/* 平成22年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h22.committeeSessions.push(...[{"id":"h22-20100628-5","meetingId":"h22-cm06","date":"2010年6月28日","dateIso":"2010-06-28","committee":"総務委員会","time":"午前１０時０２分～午後１時４３分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を45件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"土井委員","kind":"質問","question":"国の法律との関係ですから問題ない中身ですけれども、話し合いがあったのかなかったのか、どういう結果になったのかということ。昇格等に当然影響しないものということになろうと思いますけれども、そういうことも含めて職員間ではどのようなものがございましたか。","respondent":"榎本人事課長","answer":"区職労と清掃労組品川支部ともに５月１８日に協議を開始しまして、区職労は６月７日妥結、清掃のほうは６月６日妥結ということでいただいています。産休、育休、それらについての不利益がないような形で運用していきたいというふうに考えています。","id":"exchange-001"},{"speaker":"本多委員","kind":"質問","question":"趣旨につきましては十分理解できます。いろいろと人との調整といいますか、そういう部分が出てくると思うんですけれども、そういう調整はどのようにされるのか説明を求めました。","respondent":"榎本人事課長","answer":"１時間、どうしても足りない場合については臨時職員という形での対応をしておりますけれども、職場内での調整で大体足りているかなというところです。育児短時間勤務の場合につきましては、繁忙期になれば臨時職員を入れる等の対応をしています。","id":"exchange-002"},{"speaker":"林委員","kind":"確認","question":"ちょっと確認しておきます。あるいは家庭の事情でやむを得ず介護休暇というのもとっていくという仕組みがあったらいいなという人は多いわけですから、その辺はいかがか尋ねました。","respondent":"榎本人事課長","answer":"今までの説明の部分は、民間企業もこれに準じて努力義務が課せられているという形の部分と、義務が課せられている部分と両方入っております。これから出す予定でおりますし、１２月のときに勤務条件、区民に対して公表するというような形をとっているところです。","id":"exchange-003"},{"speaker":"林委員","kind":"質問","question":"育児休業に関して計画書というのは、例えばどういうことを記述するようになっているのか。それだけちょっと参考に説明を求めました。","respondent":"榎本人事課長","answer":"それから、再度の請求予定期間、いつからいつまでというのを出せる形。今回の改正で、請求にかかわること、請求の期間というものがこの計画書という形で入ってくる形に用紙のほうは改正されるということです。","id":"exchange-004"},{"speaker":"林委員","kind":"意見","question":"どういう子どもに育てようかとか、そうじゃないわけですね。わかりましたとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-005"},{"speaker":"宮崎委員","kind":"質問・要望","question":"第５３号議案のところでは、制限等のところで、この判断をどういうふうにやるのかなということを聞かせていただきたい。先ほど、そういういわゆる代替措置が支障があるかないかということに入ってくるのかどうなのかというところもまずお伺いしたいと思います。","respondent":"榎本人事課長","answer":"やはり厚生労働省関係のものについては、実際には区としてこの中小企業に対してどうするというのは動きができないというふうに認識しております。その段階で臨時職員、もしくは非常勤職員等の任用ができるかどうかを判断した上で…","id":"exchange-006"},{"speaker":"宮崎委員","kind":"質問","question":"２点目のほうは、それができるかどうかというところが免除、あるいは制限できるかどうかという判断にもなるということですか。臨時職員を採用しますとかということも、とれる条件になってくるのかということなんですけれども、そのことを伺いたいんです。","respondent":"榎本人事課長","answer":"その部分は、直接はその職員に超過勤務をさせないことの条件にはなっておりません。そういうものを含めて、どうしても応援体制が組めないという形であれば、臨時職員をとって対応するという形です。","id":"exchange-007"},{"speaker":"宮崎委員","kind":"意見","question":"わかりました。説明書類のこの２ページ目の（４）のところ、そういう場合でも、ここのところはどういう理由なのかということを聞いておきたいと思うんですけれどもとの意見を述べました。","respondent":"榎本人事課長","answer":"もともとは１ページの（１）のところで、２人、逆に取消事由としては規定としては要らないという意味で外したというものであります。","id":"exchange-008"},{"speaker":"宮崎委員","kind":"意見","question":"済みません、ちょっと私の聞き方がよくなかったんですけれども、要するに、両親で、今までは育児に欠けるといいますか、そういう条件だったのが、今は両方でもいいですよというふうになってきた、この考え方というか、そこのところをちょっと聞いておきたいなと思っていたんですとの意見を述べました。","respondent":"榎本人事課長","answer":"その考え方の部分は、少子化対策の観点から、やはり仕事と子育ての両立支援を一層進めたいということで。育児をとにかく優先しましょうという形のものが入ってきているというものです。","id":"exchange-009"},{"speaker":"須貝委員","kind":"確認","question":"対象が負傷、これは介護休暇の新設ということですから、あくまで介護認定は受けていなければいけないということなんでしょうか。それに対してきちんと審査部門があるのかどうかというのを、その辺についてちょっと確認と質問をします。","respondent":"榎本人事課長","answer":"これについては、基本的には介護認定でもって、老齢により２週間以上支障があるということの判断をしていきたいというふうに考えております。有給ということになっておりますので、その証明をとった上でこの休暇の取得についての判断をしていきたいというふうに考えています。","id":"exchange-010"},{"speaker":"須貝委員","kind":"質問・要望","question":"本当にもう１から１００まで千差万別で、その辺をきちんとした線引きというんですか、不公平感がないような対応はしてほしいと求めました。一応そこで終わります。","respondent":"榎本人事課長","answer":"その第１６条の６で、労働者からの前条第１項の規定による申出があったときは、介護の部分については強制力があるです。済みません、訂正します。","id":"exchange-011"},{"speaker":"堺委員","kind":"質問・要望","question":"確認で何点か教えていただきたいのですけれども、第５３号議案で、そういう考え方が今回反映されているのかなと。だけど、実態的にはなかなかそれは難しいのではないかということなのか、その辺はどうなんか尋ねました。","respondent":"榎本人事課長","answer":"昔、実際に介護が始まって１カ月とか２カ月とか続くという見込みの段階で、自分はもう職を続けるか続けないかという判断を迫られておりました。実際には有給の５日を見た後、核家族化による介護ということで…","id":"exchange-012"},{"speaker":"林委員","kind":"確認","question":"ごめんなさい、二度目になるんだけれども、確認だけ。そうすると、東京都もそうか尋ねました。","respondent":"榎本人事課長","answer":"産休育休代替職員ということで、たしか採用をしているということなので、丸々１日をとる場合についてはその対応ができる。どう対応するかということですけれども、非常勤講師等の採用もしておりますので、そういうもので足していくのかなという形で考えております。","id":"exchange-013"}]},{"id":"topic-02","title":"４番目、第５６号議案、品川区特別区税条例の一部を改正する条例","agenda":"４番目、第５６号議案、品川区特別区税条例の一部を改正する条例","exchanges":[{"speaker":"土井委員","kind":"質問・要望","question":"あなた、いっぱいもらっているのねという話等になってしまうことを嫌う方がいらっしゃるようですので、ぜひその辺はご配慮をいただきたい。極端な言い方をしたら、税金のほうがかなり多いので、普通徴収を選択できるということを相当しっかりやってほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-014"},{"speaker":"本多委員","kind":"質問","question":"４番目なんですけれども、平成２４年から平成２６年ということで、施行日が平成２５年なんですけれども、それまで２年半ぐらいあるんですけれども、それは周知期間と考えればいいのか尋ねました。","respondent":"武内税務課長","answer":"本則は２０％、住民税を足して２０％とお話ししましたけれども、１０％という軽減税率を行っているんです。その期間がこの平成２３年度までありますので、当然、株取引をされる方に周知は当然この段階からされるのかなというふうに思います。","id":"exchange-015"},{"speaker":"林委員","kind":"質問・要望","question":"なぜ、何かでやらなくてよかったから放っておいたんだというふうに聞こえたんだけれども、もう１回この部分を説明していただきたい。ですから、１番と４番と５番、お願いいたします。","respondent":"武内税務課長","answer":"先ほど説明したとおり、今回、この定例会の説明の中でご理解いただきたいということで提案をさせていただいたものであります。概要の１ページ目の扶養控除全体の図についてのご説明ですけれども、子どもからお年寄りまで、それぞれの年齢に分けて控除があります。","id":"exchange-016"},{"speaker":"林委員","kind":"質問・要望","question":"きちんとこういうことだから６月１日を過ぎているけれども法改正をするんだという理由がなければ、その辺はきちんと区民に伝えてほしい。言ってみれば納税者はスポンサーですから、その辺はもう一度整理して説明をほしいと求めました。","respondent":"市岡総務部長","answer":"この租税条約実施特例法の関係は、いわば国の都合で法律の名称を変更したことに伴う規定整備を条例のほうがその影響を受けたということでして。本来やるべきだったものを怠けたとか、そういうことではありませんので、ご理解いただきたいと思います。","id":"exchange-017"},{"speaker":"宮崎委員","kind":"質問","question":"まず１番のところは、今回は、非課税限度額活用のために扶養控除等の届出を義務づけるということだけだということなんですね。平成２４年から２０％に本則に戻るということで、これによって区の税収への影響というのはどういうふうに出ているのか伺いたいと思います。","respondent":"武内税務課長","answer":"ですから、今回は直接区税条例の廃止ではありませんけれども、特別区民税の部分で改正された大きな部分ですので、この説明をさせていただきました。区にどの程度こういうシステムをつくることによって増収が見込まれるかという部分については把握できないという状況ですので…","id":"exchange-018"},{"speaker":"宮崎委員","kind":"質問・要望","question":"例えば、昨年、その前とか、本来の本則との関係でどのぐらい影響があったんだという、過去の実績なんかではわかるのでしょうか。そういうことできっと何か、過去の２０％を１０％に減らした影響の実績なんかがわかったら、ちょっと参考に聞かせていただきたいんですけれども。","respondent":"武内税務課長","answer":"それで、額にして、所得割が約５億７,０００万円という区税収入としての取り扱いをしております。こういう数字でしたら区のほうで押さえております。","id":"exchange-019"},{"speaker":"宮崎委員","kind":"質問・要望","question":"わかりました。２番の６５歳のところなんですけれども、対象人数がどうなるか想定している人数があったらお聞かせいただきたいんですけれども。","respondent":"武内税務課長","answer":"２年前に公的年金の特別徴収が開始されたときには、約２万５,０００人、公的年金受給者がおりました。その中で６５歳以上の方については約１万５,０００人ということですので、これがすべてということではありません。","id":"exchange-020"},{"speaker":"堺委員","kind":"質問・要望","question":"理解を深めるために確認をしておきたいのは、１ページ目の特別区民税・都民税の扶養控除の全体図という、これが廃止になります。その辺をもう１回整理する意味で教えていただけますか。","respondent":"武内税務課長","answer":"今回のこの地方税法の改正に当たっての国からの説明では、委員言われるとおり、子ども手当の創設の財源に充てるということ。特定扶養控除の上乗せ分については、高校無償化の財源に充てるということでの説明で区にほうには来ております。","id":"exchange-021"},{"speaker":"堺委員","kind":"確認","question":"そうなると、いつだったか新聞か何かの報道等によると、そういう理解でよかったですか。ある階層の人、それを確認しておきたいんですが、いかがか尋ねました。","respondent":"武内税務課長","answer":"ただ、特定扶養控除の上乗せ部分については、高校の無償化という名目で行いますけれども、高校に行かれていない方もいるのかなと思います。無職で仕事を求職中だったりしますと、その辺の増税というか、そういう方については影響が出るのかなというふうには考えられます。","id":"exchange-022"},{"speaker":"宮崎委員","kind":"提案","question":"実際に品川区の条例をどうするかということで提案が出てきていますので、そういうことであれば、反対しなければいけないというふうに考えます。ですから、これは私は賛成できないと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-023"}]},{"id":"topic-03","title":"５番目、第６３号議案、（仮称）品川地区小中一貫校新築外構その他工事請負契約","agenda":"５番目、第６３号議案、（仮称）品川地区小中一貫校新築外構その他工事請負契約","exchanges":[{"speaker":"林委員","kind":"意見","question":"５ページの図の中で、今現在どういうことに、区と第一三共との間の話はどういうふうになっていますかとの意見を述べました。","respondent":"本間副区長","answer":"この土地を区に売却するといった場合には、先般、一応売却の方向で会社の内部では方向性は固まったというお返事はいただいてあります。私どもとすれば、できるだけ早くこの土地を入手したいということで、強く今後も向こうと折衝をしていきたいというふうに考えているところです。","id":"exchange-024"},{"speaker":"林委員","kind":"質問","question":"この図面の一番上にある品川神社とのがけっ縁の問題が最初のころから出ていたんですけれども、その辺の解決はされているんですか。２つ説明を求めました。","respondent":"宍戸施設整備課長","answer":"はブリッジで３階部分でつなげますので、横断については今までよりも安全にそれぞれに棟をつなぐことができるというふうなことになっております。基本的には全面的に校舎棟の部分の北側の擁壁についてはやり替えますので、安全性については確保を…","id":"exchange-025"},{"speaker":"林委員","kind":"質問","question":"外構工事をする上で、せっかく一体型一貫校をつくるということですから、それは強く言っておきます。これから正確な設計がなされていくと思うので、その中で相手側に伝える、あるいは工事業者に伝えるということをお願いしておきます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-026"},{"speaker":"須貝委員","kind":"質問","question":"１点だけちょっとお聞きしたいんですが、この工事が工期が平成２４年３月９日という工期になっております。平成２２年６月の時点で、予定が立てばどんどんこういうふうに外構工事等の入札も決めて進んでいくような、そういう手法をとるのか尋ねました。","respondent":"宍戸施設整備課長","answer":"連携を密にして、なるべくむだがないような打ち合わせをした上で双方工事を進めるという意味で、だいぶゆとりをもった発注にしています。なるべく早く外構工事の工事業者を決めて、打ち合わせを密にしながら進めるというふうな形に持っていきたいというふうに考えてあります。","id":"exchange-027"},{"speaker":"宮崎委員","kind":"意見","question":"実際に小中一貫校がこうやって図面が出てきているわけですね。どっちにどういう責任が出てくるのか、そこのところを、今回はどういう考え方で行くのかということを聞いておきたいと思いますとの意見を述べました。","respondent":"本間副区長、宍戸施設整備課長","answer":"１点目の隣地の第一三共の件ですが、交渉に当たっている、このような経緯です。 がけ部分のどちらが工事をするのかということですが、基本的には、がけの所有者が所有の部分について安全確保を図るというのが基本です。外構工事ではなくて、北側のがけの部分については…","id":"exchange-028"},{"speaker":"宮崎委員","kind":"意見","question":"１点目のほうですけれども、例えば運動会なんかも狭いんじゃないかとか、そういうことがいろいろ指摘されてきたんですね。小中一貫校については、子どもたちの目線でやっていってほしいということを強く望みたいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-029"},{"speaker":"堺委員","kind":"質問・要望","question":"（５）で駐輪場の整備工事で２２台、６番目に駐車場の整備工事で一般用が５台で車椅子用２台、これはどこに設置する予定なんですか。どうも右端の歩道状整備工事の上の通用門という上のところに、それも含めて、図に書かれていないので教えておいてほしいと求めました。","respondent":"阿部経理課長、宍戸施設整備課長","answer":"価格の点ですけれども、予定価格については、事前公表しております。委員ご指摘の３番目の会社、それは自社で積算した結果、予定価格を上回るということでしたので辞退というように聞いております。 上から２つ目の四角の地域開放入口とありますけれども、この左側に駐輪場用の線が入っていると思いますが、これが学校用の駐輪場１２台です。この文字の右上の部分に駐輪場用に区切られた部分があると思いますが…","id":"exchange-030"}]},{"id":"topic-04","title":"の荏原第六中学校改築給排水衛生設備工事請負契約を一括して議題に供します。 これら３議案、および報告事項につきましては、いずれも関連する内容ですので、一括して説…","agenda":"の荏原第六中学校改築給排水衛生設備工事請負契約を一括して議題に供します。 これら３議案、および報告事項につきましては、いずれも関連する内容ですので、一括して説…","exchanges":[{"speaker":"林委員","kind":"確認","question":"ちょっと確認だけです。フジコウ、同じ名称の会社が違う工事に入札しているんですけれども、これは同じ会社なんか尋ねました。","respondent":"阿部経理課長","answer":"６ページの冨士工と、今、委員ご指摘の１７ページの不二工は別会社です。","id":"exchange-031"},{"speaker":"林委員","kind":"質問","question":"別会社だけれども、名称、企業名は全く同じ企業名、省略されている部分があるのか。例えば、フジコウ建設株式会社とか、フジコウ電設株式会社とか、全く違う会社なんか尋ねました。","respondent":"阿部経理課長","answer":"今申し上げたように全く別会社です。","id":"exchange-032"},{"speaker":"林委員","kind":"意見","question":"それ以外に１７ページの空気調和設備工事、１９ページの電気設備工事、辞退する会社が出ていないんですよね。この辞退された理由というのは、区ではわかっていらっしゃいますかとの意見を述べました。","respondent":"阿部経理課長","answer":"建築工事の辞退ということですけれども、契約に至るまでの経過なんですけれども、予定価格をまず公表いたします。そのときに、この予定価格を結果として上回ってしまったので辞退したというふうに聞いています。","id":"exchange-033"},{"speaker":"林委員","kind":"質問","question":"６件、落としたところの率は１件だけパッとこういうふうに計算すればすぐ出てくるんだけれども、できれば入れてください。それは可能か尋ねました。","respondent":"阿部経理課長","answer":"ただ、ここに書くのがよろしいのか、あるいは私が説明するときに、一応、手持ちでは持っておりますので、説明をいたします。報告事項の給排水衛生設備工事、これにつきましては９６.９％です。","id":"exchange-034"},{"speaker":"林委員","kind":"意見","question":"は６ページに至っては９９.３％というのは、その辺のことについての状況を区としてはどういうふうに見ているのか、答えられる範囲で答えてくださいとの意見を述べました。","respondent":"阿部経理課長","answer":"この中で電気だけが８３.７％ということですけれども、電気につきましては、建築とかほかの設備に比べて格付がＡという会社がかなり多い。８５％近くの落札率ですので、私どもとしては、適切な契約の状況の範囲内だろうというふうに思っています。","id":"exchange-035"},{"speaker":"林委員","kind":"質問","question":"パーセンテージで言えば８０％台に入っていくほうが望ましいというふうに感じるんですけれども、もう終わった数字を見ながらそう感じます。中学校というのは４階建てというのが１つのならわしというか、この５階校舎というのは、法的には問題ないんか尋ねました。","respondent":"宍戸施設整備課長","answer":"保育園、小中学校につきましては、基本的には５階建ては問題ないというふうに聞いております。普通教室は４階までにおさめておりますので、どうしても５階建てにせざるを得なかったということでこういう形になったというふうに聞いております。","id":"exchange-036"},{"speaker":"林委員","kind":"質問","question":"１１ページの真ん中にエレベーターがあるんですけれども、５階という建物で行くと、使えるようになるのでしょうか。それとも、上のほうに地域への開放する部分があって、エレベーターを設置してあるんだということになっているのか尋ねました。","respondent":"宍戸施設整備課長","answer":"エレベーターは、では、どういうときに使うかということですが、まず１つは、身障者対応ということです。そういうふうな方々への対応。","id":"exchange-037"},{"speaker":"林委員","kind":"意見","question":"その辺が私にはどういう指導をして子どもたちを誘導するのかというのか、それから、その辺をちょっと明確にしてほしいなと思う。おまえはいいよというようなやり方をするのは、そぐわないような気がするので、そういう気持ちを持っている人間もいるというのだけ伝えておきますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-038"},{"speaker":"宮崎委員","kind":"質問","question":"９９.３％、区側の積算と今回の辞退が２社出てきたわけですけれども、どういうふうに見ているのかということを聞きたい。区のほうはどういうふうに考えているのか伺いたいと思います。","respondent":"阿部経理課長","answer":"辞退の傾向というお話ですけれども、私としては、辞退が増えている、以前に比べて極端に増えているというふうには考えてございません。それ以降は、委員おっしゃるように、その積算がおくれているから辞退に立ち至ったんだというような傾向はないというふうに見ています。","id":"exchange-039"},{"speaker":"須貝委員","kind":"質問","question":"給排水なら給排水、外構なら外構ということは、きちんと連携をもって行われているのでしょうか。それとも、いや、ほぼ同じぐらい確保しましたよということなのか、その２点について説明を求めました。","respondent":"宍戸施設整備課長","answer":"それぞれにどういうふうな連携をもってきちっと進めるかというのは、また、連携してきちっとやっているというのが基本です。ただ、狭いながらも使いやすい校庭というふうなことで、狭い敷地の中で精いっぱい考えた上でのことだと理解しております。","id":"exchange-040"},{"speaker":"須貝委員","kind":"意見","question":"どうしても最終段階においてちょっとちぐはぐな、組み立てながら、それぞれ臨機応変に微調整するというのはよくわかります。できる限り目を光らせていただいて、よりよい学校改築、建築を今後も進めていただけたらありがたいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-041"}]},{"id":"topic-05","title":"９番目、第６７号議案、平机他の買入れ","agenda":"９番目、第６７号議案、平机他の買入れ","exchanges":[{"speaker":"宮崎委員","kind":"質問","question":"細かいことですけれども、この平机等々、どこのメーカーのものとかという、区のほうからどの程度まで指定するものなのでしょうか。メーカーはどこでもいいですよというふうになるんか尋ねました。","respondent":"阿部経理課長","answer":"今回の平机につきましては、愛知という会社のものですけれども、こういう物品を買う場合には、メーカー指定ということは原則行いません。標準品としてこういうものがありますという標準品目を示しまして入札にかけていくです。","id":"exchange-042"}]},{"id":"topic-06","title":"１０番目、第６９号議案、カウンター他の買入れ","agenda":"１０番目、第６９号議案、カウンター他の買入れ","exchanges":[{"speaker":"宮崎委員","kind":"質問","question":"さっきと同じように、メーカー等の指定があるのかどうなのか。今回はどうなのか伺いたいと思います。","respondent":"阿部経理課長","answer":"今回は、メーカー指定ではなくて、例えばカウンターですとサイズがありますので、そういうサイズを指定して製作、納入してもらうというようなことです。","id":"exchange-043"},{"speaker":"土井委員","kind":"意見","question":"以前使っていたものを後からまた使うというのは非常にいいことなんですけれども、そのままだと薄汚れていたりいろいろするんですが、そういうもののメンテナンスをして使うのかどうかだけちょっと聞かせてくださいとの意見を述べました。","respondent":"阿部経理課長","answer":"今回そういう書架とか机は、バックヤードのほうで使います。ですから、図書館の実際の皆さんのご利用になるところには新しいものが入るというような形になっています。","id":"exchange-044"},{"speaker":"土井委員","kind":"意見","question":"バックヤードといえども、やっぱり新しいところなので、若干の清掃費用ぐらい見込んで清掃してあげたらいいんだがなと今思いました。思いだけでいいですとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-045"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/212618?Template=document&Id=1856#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2010-01-01&TermEnd=2010-12-31"}],"sourceMeta":{"pages":0,"characters":48092,"voices":137}},{"id":"h22-20100629-6","meetingId":"h22-cm06","date":"2010年6月29日","dateIso":"2010-06-29","committee":"区民委員会","time":"午前１０時０２分～午前１１時２８分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を30件整理しています。","topics":[{"id":"topic-01","title":"を行います。 初めに、(1)の平成２２年度品川区民まつりの予定","agenda":"を行います。 初めに、(1)の平成２２年度品川区民まつりの予定","exchanges":[{"speaker":"菊地副委員長","kind":"質問・要望","question":"１つだけ教えてもらいたいんですけれども、１つの地域で１００万円ぐらいの補助金なんだと思うんですけれども、ちょっと教えていただきたいなと思うんです。","respondent":"中山地域活動課長","answer":"一律ではないんですけれども、全体として区の補助、この１,３００万円に対して総経費としては約２,０００万円ぐらいの規模でやられているようです。ですから、ほぼ３分の２が区の補助で行われているという事業とお考えいただければ結構かと思います。","id":"exchange-001"},{"speaker":"菊地副委員長","kind":"質問","question":"そうすると、各場所での事業の中身というか、催しの中身というのは違いがあって、非常に大々的なところがあったりとかあるんだと思うんですけれども、それによって、補助の分配というのは変わるんですか、ちょっとそこだけ。","respondent":"中山地域活動課長","answer":"模擬店等の売り上げとかも収入の中に入ってまいりますから、約２,０００万円近くの総事業費ということで、若干補足します。一番大きな地区ですと、１１０万円強という形で、規模に応じた分配をしているということです。","id":"exchange-002"},{"speaker":"石田委員","kind":"質問","question":"１点お伺いしたいんですけれども、区民まつりに人が大勢行ったときの問題点の１つとして、どのような協力体制をとっているのかと。問題点のもう１つが、トイレのほうはどうしても、区としてその辺の対応はどのようにされているのかをお伺いしたいと思います。","respondent":"中山地域活動課長","answer":"これは分配型になっておりますから、基本的には難しいというか、そういう補助の扱いにはなっておりません。区として当然支援していくという考え方をとっておりますから、連携・協力というか、実行委員会の支援をしていきたいと考えております。","id":"exchange-003"}]},{"id":"topic-02","title":"の品川区民まつりにおける国際交流事業の紹介","agenda":"の品川区民まつりにおける国際交流事業の紹介","exchanges":[{"speaker":"山路委員","kind":"質問","question":"昨年、横浜の開港１５０周年で、山下公園で国際交流事業をやられて、現地の人が、現地の食べ物とか、飲み物を安く販売しているんです。そういう支援をしたらどうかと思うんですけれども、今後そこまで計画したらどうかと思うんですが、どうか尋ねました。","respondent":"秋山協働・国際担当課長","answer":"そのような形で、徐々にいろいろな形で外国人の方が区民まつりに参加していただけるように、努力してまいりたい。八潮の区民まつりですけれども、連携して八潮のお祭りでやったこともございました。","id":"exchange-004"},{"speaker":"山路委員","kind":"意見","question":"ケーブルテレビを見させていただいたんです。比べるわけではないんですけれども、やっぱりまちの活性化につながっていくような工夫に対する支援をお願いしたいということで意見ですとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-005"}]},{"id":"topic-03","title":"の防犯設備整備助成事業における今年度の取り組み","agenda":"の防犯設備整備助成事業における今年度の取り組み","exchanges":[{"speaker":"菊地副委員長","kind":"質問","question":"１つお聞かせ願いたい。３つの町会についてカメラの設置があったと今、町会からそういう声は出ていないんでしょうか、そこを。","respondent":"矢部生活安全担当課長","answer":"ご指摘のとおり、ランニングコストというのが今非常に問題になっているんですけれども、現在３町会でつけたところですが、今のところランニングコストについて、町会のほうからその事業について補助をしてほしいというご要望はありません。","id":"exchange-006"},{"speaker":"菊地副委員長","kind":"質問","question":"今までと同じように、ランニングコストについては商店街と町会でもっていくという、従来と変わらない形式なんか尋ねました。","respondent":"矢部生活安全担当課長","answer":"はい、従来どおりということになります。将来的な費用負担も考えまして、その５年間の範囲内で町会、または商店街が負担できる範囲内で事業を展開されているということで認識しております。","id":"exchange-007"},{"speaker":"菊地副委員長","kind":"質問","question":"今の５年間というのは、どうして５年間なんですか。５年と言わず、将来的にも、ランニングコストそのものとして助成していこうというところは考えていないということなんか尋ねました。","respondent":"矢部生活安全担当課長","answer":"最低限５年間見守り活動を継続するということになっておりますので、５年間と言ったのは、あくまで補助の要件ということで説明させていただきました。私も担当のほうにランニングコストということを東京都の担当者に説明して、区ではつけられないという部分もありますので…","id":"exchange-008"},{"speaker":"山内委員","kind":"質問・要望","question":"防犯カメラのことについて伺いたいんですけれども、防犯カメラというのは、夜もちゃんと映るタイプなのか、その辺をちょっと教えてください。この３町会は今、ご存じであれば、教えていただきたい。","respondent":"矢部生活安全担当課長","answer":"防犯カメラを設置する場合には、犯罪が起きた、この辺につけたほうが効果があるんじゃないかということで話し合いをしているところであります。それと、町会の台数ですけれども、３３台つけております。","id":"exchange-009"},{"speaker":"山内委員","kind":"質問・要望","question":"夜間鮮明に映るカメラだとちょっとお高くなるということになると、ある意味、抑止力的な部分でカメラをつけると。抑止力的なカメラというのも何となく必要になってくるのかなというところはあるんですけれども、その辺についてお考えがあれば、教えていただきたい。","respondent":"矢部生活安全担当課長","answer":"防犯カメラを設置した町会なんですけれども、私の知っている事例ですと、町会の名前と地元警察の連名で防犯カメラ設置中という看板をつけている。だから、防犯カメラをただつけるだけではなくて、設置中という看板をつけて抑止を図っているというところがあります。","id":"exchange-010"},{"speaker":"石田委員","kind":"意見","question":"ちょっと聞いた話だと、東京電力とか、電柱に設置する場合があると。そういった点というのは、区としてどのように考えていて、どのような支援体制をされているのかというのを説明を求めました。","respondent":"矢部生活安全担当課長","answer":"町会が防犯カメラを設置するというのは、設置場所という非常に難しい点、基本的には町会の防犯カメラを設置してある場所は。","id":"exchange-011"},{"speaker":"石田委員","kind":"意見","question":"わかりました。もし、相談があったときには、できる限りのことをしていただければというお願いですとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-012"},{"speaker":"高橋委員","kind":"質問","question":"町会で、例えば、大井三ツ又だと１０台とあるんですけれども、これで幾らぐらいなのかというのをちょっと知りたいんです。もう１つは、課を越えて、そういうところで補助事業ができる可能性はないのか尋ねました。","respondent":"諸岡商業・観光課長、矢部生活安全担当課長","answer":"基本的にハード整備ということで、これまで商店街が防犯カメラを設置するような場合には、この中での支援をさせていただきました。ただ、商店街の負担が３分の１ということでやっておりますけれども… 大井三ツ又商店街の費用ですけれども、区と事業者それぞれ９８万円ずつの事業となっております。","id":"exchange-013"}]},{"id":"topic-04","title":"の五反田文化センターのリニューアルオープン","agenda":"の五反田文化センターのリニューアルオープン","exchanges":[{"speaker":"石田委員","kind":"質問","question":"例えば、そういうときには五反田駅からバスを出すとか、交通の部分で何か対策が必要なのかなと思うんです。そういった連携とかというのは、１つの方法なのかなと思うんですが、その辺の交通手段をどのように考えているのかをお伺いします。","respondent":"堀越文化スポーツ振興課長","answer":"大崎広小路で１０分、不動前ですと７分という形で、駐車場等をご利用いただくと考えております。今お話のあったバスというような形については現在のところ考えてございません。","id":"exchange-014"},{"speaker":"石田委員","kind":"質問・要望","question":"そういった中で、先ほど駅から何分という話が出ましたけれども、それはあくまで普通の人が歩いてそのぐらいなのかと。せっかくすばらしいホールができるわけですから、そういった部分の支援策というのも今後検討していただければと、これは要望です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-015"},{"speaker":"山路委員","kind":"質問・要望","question":"新しく生まれ変わって、私もちょっと聞き逃しているかもわからないので、教えていただきたいんですけれども、料金体系というのは、旧の料金のままで新しいところを使えるんか尋ねました。","respondent":"堀越文化スポーツ振興課長","answer":"使用料の考え方としては、新しくなったから、その分の金額を上乗せするということはございません。","id":"exchange-016"},{"speaker":"山路委員","kind":"質問","question":"出ていないので、そのままかなと思って、今お伺いしたんです。もう１回質問。","respondent":"堀越文化スポーツ振興課長","answer":"基本的な考え方、平米の基礎数値というのは、ほかの文化センターと同じ数値です。１,９００円ですとか、１,４００円ですとか、そういった形でほかの文化センターと同様の使用料の設定になっております。","id":"exchange-017"},{"speaker":"菊地副委員長","kind":"意見","question":"改築前の２倍の規模になるということで、この辺の、そもそもが委託という形式なんですよね。その辺の変化はこれから出てくるのかどうか、そこをお聞かせ願えますかとの意見を述べました。","respondent":"堀越文化スポーツ振興課長","answer":"一緒に見ていただけるというところも考えて、指導課とも連携して、できるだけご利用いただきたいと準備をしているところです。運営に当たっては、専門的な知識が必要になりますので、そういった専門事業者に委託をする予定です。","id":"exchange-018"},{"speaker":"菊地副委員長","kind":"質問・要望","question":"専門業者に委託する予定、これまではどうだったんですか。その辺の流れを教えていただきたいのと、どういう位置づけだったのか、変わっていくのかどうかというところもちょっと。","respondent":"堀越文化スポーツ振興課長","answer":"施設のメンテナンス等はもちろん委託をしていたんですが、今回施設のメンテナンスと日常の説明については、あわせて委託により行います。指導課とも連携して、基本的には４年生前後という形で考えていまして、そういう内容を形にして作成しています。","id":"exchange-019"},{"speaker":"菊地副委員長","kind":"質問","question":"それと、さっきの管理の話なんだけれども、私が認識不足なのかもしれない。今まで全く別にやっていらしたものを、今度は一括して委託の事業者に要請していくという感じなんですか、そこをもう少し。","respondent":"堀越文化スポーツ振興課長","answer":"それから、日々の投影の解説とあわせて、それらをグループ化して委託をするものです。","id":"exchange-020"},{"speaker":"菊地副委員長","kind":"意見","question":"そうすると、委託費そのものをまたこれから見直さなければならないとかが出てくるのかなと思うんです。一定程度、その辺の成果ができているということであれば、最後にその辺のことも聞かせていただけますかとの意見を述べました。","respondent":"堀越文化スポーツ振興課長","answer":"ほかの施設での子どもたちに対する投影の解説業務、そういった経験を踏まえて選定した専門業者に委託をすることになっております。いろいろ注文を出して、しっかりいいものにしていきたいと思っていますので、その点は我々もしっかりやっていきたいということです。","id":"exchange-021"}]},{"id":"topic-05","title":"の武蔵小山創業支援センターの開設","agenda":"の武蔵小山創業支援センターの開設","exchanges":[{"speaker":"石田委員","kind":"質問","question":"初めに、この新センターは管理運営を委託されると思うんですが、その体制はどのようになっているのか、１点まずお伺いしたいと思います。","respondent":"福島ものづくり・経営支援課長","answer":"それ以外にアルバイトを予定しておりまして、アルバイトが朝の開設時間の７時から１０時までです。それ以外に、インキュベーションマネージャーといいまして、専門的な施設指導、助言等を行ってもらう方が１人常時つくという予定です。","id":"exchange-022"},{"speaker":"石田委員","kind":"質問","question":"常設の方が１名と専門的なご指導をされる方が１名、例えば、この管理運営会社がどこまで管理運営をしていくのか。そういった管理をしていただくのがまず１つだと思うんですが、その辺が１点と、その辺をまず２点お伺いしたい。","respondent":"福島ものづくり・経営支援課長","answer":"入る予定の入居者に対する運営の補助といいますか、それはこちらの本来業務の一つでもありますので、しっかりやっていただく予定です。それ以外に、セミナーですとか、講演会、イベント等の開催等も行っていく予定になってあります。","id":"exchange-023"},{"speaker":"石田委員","kind":"質問・要望","question":"区の施設ですし、管理運営を委託はしているんですが、できる限り区のほうもしっかりとした対応をしてほしいと求めました。それが１点と、今後どういう相談業務をこの中で行っていこうとしているのか、お知らせほしいと求めました。","respondent":"福島ものづくり・経営支援課長","answer":"ただ、どういった方向でできるか、その団体の事情にもよると思いますので、その事情に合わせたベストな形にしていきたいと考えています。そのような仕組みを考えていきたいと思いますが、その辺のところは団体と詰めながら、決めていきたいと考えています。","id":"exchange-024"},{"speaker":"石田委員","kind":"質問・要望","question":"ある一定の部分はもう、ここは創業支援センターですから、必要な部分というのは幾つかあると思うんです。その辺のやり方というのは、どういうふうにやろうとしているのか、そこの１点だけ最後にお尋ねしたい。","respondent":"福島ものづくり・経営支援課長","answer":"相談アドバイザーの登録の件ですけれども、確かにそういうことで進めているものもあります。先ほど出ていました各団体との連携による支援ですとか、また、運営会社のほうとも連携して発展のために進めていきたいと考えています。","id":"exchange-025"},{"speaker":"菊地副委員長","kind":"質問","question":"西大井と天王洲で創業支援をやってきて、今後３カ所目になるんです。これまでの成果みたいなものはどういうふうに見ておられるのか、ちょっと教えていただけますか。","respondent":"福島ものづくり・経営支援課長","answer":"成果ですけれども、当然十分な成果をおさめていると思いますし、また、利用率についても、ほぼ１００％に近い利用率です。そういうものも複数見られていますので、十分な成果を踏まえ、今後もこういった対策を進めていきたいと考えています。","id":"exchange-026"},{"speaker":"菊地副委員長","kind":"質問","question":"これまで区内製造業の支援をしてきたと。私なんかから見れば、十分商売としてやっていけるのかなという感じがしてしまうんですけれども、この辺の選定基準とか目標というのは何なんか尋ねました。","respondent":"福島ものづくり・経営支援課長","answer":"独立を考えた場合、こういったことが必要で、こういう施設も必要であろうです。そういったことも想定しまして、女性の起業家ですとか、そういう方についても支援していきたいと考えています。","id":"exchange-027"},{"speaker":"菊地副委員長","kind":"質問","question":"区内に税理士はたくさんいらして、わざわざ税理士にこのオフィスを貸して支援をしていくという、その辺の理由がどうもよく見えてこないんです。区内にたくさんいらっしゃるであろう税理士をわざわざ区として支援するということになりますから、その辺をもう少し具体的に教えていただけませんか。","respondent":"福島ものづくり・経営支援課長","answer":"会社に入って、社員として働くというのも一つの働き方なんでしょうけれども、個人事業者としてひとり立ちしていきたい。初めの段階では顧客は一切ございませんので、そういう形で進めていきたいという熱意がございましたので、今回選定した次第です。","id":"exchange-028"},{"speaker":"菊地副委員長","kind":"意見","question":"お金がないというのはみんな当たり前ですよね。資格を持っていようと、若い人たちにはお金がないというのは、ただ、区としてきっちりした位置づけがあるのかどうかということなんですとの意見を述べました。","respondent":"福島ものづくり・経営支援課長","answer":"わざわざ税理士枠があるということではございませんで、たまたまサービス業の一つとして、税理士業を営みたいという方の応募があったです。同様にほかの業の方がここでまず創業したいということであれば、当然ながら、その審査対象になろうかと思います。","id":"exchange-029"},{"speaker":"菊地副委員長","kind":"質問","question":"税理士という職業を品川区の施設の中で育成をしなければならないという理由のところを私はお聞きしているんです。最後にここをもう少し、区の方針を含めて、ちょっとお話しいただけませんか。","respondent":"福島ものづくり・経営支援課長","answer":"方針としましては、武蔵小山につきましては、女性起業家ですとか、子どもをお持ちの方、子育て中の方を中心とする起業家を育成していこうと。やはり大きな意味でサービス業を選んでいくということで考えてございまして、翻訳もそうですし…","id":"exchange-030"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/397696?Template=document&Id=2584#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2010-01-01&TermEnd=2010-12-31"}],"sourceMeta":{"pages":0,"characters":25963,"voices":106}},{"id":"h22-20100629-7","meetingId":"h22-cm06","date":"2010年6月29日","dateIso":"2010-06-29","committee":"厚生委員会","time":"午前１０時０１分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を22件整理しています。","topics":[{"id":"topic-01","title":"平成２１年度品川区介護保険制度の運営状況","agenda":"平成２１年度品川区介護保険制度の運営状況","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"両方合わせても減っている数字なので、この辺が予防給付が始まったその効果なのかということもちょっと含めて見解を伺いたいというのが２つ目です。これは平成２１年度から、６５歳以上の方には払っている保険料から使われるわけですから、ちょっとその辺を教えてほしいと求めました。","respondent":"冨岡高齢者福祉課長","answer":"すべてのそういう審査の結果そういうふうになったということしかちょっと説明がつきませんで、当然、私はないと考えています。申請をされた方の身体の状況によって、介護の必要性によって変わっていくものだ、数字は動くものだと認識しています。","id":"exchange-001"},{"speaker":"南委員","kind":"質問・要望","question":"それは大事ですから、その点についての見解と、通院等の外出介助サービスは必要だと思うんですよ。品川区は保険料、やっぱり２年後の保険料改定のときにどういうふうにこれが出てくるかは非常に心配なところですから、これはやめるべきだと。","respondent":"冨岡高齢者福祉課長","answer":"分析をして説明できる範囲は、説明をしたとおりでございまして、これが今のところの結果であるとご理解いただければありがたいと思います。その中で私どもはどう対応していくかというところを考えた場合には…","id":"exchange-002"},{"speaker":"南委員","kind":"質問・要望","question":"改善を求めるという、改めてそういうことを求めていきたいというふうに、要望として伝えていきたいと思います。何かもし反論的なものがあれば、ぜひ伺いたいと思います。","respondent":"木下健康福祉事業部長","answer":"コンピューターシステムを変更しましたけれども、マニュアルの変更が一番影響が大きかったわけですが、そのときですら。要介護の方々ということで考えていきますと、追加資料で入れています６の２ページのほうの特定施設が非常に数が伸びているということであります。","id":"exchange-003"},{"speaker":"南委員","kind":"質問","question":"例えば、先ほどもちょっと主張してきましたけれども、次期の保険料の改定のときにかなり苦労があると思うんですよね。そういうところで高齢者の第１号被保険者の保険料の負担との関係では、では、どういうふうに考えればいいんか尋ねました。","respondent":"木下健康福祉事業部長","answer":"いろいろな要因が絡んでまいりますから、課長も申し上げましたけれども、保険料への影響は結果的にそう大きくないと考えています。いろいろな要因を含めてまた再検討するわけでありますので、特別給付の組み立ても、改めて検討していきたいと考えています。","id":"exchange-004"},{"speaker":"南委員","kind":"意見","question":"知らないために使われていないとか、それを改善しながら使えるようになると、ぐっと増えていくと思うんですよ。私は改めて市町村給付は、部長は法の想定の大原則だとおっしゃったけれども、ちょっとそのことを主張しておきたいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-005"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"私も多くのケアマネジャーさんからよく伺う話なんですけれども、家族だったり、なかなか仕事量が増えてきて大変だというお話をよく伺うんですよね。要望が上がっていく、伺いたいのは、それの推移の状況をちょっとご説明いただけますか尋ねました。","respondent":"冨岡高齢者福祉課長","answer":"それが掘り起こしと言わなくても、自然の形で問題があれば、区の対応につながっていっていると理解しています。それから、ケアマネジャーの数ですけれども、ちょっと正確な数字ではありませんが、２５０名くらいと考えております。","id":"exchange-006"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"よく介護サービスを使っている方から伺う話として、僕などは伺うものですから、そもそもこの指数が何をあらわしているものなのか。もちろん、どこかの時点を１００にして今がこうだというのはわかりますけれども、この指数をどう見ているのか、そこを教えていただけますか尋ねました。","respondent":"冨岡高齢者福祉課長","answer":"利用者数が減ったですけれども、これは実施回数の関係がございまして、若干減っているという部分かなと理解をしております。回数が４回減っておりますので、ちょっと実施回数についてはさまざまな施設の状況がありまして、回数が実施できなかったということがありますが。","id":"exchange-007"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"「指数」と言うぐらいですから、今後どういうサービスが必要なのか、そこの評価を教えてほしいと求めました。これは８ページですかね、なぜこの２７人と、そこの理由をどうお考えなのかご説明ほしいと求めました。","respondent":"冨岡高齢者福祉課長","answer":"１００から増えていくという状況もあるわけですので、全体的に考えた場合に、これはある程度普通の体制で実施していると。平成１８年度につきましては、ご案内のとおり老年者の控除等でいろいろ変更があった年です。","id":"exchange-008"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"あまりにもこれでは品川区中にそれこそ６５歳以上は７万人ぐらいいらっしゃるのですか、第３段階だけでも８,０００人いらっしゃるわけですよね。別の質問なんですけれども、今の時点でどういう状況になっているのか伺いたいのは、ちょっとそこはご説明いただけますか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-009"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"本来であれば特別養護老人ホームや公的な施設にしっかり入るべきところが、残念ながらああいう施設も含まれていたという状況だと思うんですよね。要望したいのは、しっかり状況を把握していただきたいということと、ぜひご検討ほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-010"},{"speaker":"三上委員","kind":"質問・要望","question":"来られる人と来られない人とやっぱりいるわけですから、そこのところのもう少しきめ細かな要望を聞いてあげて、これが１つです。１３ページのほうの８（１）、「品川方式」というのは簡単に言えばどういうことを言っているのか、ちょっと教えてもらえませんかね。","respondent":"冨岡高齢者福祉課長","answer":"顕彰するという意味もございまして、そういう意味も含めて、もう一度検討してみる可能性はあるかなと思っているところです。地域包括支援センターを新たにつくらなくても、品川では独自の在宅介護支援システムを持っておりますというのがメーンになっていると考えています。","id":"exchange-011"},{"speaker":"三上委員","kind":"質問・要望","question":"こういうのを委員会で勉強会だなんて言うから、よほど何か体系的なものが何かあって、そういうことだったのかなと思ってちょっと伺ってみたんです。いろいろな要望がやっぱりあると思うんですよ。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-012"}]},{"id":"topic-02","title":"では、ほかになければ、以上で本件を終了いたします。 次に、（２）平成２１年度品川区介護・障害者サービス向上委員会の報告書","agenda":"では、ほかになければ、以上で本件を終了いたします。 次に、（２）平成２１年度品川区介護・障害者サービス向上委員会の報告書","exchanges":[{"speaker":"稲川委員","kind":"質問","question":"このペーパーの２のモニタリングのアンケートについてお伺いしたいんですけれども、またこの２年後になったら、今まで出たこの１,８４１件もまとめた報告書がどういう形で出てくるのかを説明を求めました。","respondent":"冨岡高齢者福祉課長","answer":"回収率ですが、６４％というのは、通常のアンケートとしては高いほうだと考えています。このアンケートを引き続き行いまして、それをもう１回検証して、その後どうするかで対応してまいりたいと思います。","id":"exchange-013"},{"speaker":"稲川委員","kind":"質問・要望","question":"まあ１００％まではいかないでも、やっぱりアンケートの手法によって全く答えとか戻り率というんですか、回収率が違ってくると思うんですよね。ぜひこれ、１回、調査とか研究をしてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-014"},{"speaker":"南委員","kind":"質問・要望","question":"それが第三者の目から見てどうなのかというところが果たしてどうなっているのかがちょっと見えなかったので、そこを教えてほしいと求めました。いろいろな問題意識をどういうふうにすくったらいいのか、その辺がどういうふうに考えていっているのかをちょっと一つ教えてほしいと求めました。","respondent":"冨岡高齢者福祉課長","answer":"いずれにしましても、サービス向上委員会の担っておりました苦情の解決の仕方のどういうふうにしたかということの検討とか、それから。すくい切れない声をどのように受けて対応するのかですけれども、それに対応できていないというような部分かと思いますけれども、ご自身も含め…","id":"exchange-015"},{"speaker":"南委員","kind":"質問・要望","question":"そういうものを設置するとか、ちょっとその辺の確認で質問したんですけれども、ちょっとその辺を教えていただきたい。そういうふうにちょっと要望、それはもう要望でいいと思いますので、言っておきたいと思います。","respondent":"冨岡高齢者福祉課長","answer":"例えば小委員会という形になりますか、あるいは専門部会となりますか、そういう一定機能を担保するような対応をしてまいりたいと思います。これはまた詳細は詰めてこれにかえたいと思っています。","id":"exchange-016"},{"speaker":"南委員","kind":"質問・要望","question":"そこの部分の自分たちみずからが検証することは大事ですから、その点についてはどういうふうな機能というかしら、それを教えてほしいと求めました。","respondent":"冨岡高齢者福祉課長","answer":"こういうものを話題にしながら、実際になされているかどうかという検討もされていると考えております。もう一つ、すみません、国の第三者評価を受けなければいけないということになっておりますので、そういう制度の中で対応できていると考えます。","id":"exchange-017"},{"speaker":"南委員","kind":"質問・要望","question":"そういうしくみをつくって苦情が１つ１つ解消されていくということのそういうしくみがあるのだということを確認できたので、ないと、一つの問題が。その辺が非常にデリケートで難しいと思っているので、できるだけそういうふうになるようにしていただきたいということを、ちょっと要望で終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-018"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"要するに「品川区標準」とはなぜつくったのか、他区とどう違うのか、そこをちょっとご説明ほしいと求めました。十分な改善や充実が私は必要だと思うんですけれども、その点、どうお考えなのかご説明いただけますか。","respondent":"冨岡高齢者福祉課長","answer":"それで、具体的に申し上げると、一定の事業者が取り組むべき一定の標準ということで設定したです。高齢であるとか、そういうものについては独自のケアマネジメントの範囲で対応できるというふうな話でありまして、多分。","id":"exchange-019"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"２対１にすべきではないかというお話もしましたけれども、この職員体制についてはどう解決すべきだと思っていらっしゃるのかを伺いたいと思うんです。寝かせきり防止だと５割ほど、５割の方が６０％から８０％ということで、そこをどうお考えなのかご説明ほしいと求めました。","respondent":"木下健康福祉事業部長","answer":"その部分で、ここのような「まだ十分ではない」という数字が出ているのだろうと思うわけであります。２.５対１ぐらい、いずれにしても介護報酬が３対１基準でやってありますから、やっぱり国の段階での検討が必要なテーマだと思っているわけです。","id":"exchange-020"}]},{"id":"topic-03","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"特養ホームの関係で要望として出したんですけれども、今の委員長の説明の中で地域包括ケアに含まれると、それはそれとしてよかったと考えています。区のほうに意思として伝えていけるような、これからの計画の中に取り入れていただきたいということをちょっとお願いさせてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-021"}]},{"id":"topic-04","title":"行政視察","agenda":"行政視察","exchanges":[{"speaker":"南委員","kind":"意見","question":"７月３日の１０時ということなので、一般的には夜かなとイメージしていたんですけれども、この時間で住民の方々は来られるのか。その辺を多分協議してこの時間を設定したのかなとは思うんですけれども、ちょっとそこだけ１点との意見を述べました。","respondent":"平澤生活福祉課長","answer":"こちらの浜川荘なんですけれども、ほとんどがＪＲアパートの方が影響を受けるということで、逆に夜ですと、ほとんど参加できなくなってしまうということで、会長とご相談させていただきましてこの時間帯で設定させていただきました。","id":"exchange-022"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/360687?Template=document&Id=3272#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2010-01-01&TermEnd=2010-12-31"}],"sourceMeta":{"pages":0,"characters":39143,"voices":69}},{"id":"h22-20100629-8","meetingId":"h22-cm06","date":"2010年6月29日","dateIso":"2010-06-29","committee":"建設委員会","time":"午前１０時０８分～午後２時１５分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を29件整理しています。","topics":[{"id":"topic-01","title":"再開いたします。 (2)区営住宅（あき家）入居予定者登録募集について 次に（２）の区営住宅（あき家）入居予定者登録募集","agenda":"再開いたします。 (2)区営住宅（あき家）入居予定者登録募集について 次に（２）の区営住宅（あき家）入居予定者登録募集","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"直近の応募者というんですか、登録者というんですかね、の人数と実際に入れた人数と入れた倍率ですね。それを教えていただきたいのと、あと、あわせてあきが発生するときというのの主な理由というのはどんなことがあるのかお伺いします。","respondent":"柏原住宅担当課長","answer":"倍率ですが、登録から入居される方につきましては７倍です。東大井三丁目住宅で４件、西五反田五丁目住宅で２件、西大井六丁目第３住宅で１件の合計２３件です。","id":"exchange-001"},{"speaker":"安藤委員","kind":"質問","question":"それをお伺いします。応募しにくる区民の皆さんの声を伺っていると思うんですが、幾つか何か特徴的とか代表的な声などありましたらご紹介ほしいと求めました。","respondent":"柏原住宅担当課長","answer":"人数につきましては、平成２１年度は３２件ございました。今こういった状態なんですけれども、区営住宅等に入れますかとか、そういった個別的なお問い合わせです。","id":"exchange-002"},{"speaker":"安藤委員","kind":"質問・要望","question":"いつぐらいにどのようなやり方でどういう方を対象にというのを教えていただきたいのと、まあ、その方はご夫婦で子どもはいないんですね。それとも、まあそもそもそういう数が少ないと思うので何らかの対策が必要だと思うんですけれども、いかがか尋ねました。","respondent":"柏原住宅担当課長","answer":"まず、区営住宅等ありますので、まずは区営住宅につきましてはそういった方のためのものというふうに考えております。収入は公営住宅に入られる方よりも見込めるのではないかと思いますので、民間の住宅等々も含めながらご検討いただくべきかなというふうに思います。","id":"exchange-003"},{"speaker":"安藤委員","kind":"提案","question":"ぜひ区としていろいろそういった雇用の実態をよくつかんでいただいて、対策をとっていただければなというふうに思いますので、これは提案ですとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-004"}]},{"id":"topic-02","title":"（３）の都営住宅（地元割当）入居者募集","agenda":"（３）の都営住宅（地元割当）入居者募集","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"今回１枠だけという大変厳しいと思うんですが、この中、区としてはそういうさっきのような休日相談窓口というのはつくってやっていらっしゃるのか。やっていないとしたら、都がやっているのか、そこら辺はどのようになっているのか尋ねました。","respondent":"柏原住宅担当課長","answer":"こちらのほうは都営住宅の地元割につきましては、募集が今回、都のほうから件数が来ればですけれども、秋口にも１回ある可能性があります。件数が少ないということで、区営住宅の関係で窓口が開いておりますので…","id":"exchange-005"},{"speaker":"安藤委員","kind":"質問・要望","question":"わかりました。区として都営住宅をもっと都につくってほしいという要望をぜひ上げるべきだと思うんですが、そちらに関しての要請などはされているんか尋ねました。","respondent":"柏原住宅担当課長","answer":"募集のことですけれども、区営住宅と都営住宅、制度の違うものですので、同時に申し込みすることは可能です。都営住宅の建設等につきましては、区としまして、そちらについて何かということで申し上げることではないというふうに考えております。","id":"exchange-006"},{"speaker":"安藤委員","kind":"質問・要望","question":"これも要望なんですが、やはり窓口でいろいろな先ほども結構窓口でどのような話を聞いていらっしゃいますかということで伺ったところ。聞いているところだと思いますので、ぜひ区として区民の皆さんの願いに立って都に要請していただければという私の要望です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-007"}]},{"id":"topic-03","title":"（４）戸越幹線貯留管中流部整備工事における出水の対応","agenda":"（４）戸越幹線貯留管中流部整備工事における出水の対応","exchanges":[{"speaker":"藤原委員","kind":"質問","question":"まだ、調査の結果が出ていないので、それを踏まえての答弁でいいんですけれども、いずれこの原因、調査結果が出ると思うんですけれども、出た時点で、業者なり東京都、区も含めて工事に関してのお金という形は、調査結果によってどこが支払いなさいという形になっていくんか尋ねました。","respondent":"藤橋都市整備下水道課長","answer":"対策については直ちに着手して、一刻も早く工事を完了させたいというふうに考えておりまして、対策についてあわせて今検討しています。その中でどのような費用分担で行っていくのか、だれが負担するのかというのは、結論が出た段階で判断しないとというふうに考えております。","id":"exchange-008"},{"speaker":"藤原委員","kind":"質問","question":"東京都、業者、品川区という大きく分けて言うならば、これに関しては品川区の責任というのは、調査の途中ですけれども、あまりないと考えてよろしいのか尋ねました。","respondent":"藤橋都市整備下水道課長","answer":"現在、調査委員会のほうで調査している中でも品川区が何らかの費用を出す必要があるかとか、そういったことはないというふうに考えております。","id":"exchange-009"},{"speaker":"安藤委員","kind":"質問","question":"住民説明会を行うということなんですけど、７月ですね、この対象範囲と周知の方法についてお伺いします。いろいろな事情でいらっしゃると思うんですね、そういう方への知らせる仕組みというのはどのように担保されるのかお伺いします。","respondent":"藤橋都市整備下水道課長","answer":"それから、いつ再開ということは申し上げられませんが、区といたしましては一刻も早く再開したいというふうに考えています。住民説明会におきましては、それから地域の方々への説明を実施しておりまして、それから回覧等を用いまして説明会の案内をしてまいりますので。","id":"exchange-010"},{"speaker":"安藤委員","kind":"質問","question":"最後の点ですけれども、従来と同様のということなんですが、回覧とかいうのはいただいたんですが、具体的にはそういう以外にはやらないんでしょうか。例えば全戸チラシをお配りするとか、それはどの範囲で配るのかとか、そういうようなのがあれば。","respondent":"藤橋都市整備下水道課長","answer":"チラシにつきましては、回覧で周知する方法と周辺の方々へ個別に配る方法の２種類をこれまでも採用しております。あわせて、これまでと同様に町会の施設をお借りして説明会を行う場合と、それから場合によっては個別に説明する場合がありますけれども。","id":"exchange-011"},{"speaker":"松澤委員","kind":"質問・要望","question":"それから外側を掘るというと大変だと思うんですが、あの施設そのものをまた解体して広げてやる、そんなような大がかりになるんですか。その辺のことについて。","respondent":"藤橋都市整備下水道課長","answer":"もし、よろしければ、ちょっとパネルと実演して説明させていただければと思うんですが、よろしいでしょうか。","id":"exchange-012"},{"speaker":"松澤委員","kind":"質問","question":"品川区はきれいな水ができて喜んでいるんだけれども、そのぐらい、そうすると地下水そのものが今水位が上がって増えているということなんですか。その辺はちょっと所管外だからちょっとわからないですよね。","respondent":"藤橋都市整備下水道課長","answer":"地下水位ですが、図２の発進立坑の断面図に示した位置、土質のボーリングしたときの地下水位よりも現在は少し下がった状況にあるんですね。上がったという状況は確認できませんでした。","id":"exchange-013"},{"speaker":"松澤委員","kind":"意見","question":"すごいんだよね、ひび割れちゃってね、その辺の対策はどうなっているのか。もう一つお願いいたしますとの意見を述べました。","respondent":"藤橋都市整備下水道課長","answer":"それはやはり周りから薬液注入なりで、まず水が入らないようにすることをした上で工事をやっていくという形になるかと考えています。それからもう１点の砕石を投入したとき、したがって、速やかに調査して対応したいというふうに考えています。","id":"exchange-014"},{"speaker":"阿部副委員長","kind":"意見","question":"済みません、うろ覚えなので違っていたら申しわけないんですけれども、この工事をしている業者さん、途中で変わったかあるいは複数の工事会社が時間的にずれてかかわっていたというようなことがあったかなと思ったんですけどとの意見を述べました。","respondent":"藤橋都市整備下水道課長","answer":"その次の貯留管をつくるシールドトンネルにつきましては、五洋建設・浅川建設共同企業体が施工いたしました。いわゆる施工業者としては２つの共同企業体がかかわっているということになっています。","id":"exchange-015"},{"speaker":"阿部副委員長","kind":"質問","question":"一連の、まあ別々の工事とも言えますけれども、そういうことというのはよくあるのでしょうか。この連続した工事に別々の企業体がかかわったことで、原因究明がより難しくなっているという面はありましょうか。","respondent":"藤橋都市整備下水道課長","answer":"施工業者が２つ、やはり当時の記憶が定かでない部分があったり、記録からなかなか確認ができないことがあったりして時間がかかっているのは事実です。それから、その２つのそれぞれの施工業者さんへの確認の時間を要しているという実態であります。","id":"exchange-016"},{"speaker":"阿部副委員長","kind":"質問","question":"２つの企業体になったのは、入札してみたらたまたまということでよろしいんか尋ねました。","respondent":"藤橋都市整備下水道課長","answer":"そのように考えていただいて結構です。","id":"exchange-017"}]},{"id":"topic-04","title":"の３、所管事務調査","agenda":"の３、所管事務調査","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"１点目の住宅耐震化の問題というのは1)に含まれるのかどうかということと、その２点のほうが今回ちょっと正副案に入っていないのは、何か理由があれば教えていただきたいんですけど。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-018"},{"speaker":"安藤委員","kind":"質問・要望","question":"２番目と３番目のところが入っていない理由があれば、教えていただきたい。","respondent":"原委員長","answer":"時間的な形で考えて、テーマ２つかなと。かなりいろいろな全体的には住宅密集地ということでまとめさせていただきました。","id":"exchange-019"},{"speaker":"安藤委員","kind":"質問・要望","question":"２つに絞らざるを得なかったのかもしれないんですけれども、今後の委員会運営を工夫していただいて、議論できる場を工夫していただければということを要望させてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-020"},{"speaker":"安藤委員","kind":"意見","question":"一任というのはちょっとできかねるんですけれども、やはりどういうところに何を見にいくのかということを。時間の制約はあると思うんですが、一任というわけにはちょっといかないんですが、私としては議論をできる限りしていかないとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-021"},{"speaker":"安藤委員","kind":"質問","question":"今、始めて委員長のどこに行くかということしか最初なかったものですから、何でなのかなと思って聞いたんですけど。ぜひそういう議論を尽くして、視察するのであれば、ぜひ議論を尽くす必要が私はあると思いますので、それが私の意見です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-022"},{"speaker":"安藤委員","kind":"質問・要望","question":"私の気持ちとしては、くどいようですけれども、もう一度やはりきちんと、前回の話を議論を尽くされたとは私には思えませんので、委員長のそういうよろしいでしょうかというのはあるにせよ、私の要望としてはぜひ１回議論をしっかりすべきだと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-023"},{"speaker":"渡部委員","kind":"意見","question":"今日本来であれば場所等示されるはず、視察の内容等示されるべきところが、先方の都合等で場所が未定だったと。この話はもう前回終わっていることだと思いますので、あくまでも正副一任でご議論ないと思いますがとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-024"}]},{"id":"topic-05","title":"の５その他を議題に供します。 まず、所管質問","agenda":"の５その他を議題に供します。 まず、所管質問","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"宮崎議員の大規模開発より区営住宅をの質問に対して、部長のほうが住宅戸数が世帯数を上回っていると。具体的に区としてはどういうことを考えているのか教えてほしいと求めました。","respondent":"柏原住宅担当課長","answer":"こういった中で検討していきたいというふうに考えているところでございまして、一番下の実施・連携体制のところです。２３年度からは、住み替え事業の実施や各種情報発信を予定しております。","id":"exchange-025"},{"speaker":"安藤委員","kind":"質問","question":"空き家が、約２万５,０００戸というのは伺いました。区営住宅の入居希望者の方々が入居できるような住宅ストックの活用を考えていらっしゃるのかどうかお伺いします。","respondent":"柏原住宅担当課長","answer":"そういった具体的な数字をとりながら、どのぐらいのストックを活用できるか等々も含めて検討していくというものです。子育て世代の方であるとか、そういった方等も含めながら、どういった方々になるかというのもそのときに整合していきたいというものです。","id":"exchange-026"},{"speaker":"安藤委員","kind":"質問・要望","question":"ちょっと宮崎議員の質問の中では、区営住宅をつくってほしいと要望があったわけですが、そういうことではないんでしょうか。そういうことはやらないんか尋ねました。","respondent":"片田防災まちづくり事業部長","answer":"国あるいは都の施策としてあるいは区の施策として、それぞれ都営住宅、区営住宅といったものを設けて支援しているという状況です。これは住み替えだと私は考えておりますので、考え方、スキームがまた決まり次第委員会のほうにもご報告をするということで考えております。","id":"exchange-027"},{"speaker":"安藤委員","kind":"質問","question":"そういう中で、やはり多くの方が希望されながら、やはりそういう行政の方がとっている手当からあぶれちゃうわけですから。住宅に困っている方々にとって実質的に助けになるようなそういう施策をしてほしいと求めましたけれども、何かありましたらお願いします。","respondent":"片田防災まちづくり事業部長","answer":"平成２０年度ですけれども、そういう状況になってきているという中で、確かに若い方とかいろいろなお困りの部分があると思いますけれども。区としても別な側面からの支援はいろいろメニューとしてはあろうかなと考えていますので…","id":"exchange-028"},{"speaker":"阿部副委員長","kind":"質問","question":"２点ほどお伺いしたいんですけれども、ちょっとやはり今検討中ということなんですけれども、わかりにくいなと。それを説明を求めました。","respondent":"柏原住宅担当課長、片田防災まちづくり事業部長","answer":"１カ所ということではなくて幾つか拠点を持つというのも１つの考え方なのかなとは思っています。賃貸のできる住宅だとかもろもろ入れますと２万戸近いものは数字としてはとらえてはいるんですけれども、です。 高齢者施設に入って空き家になっている場合もあるし、できるだけわかる範囲の中で情報収集をしながら整理をしなければいけない。他の事業ともソフトだけではなくてそういうハードの支援も絡み合わせながら…","id":"exchange-029"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/483234?Template=document&Id=3982#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2010-01-01&TermEnd=2010-12-31"}],"sourceMeta":{"pages":0,"characters":24010,"voices":92}},{"id":"h22-20100629-9","meetingId":"h22-cm06","date":"2010年6月29日","dateIso":"2010-06-29","committee":"文教委員会","time":"午前１０時０２分～午後１時４４分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を69件整理しています。","topics":[{"id":"topic-01","title":"の平成２２年度新入学学校別増減要因一覧","agenda":"の平成２２年度新入学学校別増減要因一覧","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"この新１年生の増減要因一覧というのは、いつから作成が始まっているのかということと、あと経年的に見た特徴的な傾向とか何かあるのかどうか。その辺の分析とか傾向について説明を求めました。","respondent":"富田学務課長","answer":"小学校が平成１２年度の入学者から、中学校が平成１３年度の入学者から学校選択を実施しておりますので、そのときから作成しております。１０年間を見通してというようなことにつきましては、指定校変更の人数等々が減ってきているというのは特徴として挙げられることです。","id":"exchange-001"},{"speaker":"飯沼委員","kind":"質問","question":"その辺は追いかけていらっしゃるのかどうか、その辺の傾向を１つお伺いしたいのと、そういった傾向のとらえ方をしているかどうか。一貫校で６年生から７年生に上がるときに、それをつかんでいらっしゃるかどうか、説明を求めました。","respondent":"富田学務課長","answer":"２点目の希望申請についての増減の二極化といったようなご指摘でありましたが、これは学校によりさまざまの状況があります。３点目の小中一貫の小学校から中学校へのというところにつきましては、他の中学校に現実に行っているということはあります。","id":"exchange-002"},{"speaker":"飯沼委員","kind":"質問","question":"２点目のプラス傾向、そういうとらえ方というか、そういう分析とかで出ているのかどうか。学校によりさまざまということにおいては、学校においてはあらわれているというとらえ方でいいのか尋ねました。","respondent":"富田学務課長","answer":"学校によりさまざまと申し上げたのは、年度により一概にずっと減だとか増だとかという、その人数を含めて一概になかなか申し上げられないということでありまして、変動はあるということです。","id":"exchange-003"},{"speaker":"西本委員","kind":"質問・要望","question":"そこら辺をもう少し詳しくどういう数字なのかを教えていただきたい。希望数というのは何の希望数なのか、指定校変更というのとの違いがよくわからないんです。","respondent":"富田学務課長","answer":"その就学指定が学校教育法で定められている指定校ということになりまして、指定された学校以外を希望している場合には指定校変更となります。就学指定された後に、指定された学校ではない学校に行きたいという方々が出てくるということで…","id":"exchange-004"},{"speaker":"西本委員","kind":"質問","question":"その前に申請をするんですか。その希望を聞くということ、では、学区域でそこが指定校になるということか尋ねました。","respondent":"富田学務課長","answer":"指定校変更ですとか区域外就学といった区分は、学校選択が始まる前からずっとある制度です。学校選択を実施していない自治体においても、他の自治体でもある制度です。","id":"exchange-005"},{"speaker":"西本委員","kind":"質問","question":"そこでオーケーというふうに出るのは、どういう形でオーケーになるんですか。そこの学校選択とどう違うんか尋ねました。","respondent":"富田学務課長","answer":"指定校変更についてのお尋ねだと思うんですが、現在指定校変更の申請を出される多い例としては、ブロックを越えた学校を希望する場合。親子で意見が違っていたので、やはりこっちの学校に入りたいというような場合に、中学校だと多く指定校変更というような形で出てくるです。","id":"exchange-006"},{"speaker":"西本委員","kind":"質問","question":"この数とはまた別に、特別支援学級の子どもの数というのはあるんですか。それとも１年生の全部がここの中に入っている数なんか尋ねました。","respondent":"富田学務課長","answer":"実際上は、右側の入学者数というのは通常学級の人数ということです。学務課で把握しております通常普通学級の人数です。","id":"exchange-007"},{"speaker":"西本委員","kind":"質問","question":"鮫浜小学校、中延小学校、ここら辺が非常に気になるんです。これはどういう動向なのか、どういう指導、対策を教育委員会として考えておられるのか尋ねました。","respondent":"冠木指導課長","answer":"私どもとしましても重点支援校という形で指定をいたしまして、校長の学校経営に対して私どもが介入をして、至らないところについて。そういうようなところと学校の経営とちゃんとマッチしているのか、そんなところを分析しながら、校長への指導を進めていくです。","id":"exchange-008"},{"speaker":"西本委員","kind":"質問・要望","question":"今、分析しているということなのでしょうか。数ではないとは言いつつ、やはりそういう部分で敬遠されているので、何となくそれらの特徴みたいなものがあれば教えていただきたいんですが。","respondent":"冠木指導課長","answer":"それと、学校の校長の経営方針がきちんと合っていけば、それなりの適正な数値にはなってくるのかなと思っているんです。ところがその辺が十分でない場合に、私ども教育委員会としても校長へ指導していくです。","id":"exchange-009"},{"speaker":"西本委員","kind":"質問・要望","question":"ですからそういういろいろなところで、ただそういう学校も数字から見ると結構よくなっているところがあるんです。そこを踏まえて参考にしながら、中延小学校なんかもいろいろなことをやっている学校だと思いますので、ちょっと支援を考えてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-010"},{"speaker":"金野委員","kind":"質問","question":"それと、この入学者数の人数が先ほど平成２１年度から比べると６４人減とおっしゃっていたでしょうか。これは大体７２.９％の入学者率ということで、これは平成２０年度、平成１９年度と、この推移はどのようになっていますか尋ねました。","respondent":"富田学務課長","answer":"平成２１年度、平成２２年度では、学校としては変わってきているというところがあります。小中一貫校も増えてきておりますので、そういう意味では希望の状況というのも変化が出てきているのかなと考えております。","id":"exchange-011"},{"speaker":"金野委員","kind":"質問","question":"国公立も含めると５８７人になるんでしょうか。これは今年の数字ですけれども、昨年、一昨年前、私立とか国公立を選ぶこの傾向性というか、数字的にはどんな状況なんか尋ねました。","respondent":"富田学務課長","answer":"平成２０年度は国公立が２４人、私立が５０９人ということですので、数としてはあまり変化のないところです。当区は城南の地区の中では、区立小学校から私立に行く割合は非常に低いです。","id":"exchange-012"},{"speaker":"金野委員","kind":"質問","question":"わかりました。現状をまずお聞きいたしまして、課題等もある中で、どのようにこの数字を見ていらっしゃいますか尋ねました。","respondent":"冠木指導課長","answer":"数字だけを見ると横ばいというところがありますけれども、やはり私ども小中一貫校で教育内容の充実ということで進めております。これをどんどんＰＲすることによって、中学校連携型の中学校もありますけれども、私どもの小中一貫校に進んでいただきたいという思いです。","id":"exchange-013"},{"speaker":"金野委員","kind":"質問・要望","question":"城南地区では私立校、この中学校の７年生から９年生といういろいろ指導が大変で、特に生活指導のほうをお願いしたいということを思います。要望して終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-014"},{"speaker":"井上委員","kind":"質問・要望","question":"委員から質問があった指定校変更の辺のところでもう一度確認をしたいんですけれども、その前に質問で、全員が出していないと考えていいのでしょうか。その方たちも一応そういう希望として、Ａ校エリアに住んでいるけれども、Ａ校といって出すんか尋ねました。","respondent":"富田学務課長","answer":"指定校変更の先ほどの忘れたというかおくれたという、そのときに出さなかったんだけれども、そういった方々は指定校変更ということになります。指定校変更の数というのはかなり多くなってくるんだというような状況です。","id":"exchange-015"},{"speaker":"井上委員","kind":"意見","question":"実際にこの１４０人の方で、でも言った人は、言ってみたら変わることができたんだみたいな結果はよくないと思うんです。自分はというようなトラブルがないのがベストだと思うんですけれども、そういうところの配慮というか対策はどういうふうにとられていますかとの意見を述べました。","respondent":"富田学務課長","answer":"学校説明会等々にも大勢の方々が小学校の場合は足を運ばれていますので、その辺のご説明はさせていただいています。就学指定通知を１２月半ばぐらいに発送しますが、必ず記載をしていますので、周知においては十分であると思っています。","id":"exchange-016"},{"speaker":"井上委員","kind":"質問・要望","question":"本当にそういうことで、入ってみたらびっくりみたいなことのないように、ぜひ配慮していただきたいと思うんです。いついつまでに変更を希望される方はということで、そういう手続がしっかりとできているのかということが１点、まずそれを１つお願いします。","respondent":"富田学務課長","answer":"現在のところ、指定校変更の申請に期限は設けておりません。新１年生に限らず、途中学年でも指定校変更の制度というのは利用されているものですので、変わりたい方はすぐにいらっしゃる方がほとんどです。","id":"exchange-017"},{"speaker":"井上委員","kind":"質問","question":"今度は転入のところなんですけれども、小学校１年生の場合１１０人の方の転入があるわけで、以前から３５人の定員で５人の転入学ということで学級編成をされていたかと思うんですが、この辺は品川区が考えている転入の見込みと実態がどうなのかというところで、把握されていることを説明を求めました。","respondent":"富田学務課長","answer":"１０人という学校がありますので、特に新１年生の場合には、転入の方が多い傾向はあります。今後も、同様に運用してまいりたいと思います。","id":"exchange-018"},{"speaker":"井上委員","kind":"質問","question":"先ほど、私はちょっと納得がいかないんですけれども、同じ１年生で入学しているお子さんたちのことをどういうふうに考えているのでしょうか。どういう見解のもとにこういう資料の出され方をするのか、お伺いしたいと思います。","respondent":"富田学務課長、冠木指導課長","answer":"これは学務課の就学担当が希望申請、指定校変更、４月１日の入学に至る過程の部分を数字として把握している範囲でまとめさせていただいた資料です。直接の特別支援学級の就学相談等々を含めて、学務課では担当しておりませんので… 特別支援学級に就学されたお子さんの就学状況については、そして特別支援学級にお進みになった子どもたちの数等を公にしておりますので、それで報告をしているといたしております。","id":"exchange-019"},{"speaker":"井上委員","kind":"質問・要望","question":"やはりこれは１つの組織として整理をするとか、指導課と書いてもいいわけですから、ぜひそういう資料の出し方として考えていってほしい。これは考え方の問題ですから、ただ通学区域の自由化ということの動向の資料としてではなくて、そういう工夫もぜひしてほしいと求めました。","respondent":"富田学務課長","answer":"学校選択をしていただいた対象学年の方々へのアンケート調査というのを毎年度実施しておりまして、また集計がまとまりましたならば校長連絡会等々でも校長には周知いたしますし、こちらの文教委員会にも報告する予定にしております。","id":"exchange-020"},{"speaker":"井上委員","kind":"質問","question":"そういうところがどんどん少なくなっていってしまうということを、片やそういう政策で結果的に誘導してしまっていると思うんですけれども、そういうところで校長が努力される手はあるんか尋ねました。","respondent":"市川教育次長","answer":"そのことを、ましてや小学校の場合には、私どもは学校選択制を実施した当初から１つの考え方としてお伝えしているところです。では、何のために学校選択制を実施しているのかということなんですけれども、学校を選択していただくことを目的に学校選択制を取り入れたのではない。","id":"exchange-021"},{"speaker":"井上委員","kind":"質問","question":"自分たちの努力で変えていこうよというところが本来あるべきなのに、ここまで１０年、本当に中延小学校が新１年生が７人。地域を巻き込んでの改善とか、そこを具体的にどういうふうに取り組んでいるのか、少し例があれば紹介していただけますか尋ねました。","respondent":"冠木指導課長","answer":"子どもたちをじっくりと３６５日見ていくといった環境づくりといいますか、経営の考え方といったところを校長に助言していく中で、具体的な校長の手立てを応援してまいりたいと考えています。","id":"exchange-022"},{"speaker":"伊藤副委員長","kind":"質問","question":"簡単に端的にお伺いしますけれども、１つはこの表の中で、日野学園、伊藤学園の扱いはどうなっているのでしょうか。単純に日野学園と伊藤学園の扱いはどうなんでしょうかというのが１つと、もしくは中学校ではないところを希望したということか尋ねました。","respondent":"富田学務課長","answer":"２点目の減要因の内訳の中の希望申請ですが、なかなかわかりにくくて申しわけございません。表現については検討させていただきたいと思います。","id":"exchange-023"},{"speaker":"伊藤副委員長","kind":"提案","question":"だけど日野学園、伊藤学園の名前がないので、扱うのであれば同じようにしたほうがいいのではないでしょうかというご提案をします。今、さらに連携をとった上でスムーズな連携をとったほうがより実を結ぶと思うんですが、その将来的な考え方を一言お答えいただけますか尋ねました。","respondent":"冠木指導課長、和氣小中一貫教育担当課長","answer":"保・幼・小の連携というのは１つの大きなテーマでございまして、つぶさな連携ということで、幼稚園との連携をしています。これが一つ就学の動向にもかかわってくると私どもも認識しておりますので… 私どもとしましてはその連携グループ、連携グループとしてのまとまりをしっかりつくってまいりたいと思っておりまして、中学校へのスムーズな移行というのをさらに促進させてまいりたいと考えておるところです。","id":"exchange-024"},{"speaker":"伊藤副委員長","kind":"質問・要望","question":"小学校、中学校を含めた立体的なというか、そういう中で教育を展開していっていただきたいということを要望しておきます。よろしくお願いたします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-025"},{"speaker":"飯沼委員","kind":"質問・要望","question":"確認で、先月ご説明いただいた事務事業概要の人数総枠と違うので、これというのは４月１日ですか。ちょっとそこの確認が１点と、学校ごとにされているのか、保護者アンケートの中身をちょっともう少し教えていただきたい。","respondent":"富田学務課長","answer":"小学校６年生卒業間際の保護者・児童の方と、小学校１年生については入学した後の保護者の方に実施をしています。全校で実施しています。","id":"exchange-026"},{"speaker":"飯沼委員","kind":"質問","question":"すみません。これの報告というのはどこに載ってどう伝えられるのか、どこを見たらわかるのかというところを説明を求めました。","respondent":"富田学務課長","answer":"毎年度の文教委員会で報告をしています。","id":"exchange-027"},{"speaker":"飯沼委員","kind":"質問","question":"文教委員以外には行かないというとらえ方でいいですか。どこかに公表されているということはないんか尋ねました。","respondent":"富田学務課長","answer":"ございません。","id":"exchange-028"}]},{"id":"topic-02","title":"の、平成２３年度品川区立学校職員採用候補者選考日程","agenda":"の、平成２３年度品川区立学校職員採用候補者選考日程","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"ここの中身を教えていただきたいのと、先ほど今年は１カ月早めて優秀な人材を確保したいというところで、都の選考というのはもっと早いですよね。ちょっとその辺のスケジュールはわからないんですが、結果が出る前にこちらをということなのか、ちょっとその辺を説明を求めました。","respondent":"冠木指導課長","answer":"経験者選考については、常勤の教員を目指しておられる方がたくさんいらっしゃいますので、そういった方々にも枠を広げるという意味合いです。それからもう１点、近隣の地区の教員採用試験が７月中旬に行われるものですから、選考の日程を１カ月早めたです。","id":"exchange-029"},{"speaker":"飯沼委員","kind":"質問","question":"その選考の内容というのは一次、二次の選考があるんですが、ここの中身をちょっと教えてほしいのと、前回のときにどのくらい応募があったのかも説明を求めました。","respondent":"冠木指導課長","answer":"概要としましてはこの２ページに書いてあるような大卒程度の国語、数学、論文であるとかというようなところでやらせていただきたいと考えています。これは募集する教科によっても多少の増減があろうかと予想しています。","id":"exchange-030"},{"speaker":"金野委員","kind":"質問・要望","question":"この募集をされているのかが１点と、多く応募をしていただきたいのと、アイデアというのはどのようにしたらいいのか教えてください。現時点ではどれぐらい来ているのか尋ねました。","respondent":"冠木指導課長","answer":"この実施要綱とあわせまして、ぜひ熱い思いを品川区に向けていただきたいというＰＲをさせていただきたいているところです。募集状況がわかりましたら、文教委員会で報告します。","id":"exchange-031"},{"speaker":"金野委員","kind":"質問","question":"資料というか、そのアピールをするものがあるということですので、わかりました。参考のために１期生、２期生の採用の方の中学校の専攻、専科はどういったものだったのか尋ねました。","respondent":"冠木指導課長","answer":"中学校については今現在、英語科が３名、それから理科が１名、保健体育科が１名となっています。","id":"exchange-032"},{"speaker":"金野委員","kind":"質問","question":"この英語、理科、体育というふうに選んでいくものなんでしょうか。この辺の中学校の先生の教員採用、選ぶ根拠を説明を求めました。","respondent":"冠木指導課長","answer":"昨年は最終的に、結果的に３名の採用ということで、予定の５名までなかなか届かなかった。年齢層なども考えながら、中学校の英語についてはこの２年間で３名を確保できたというところで、目的が達成しつつある。","id":"exchange-033"},{"speaker":"金野委員","kind":"質問","question":"もう１つ学業のほかに、そういったところの選考の中には当然入っていることだと思うんですけれども、そういったところでは現状どうなんでしょうか。１期生、２期生の今の現状、学業のほかに生活指導のほうではどのような力を発揮されているか尋ねました。","respondent":"冠木指導課長","answer":"それぞれ担任１年目の方、２年続けて担任の方がいらっしゃいますけれども、それぞれお力を発揮していただいている。その方の資質については探っていくところですけれども、さらに研修等の機会を利用しまして、そういった力をさらに充実させていきたいと考えています。","id":"exchange-034"},{"speaker":"金野委員","kind":"質問","question":"教育長から熱き思いを伺いまして、まさに私ももう一言申し上げようかなと思っていた部分も、今、教育長のほうからお聞きしました。どうか。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-035"},{"speaker":"西本委員","kind":"質問","question":"特にこれはどこまで調べられるのですか。特に教育関係となってくるといろいろ受けとめる方がいらっしゃいますので、ちょっとそこの見解を説明を求めました。","respondent":"冠木指導課長","answer":"私どもも、自己申告ももちろんなんですけれども、その他の方法を使いまして、できる範囲で本人の状況確認はしているところであります。ですから事故のないように十分に取り組んでまいりたいと考えています。","id":"exchange-036"},{"speaker":"西本委員","kind":"質問","question":"区で調べるのが難しいところもあると思うんですが、犯罪がわかったという時点、それらしき事由があるなというように判断するときは、やめていただくという形にしているんか尋ねました。","respondent":"冠木指導課長","answer":"この欠格事項にかかわる部分については、その時点でおやめいただくということになります。","id":"exchange-037"},{"speaker":"井上委員","kind":"意見","question":"当初計画がどういうふうに動いていくのか、どういうふうに動いていくというものなのか、少しお知らせくださいとの意見を述べました。","respondent":"冠木指導課長","answer":"現段階では当初計画は変わっておりません。もちろんこれは人物が一番大切ですので、採用の人数は多少の変動はあるかと思うんですが、そういう意味で５名程度という提議をしておるところです。","id":"exchange-038"},{"speaker":"井上委員","kind":"質問","question":"今、最初の５名なのか６名なのか、ちょっとそこのところと、そこで人数を３０人程度ということで目標にしていましたけれども、それ以降何か考えがあるのか、ちょっとそこを整理して、どのような方向にこれが進んでいくのかということ、方向を少しお聞きします。","respondent":"冠木指導課長","answer":"は昨年の段階で今後５年間で３０名というような方向性を出させていただいたところですので、しばらくは５名程度というところで選考を続けてまいりたいと思います。","id":"exchange-039"},{"speaker":"伊藤副委員長","kind":"質問","question":"たまさか１,２００名全員をこの品川区で処理することはできないはずでしょうから、次の展開はどうでしょうかということを聞きたいのと。その大きな３つをお聞かせほしいと求めました。","respondent":"冠木指導課長、若月教育長","answer":"そして、１人でも多くの品川区で一生懸命やっていただくという教員を、都費の中でも採っていきたいと考えています。固有教員につきましては、その中でこれから育成をいたしまして… 今度はうちの区の職員ですから、やがて法整備を進めて学校の管理職になれるような段取りを進めていきたいと今のところでは思っています。一番最初のご質問に戻るわけですが…","id":"exchange-040"},{"speaker":"伊藤副委員長","kind":"意見","question":"やはり３０名程度という先生方の品川区の中での活躍、十分な対処をしていただきますように、改めてよろしくひとつお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-041"}]},{"id":"topic-03","title":"の荏原東地区の小中一貫校の学校名称","agenda":"の荏原東地区の小中一貫校の学校名称","exchanges":[{"speaker":"西本委員","kind":"質問","question":"前回の文教委員会にはなぜ報告がなかったのでしょうか。文教委員会が６月１日にあったわけですから、報告の何もなければ、その報告のずれはどうしてでてきたんか尋ねました。","respondent":"和氣小中一貫教育担当課長","answer":"５月３１日に決定したばかりで、それからさらに開設準備連絡会の皆さんにも正式に報告をしていない段階でございました。その上で文教委員会にも報告をするということで考えてございましたので、６月１日には特にご報告をしなかったということであります。","id":"exchange-042"},{"speaker":"西本委員","kind":"質問","question":"どうして６月１日付でこれが出てくるのか、６月１日に文教委員会があったわけですから、ここで話があってもしかるべきではないかなと思うんです。私たち文教委員という役割を担う中で、これはちょっとさびしいかなということなんですが、この兼ね合いはどういうことなんか尋ねました。","respondent":"市川教育次長","answer":"１つには、これは先ほど担当課長からも説明したとおり、地域関係者の方に協力をしていただいてきた。したがいまして、今後、情報提供ということにつきましては、ご指摘いただいたようなことも含めて、注意をしながら対応してまいりたいと考えています。","id":"exchange-043"},{"speaker":"西本委員","kind":"質問・要望","question":"ただ私たちはやはり議員ですから、住民の人たちの代表としていろいろ話し合いをするという任務があるわけです。それを含めて今後地域の方たちとかの情報も含めてどういう事情か、地域のためになりますので、ぜひ今後考えてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-044"},{"speaker":"飯沼委員","kind":"質問","question":"基本的なことなんですが、ここに開設準備連絡会という連絡会と書いてありますけれども、この構成は書いてあるんですが、何人くらいで構成されているのかと、７つの専門部会はどういうことが検討されているのか知りたいので、７つの専門部会を説明を求めました。","respondent":"田村庶務課長、和氣小中一貫教育担当課長","answer":"大もとのメンバー等をご説明しますが、まずメンバーは荏原第五地区の町会長全員、それから荏原第四地区の連合町会長を含めて該当する町会長４名。分科会については小中一貫教育担当課長からご説明いたします。 それから保・幼・小施設が一緒になりますので、保・幼・小連携検討部会。それから地域センターと複合施設になるということで、地域センター連携検討部会、この７つの部会を設置しております。","id":"exchange-045"},{"speaker":"飯沼委員","kind":"質問","question":"随分細かくいろいろ検討されて、この中にも先ほどの準備会の皆様がこうやって入って分かれていらっしゃるんですか。ちょっとそこの中身をお伺いしたいのと、あともう１点はアンケート、具体的にどのくらい集まったのかを説明を求めました。","respondent":"和氣小中一貫教育担当課長","answer":"関係する４校にアンケートの回収箱を置くのと、荏原第五地域センターのほうにもアンケートの回収箱を置きまして、そこでとったものです。全部の総数でいきますと大体５００件か６００件程度のアンケートの集約があったです。","id":"exchange-046"},{"speaker":"飯沼委員","kind":"質問・要望","question":"五、六百件というと結構集まったという感じでしょうか。これは要望です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-047"},{"speaker":"井上委員","kind":"確認","question":"名称候補を６つに絞って部会としての意向を最終確認したと最後のほうにあるんですけれども、この６つの中から区長が決定をしたと考えるのか、この６つに絞られた後の皆さんから意見聴取を少しされたのかどうかをちょっとお願いします。","respondent":"和氣小中一貫教育担当課長","answer":"その上でこの６つから、この豊葉の杜学園というのが圧倒的に多数の方が開設準備連絡会では支持をされていたということがあります。結果的にはそこになったという経緯でございました。","id":"exchange-048"},{"speaker":"井上委員","kind":"質問","question":"これが要するに小学校の別の名前をまた１年間、つくることを含めてどうしましょうかというレベルなのか、ちょっとそこのところを説明を求めました。","respondent":"和氣小中一貫教育担当課長、市川教育次長","answer":"その上でお考えいただいたということですから、どんな思いでこの校名を投票したのかも含めまして、全部ご検討いただいたです。中学校の名称は、例えば中学校で言うと統合して２年間だけ新しい名前を決めて… 先ほど説明申し上げた専門部会の中で議論として結論づけられたということで、小中一貫校の名称を先に決めさせていただいたという経過です。これが今回、荏原東地区の中での学校名についてのいわばルールづけということで…","id":"exchange-049"},{"speaker":"井上委員","kind":"質問","question":"そうすると、これは基本的には愛称だというふうにとらえました。こちらも豊葉の杜中学校というふうに今のところしていこうじゃないかという、決定ではないけれども、そういう方向での検討だと理解していいか尋ねました。","respondent":"和氣小中一貫教育担当課長","answer":"そういう方針で進めているところです。","id":"exchange-050"},{"speaker":"井上委員","kind":"意見","question":"そのことについて地域の方たちはどういう議論になっているのか。まだそこのところで、その辺のところがどういうふうに整理されているのか、もう１度お願いしますとの意見を述べました。","respondent":"和氣小中一貫教育担当課長","answer":"先ほど申し上げましたように、アンケートをとるときにもそういうことを前提としてとらせていただいていますと明記してアンケートをとっております。そのことを前提にして、皆さんアンケートにお答えいただいておりますので、地域交流は十分にとられていると考えております。","id":"exchange-051"}]},{"id":"topic-04","title":"の聴取を続けます。 次に、（４）の五反田図書館リニューアルオープン等","agenda":"の聴取を続けます。 次に、（４）の五反田図書館リニューアルオープン等","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"基本的に蔵書のボリュームとか、あと閲覧席とかの基準みたいのはあるのでしょうか。ほかの業務はどういうふうな流れの中で中央図書館がやっているのか、ちょっとそこの流れを説明を求めました。","respondent":"小川品川図書館長","answer":"スタッフの数は責任者等も含めまして１９名程度ということで考えております。品川図書館から五反田図書館に出向きまして蔵書管理等をしていくです。","id":"exchange-052"},{"speaker":"飯沼委員","kind":"質問・要望","question":"何かあるのかなと思ってお伺いしたんですけれども。その辺を教えていただきたいのと、それに返しているのか、そのあたりを説明を求めました。","respondent":"小川品川図書館長","answer":"３点目のご質問ですが、基本的に全１０館で利用者の方のお声を吸い上げるためのアンケート用紙を用意しています。今ですとメールですとか、お手紙ですとか、あらゆる手段で利用者の方からのお声を吸い上げる場面は確保できていると考えています。","id":"exchange-053"},{"speaker":"飯沼委員","kind":"質問・要望","question":"してほしいなと思うのと、あいている時間を教えていただきたいのと、ほかの図書館で結構年数がたっている図書館があります。今後のやり方とか、改修とか改築の計画とかはどのくらいあるのか、ちょっとその辺を教えていただけますか。","respondent":"小川品川図書館長","answer":"それからカードをつくることはできないということで考えてあります。そのほかについては耐震診断結果で改修が必要でない、あるいはもう改修が終わったということで、残りは二葉図書館のみです。","id":"exchange-054"},{"speaker":"西本委員","kind":"質問","question":"（３）番のところの臨時窓口なんですが、当面２００人の利用実績があったということなんですが、ちなみに前の五反田図書館のときと比べるとかなり大きい結果だったのか尋ねました。","respondent":"小川品川図書館長","answer":"サービスコーナーの利用ですが、ちなみに比較をします旧の五反田図書館の日々平均の利用者数が約３００名程度ですので、それに比べるとかなり、スペースが小さい割にはとても利用していただけたと考えています。","id":"exchange-055"},{"speaker":"西本委員","kind":"質問","question":"多分、ＴＯＣですので、人の出入りが多かったからなのかなと思うんですけれども、五反田図書館はちょっと駅から遠いんですね。この結果を見て思ったんですが、こういう方法も非常に区民の方々へのサービスとしてはいいのかなと思ったんですが、その辺はいかがか尋ねました。","respondent":"小川品川図書館長","answer":"今後、武蔵小山のようなパターンを利用していくかということについては、今のところ全くの白紙で未定ですが、まずは武蔵小山の利用状況等を見据えて、それから次の課題として考えていきたいと考えております。","id":"exchange-056"},{"speaker":"金野委員","kind":"質問","question":"１点、お聞きします。特徴のところでの、子育て支援コーナー新設ということなんですが、これはもう少し詳しく伺わせてください。","respondent":"小川品川図書館長","answer":"子育て支援コーナーについてですが、小児栄養の関係、今の図書館の現状ですと一般図書のコーナーに分類ごとに並べてあるという状況なんです。に、一目で必要な分類のものを見分けることができるという部分で、そこに特徴を生かしてコーナーを設けていきたいというものです。","id":"exchange-057"},{"speaker":"金野委員","kind":"意見","question":"いわゆる支援コーナーですけれども、そこで本のやり取り、あるいは相談に乗るようなコーナーではないということでしたね。そういう理解でいいんですねとの意見を述べました。","respondent":"小川品川図書館長","answer":"特にそういった相談員等の配置は考えてございません。","id":"exchange-058"},{"speaker":"金野委員","kind":"質問","question":"配置はないということですが、ここの業務をやってくださる事業者の方でそういった対応するような人がいるんか尋ねました。","respondent":"小川品川図書館長","answer":"当然、図書館の業務を請け負っていただきますので、そういったコーナーの特色も含めて理解をしていただいて、スタッフの配置というものをしてもらうようにしておりますので、そういった面での図書のアドバイスなどは、個別に相談いただければ対応は十分できるかと考えております。","id":"exchange-059"},{"speaker":"井上委員","kind":"意見","question":"相談ができて、ここは文化センターとの複合ということで、これからお父さんがお子さんを連れていくという部分もあると思うんです。男性トイレの中におむつがえ、あるいはちょこっと座っている、そういうところがちゃんと用意されているかどうか聞かせてくださいとの意見を述べました。","respondent":"小川品川図書館長","answer":"レファレンスについては、図書館員が不在の図書館につきましても、事業者のスタッフが一時的にはレファレンスを対応するということになっております。業務の中にも館内レファレンスについては対応するということになっておりますので。","id":"exchange-060"}]},{"id":"topic-05","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"井上委員","kind":"質問","question":"調査項目の中に、保・幼・小・中の連携という、保・幼・小・中まで入れたところというのは、品川区の事業の調査というところでは結構新しい言葉だと思うんですけれども、ここのところはどういうことか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-061"},{"speaker":"井上委員","kind":"確認","question":"もう１つ、本当に時間もない中でということで、これを中心にしてやりましょうという中なんですが、ほかにも事前に正副委員長への申し入れで、その他の部分で確認をしたい部分とか調査ということは、臨機応変に対応していただけるという理解でよろしいか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-062"},{"speaker":"西本委員","kind":"質問・要望","question":"保・幼・小・中、これは非常に豊富な視点で、いいかなと考えています。これは公明党さんが出されている要望ですと、具体的に何となくイメージがわくんですけれども、どこまで含めているのか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-063"},{"speaker":"西本委員","kind":"質問","question":"ネットさんも出されていますが、具体的にはどういうことを放課後対策で考えておられるのか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-064"},{"speaker":"井上委員","kind":"質問","question":"いろいろ議会質問でも、どういう子どもたちというふうに限定をしないで、放課後の支援対策というところでとらえています。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-065"}]},{"id":"topic-06","title":"では３の行政視察についてですが、先に予定表の４、その他","agenda":"では３の行政視察についてですが、先に予定表の４、その他","exchanges":[{"speaker":"井上委員","kind":"質問・要望","question":"ここが来年には移転するわけですから、どういうふうに、少し状況を説明ほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-066"},{"speaker":"井上委員","kind":"質問・要望","question":"今のお話だと預かり保育と給食は可能な限り進めるというお話ととらえていいのかという確認と、もう１つ、これは未確認で。９月の文教委員会までそれが出てこないのか、どういうふうなスケジュールになっているのか、改めて確認をさせてほしいと求めました。","respondent":"吉岡保育課長","answer":"預かり保育と給食ですけれども、委員がどう認識されているかちょっとわからないんですけれども、あるいは給食がなくなるという話はしてございません。それから、決定した後の対応ですが、スケジュール的には来年の４月のオープンになります。","id":"exchange-067"},{"speaker":"井上委員","kind":"質問・要望","question":"今、内部の決定になると思いますというところが、どのぐらいをめどに私たちは考えればいいのかという、行き当たりばったりではないはずなので、もうちょっとそこははっきりとお示しほしいと求めました。","respondent":"吉岡保育課長","answer":"決定の時期ですけれども、組織がしかるべき時期には決定いたしますので、９月ごろにはおおむねの決定ができるのではないかと考えております。","id":"exchange-068"}]},{"id":"topic-07","title":"行政視察","agenda":"行政視察","exchanges":[{"speaker":"井上委員","kind":"質問","question":"中身について少し聞いてもいいですか。一番上のこの学校で行っている食育科というのは、品川区で言う市民科みたいなものということなんか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-069"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/746735?Template=document&Id=4704#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2010-01-01&TermEnd=2010-12-31"}],"sourceMeta":{"pages":0,"characters":45883,"voices":179}},{"id":"h22-20100629-5","meetingId":"h22-cm06","date":"2010年6月29日","dateIso":"2010-06-29","committee":"総務委員会","time":"午前１０時０２分～午前１１時４７分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を34件整理しています。","topics":[{"id":"topic-01","title":"第５２号議案、平成２２年度品川区一般会計補正予算","agenda":"第５２号議案、平成２２年度品川区一般会計補正予算","exchanges":[{"speaker":"土井委員","kind":"質問","question":"緊急雇用創出事業補助金という形になって、これは都のほうから来ることになっているんですが、実際上はどこからくるんですか。どこか別なところにプールしてあった金がおりてきているんだというふうに認識するんですが、その辺、細かくちょっと聞かせてほしい。","respondent":"金子企画財政課長","answer":"これですが、結果として両方とも東京都から入ってきますけれども、もとのところは国の予算で、国の緊急雇用創出事業で東京都のほうで基金になっているものと、東京都を経由して基金にならないで入ってくるもの、こういうふうな話で伺っているものであります。","id":"exchange-001"},{"speaker":"土井委員","kind":"意見","question":"大もとの国の緊急雇用対策の資金という形での予算はいつ、どうつくられて、それが今どういう形になっていて、そして、今こういう形で出てくるのかという、その仕組みをちょっと説明を求めました。","respondent":"金子企画財政課長","answer":"これはここ３年ほど継続して実施しているものでありまして、東京都のほうはたしか２年ほど前に国のほうから出て、支出をしてもらうというふうな形で来たものとして受けとめてあります。","id":"exchange-002"},{"speaker":"土井委員","kind":"質問","question":"その基金というのは、どこにたまっていたのかということが知りたいんです。基金、そして区のほうにおりてきたという資金の流れがあるのではないでしょうかということでお伺いしているので、その辺がわかるように。","respondent":"金子企画財政課長","answer":"先ほど申しましたとおり、ここでまた何回か国の方から出てきたものを都でプールしてあったものをそれぞれ市区町村で実施する事業に対して。平成２０年度から幾つか割り振られて実施してきておりまして、予定としては平成２３年度も予定されているというふうに聞いているところで…","id":"exchange-003"},{"speaker":"土井委員","kind":"意見","question":"それがどこかということと、その団体なり、何なり、どこかに行ったのか、そこでプールされたのかどうかということを聞きたかった。金がおりてきたことに文句を言っているわけじゃありませんとの意見を述べました。","respondent":"金子企画財政課長","answer":"基金自体は東京都のほうの基金ですから、東京都で持っているというふうに聞いております。執行するのもそういう意味では東京都が執行しているというふうに私どもでは認識しております。","id":"exchange-004"},{"speaker":"林委員","kind":"意見","question":"本当に切羽詰まった、雇用創出を生み出していくためのものというふうにとらえるほうが私は、「緊急」という言葉の使い方は正しいと思うんです。雇用創出にでも使ってくれと言って、地方自治をなめたような補助金の形に私は見えるんだけれども、腹が立ちませんかとの意見を述べました。","respondent":"金子企画財政課長","answer":"区としても３年ほど使っているわけなんですけれども、それを活用して事業のスキームを組み立てるということをやってきたわけです。成り立ち得るだろうというところから改めて東京都の緊急雇用創出事業について申請して、こういったものを活用するというふうに考えたものです。","id":"exchange-005"},{"speaker":"林委員","kind":"質問","question":"高齢者のほうの話は厚生委員会で済んでいる話だから、歳出の総務費の部分で、ちょうどここに危機管理室長もおられますからお聞きいたしますけれども、区施設運営サポートという事業は緊急に必要な事業なんか尋ねました。","respondent":"伊勢危機管理室長","answer":"平成２２年度、平成２２年度は３カ月ほどたったわけですけども、この制度をぜひ活用して緊急対応していきたいです。サポートの関係につきましては、常時図書館等に配置いたしまして、何かほかでも緊急な事態があれば即日警備配置ができるようにというようなことです。","id":"exchange-006"},{"speaker":"林委員","kind":"質問","question":"とすると、これは、図書館の運営に当たる人件費に回っていくというふうに理解をするものなんですか。なぜ当初の予算に入れなかったのか、緊急だからここに使おうという段取りになったのか、その辺を聞かせてください。","respondent":"伊勢危機管理室長","answer":"図書館もいろいろな館がありますけれども、トラブルが起こりそうなところ、所管と連絡を取り合って詰めていました。今現在ですともう既に９件そういうのが出てきているということで、この間、常時配置するという形のサポートという形で計上させていただきました。","id":"exchange-007"},{"speaker":"林委員","kind":"質問","question":"緊急でも必要だとつけて、なおかつ平成２２年度もこういうことが実際に起こっているから必要な経費なんだという説明ですよね。必要な経費だから６３０万円ちょっとの経費をかけているわけですから、来年度の当初予算にも当然これは入ってくるんですね。","respondent":"伊勢危機管理室長","answer":"今現在の９件ですけども、これを配置することによって抑止効果が生まれるということもありますから、これからどういう形で数字が推移していくかわかりませんけれども、その辺の状況を見ながら予算編成に当たるということになります。","id":"exchange-008"},{"speaker":"林委員","kind":"質問・要望","question":"確認しておきます。来年の予算編成のときにあるだろうから、担当の、所轄の予算要望に対して、企画財政課のほうも、上がってきたらつけますね。","respondent":"金子企画財政課長","answer":"来年度の予算編成につきましてはこれから方針を立て、なおかつ実情がどういうふうに変化しているかということも判断した上で、最終的には予算の判断をしていきたいというふうに考えてあります。","id":"exchange-009"},{"speaker":"林委員","kind":"質問・要望","question":"もう一回、また予算の要望が出てきたら、また調べるんですか。ぜひ、まして文字には、「緊急」という字がつくほど逼迫しているというのがどうも腑に落ちないんですけれども。","respondent":"日下部企画部長","answer":"ただ、この問題を、雇用の問題を解決するときに、国だけではこれはやはり解決は難しいと。これに対してどう取り組んでいくかということが前々からの課題でもありましたので、せっかくの１０分の１０の補助金ですから有効に活用したい。","id":"exchange-010"},{"speaker":"宮崎委員","kind":"質問・要望","question":"２年前からこういう警備を配置しているんだけれども、今の説明では、ここのところ増えている。今の件数も含めて、どういうふうに、なぜこういうふうになってきたのかというところをちょっと教えていただきたいんですが。","respondent":"伊勢危機管理室長","answer":"それから、増えている理由ですけども、これは平成２１年度までは比較的職員で対応していたというところがあります。職員で対応していましたけれども、昨年度は１１件でございまして、現在のところは９件です。","id":"exchange-011"},{"speaker":"宮崎委員","kind":"質問","question":"あるいは９件の数え方というかですね、具体的にどういうところで、こういう警備の方が対応しなければいけないのか。例えば配置するところからどういうふうに連絡なりやって、どういうふうに対応するのか、そこのところはどうか尋ねました。","respondent":"伊勢危機管理室長","answer":"基本的にはこれまで、２年前から始めたわけなんですけど、それまではずっと職員でやってきました。それから、平成２２年６月、今日までですけれども、９件のうち図書館が６件です。","id":"exchange-012"},{"speaker":"宮崎委員","kind":"質問","question":"だけど、例えば苦情を言っているんだとかですね、そういう対応になっていくかどうかとかですね。そういうところはどういうふうに判断していくのかなというのと、場合によればそういう刃物とかですね、どんなもんか尋ねました。","respondent":"伊勢危機管理室長","answer":"そういう中で、なかなか退去できないから、警察を呼んで、ということがございました。こういうような事例、なかなか刑法犯にはいかないけれども、迷惑行為をやっている場合に呼んでるということがあります。","id":"exchange-013"},{"speaker":"宮崎委員","kind":"質問","question":"実際に配置するとなるとどういう、いわゆる警備会社のほうに頼むのでしょうか。まあ、それはともかく、どういう配置をするのか、どこに配置するかですね。","respondent":"伊勢危機管理室長","answer":"警備員の実際の配置ですけども、施設だとか、そういう対応によって違います。それから、これから契約するわけですけど、基本的には警備会社を想定しております。","id":"exchange-014"},{"speaker":"宮崎委員","kind":"意見","question":"そういう事業部のところでしっかり対応するというのが何か、本来の形なのではないかななんていうふうに思うんですけども、そこら辺はどうでしょうとの意見を述べました。","respondent":"市岡総務部長","answer":"まだ例に出しませんでしたけれども、保育園等で養育の関係で、こういうのはなかなか職員が間に入っておさめるということも難しいケースがあります。必要以上にこういう警備を配置する必要はありませんが、総務費で全体的なカバーをするという意味の予算をお願いしたと…","id":"exchange-015"},{"speaker":"宮崎委員","kind":"意見","question":"今、私は何か、危機管理室というよりもある意味では総務課ということでのほうが何かしっくりいくのかなというふうな感じを受けました。これは意見だけですとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-016"},{"speaker":"須貝委員","kind":"質問","question":"今回このおかげで１２名ですか、１２名分の少なくとも雇用は生まれるということならば、私は本当に大したもんだと感謝しております。それは別段、これは福祉に回るんですけど、これはこういうふうに割り振っているのは問題は何もないということなんか尋ねました。","respondent":"金子企画財政課長","answer":"歳入の科目の問題のご質問ですけども、歳入としましては、雇用関係の歳入として入っております。今回もこの趣旨からいって産業経済費であるということから、歳入のほうについてはこのようにさせていただいたものです。","id":"exchange-017"},{"speaker":"堺委員","kind":"質問・要望","question":"ところが、その上の福祉人材スキルアップ事業ですから、そこは新たな雇用創出につながるという考え方をするのかどうか。その辺の考え方を教えていただけませんか。","respondent":"金子企画財政課長、伊勢危機管理室長","answer":"説明が不十分だったかもしれないんですが、５施設になりますので計１０名を雇用してもらおうと、雇用の創出ということが当てはまっているというふうに考えてあります。 危機管理では１名配置するですけども、年末年始を除いて土日もありますので、実際には警備会社で何名か、１名では足りないと思いますので、何名か、時間で区切るとかありますから、その辺は１名ではなくて２名以上になると思います。","id":"exchange-018"},{"speaker":"堺委員","kind":"質問","question":"今の５施設で、１施設２名だから１０名と。私自身がちょっと理解できなくて質問したんですが、それは説明されるときにその部分、そういうふうな説明があるとありがたい気がするんです。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-019"}]},{"id":"topic-02","title":"平成２１年度品川区一般会計予算繰越明許費繰越計算書","agenda":"平成２１年度品川区一般会計予算繰越明許費繰越計算書","exchanges":[{"speaker":"林委員","kind":"質問","question":"繰越明許というのは１件か２件、８件もあるということについてまず、財政担当からご意見を伺いたい。","respondent":"金子企画財政課長","answer":"見通しより若干おくれて年度をまたいでしまったということが、結果としてこういうことに結びついたというふうに考えてあります。そういったことが可能であるならば、今後そういったことも視野に入れて予算の編成というものもしていく必要があるかなというふうに考えてあります。","id":"exchange-020"},{"speaker":"林委員","kind":"質問","question":"一番下の８つ目の大崎駅周辺地区再開発事業ということでいくと、品川区の一般財源が３,８６４万円であるということで、合計で３億８,０００万円強。それぞれの事業に当たって、ここに出ている繰越明許費計算書の右から３列目の数字というので、これで全部終わりか尋ねました。","respondent":"金子企画財政課長","answer":"ちょっと全部終わりかという意味がわかりませんけれども、この事業に関しての平成２１年度分についてはこれで完了です。","id":"exchange-021"},{"speaker":"林委員","kind":"意見","question":"平成２１年度に立てた平成２１年度予算の部分でこれは終わりだけど、事業全体でもまだこれ以外に、大崎駅周辺ですとか、電線の地中化というのでは、事業全体としてはこれ以外にも予算をつけてあるのか、これからつけるのかとの意見を述べました。","respondent":"金子企画財政課長","answer":"７年、８年かかる長い事業ですので、これはあくまでも平成２１年度分であると。平成２２年度分については別途予算を計上して、鋭意執行すると、こういう形になっております。","id":"exchange-022"},{"speaker":"林委員","kind":"質問","question":"そうすると、これだけ、ちょっと今偶然出た商店街電線類地中化事業という話でいくと、この事業もやってるけど、別の平成２２年度予算をつけた部分、ここでは数字、私もわからないんですが、あなたたちも持ってないんだろうけど、あって、２つの工事が進んでるんだよというふうにとるわけか尋ねました。","respondent":"金子企画財政課長","answer":"戸越銀座の場合の電線類地中化事業はたしか４つぐらいに工区が分かれてまして、計画的にそれを順次予算化して進めているという形ですので、そういう意味では委員のご指摘のとおりです。","id":"exchange-023"},{"speaker":"林委員","kind":"質問","question":"しつこいようだけど、平成２２年度に立てた予算の工事よりも、こっちの工事をまずは終わらせないとまた、繰越というのはないんで、また繰越明許という事態が起きるなんていうこともあるんか尋ねました。","respondent":"金子企画財政課長","answer":"先ほどもちょっと申しましたとおり、平成２２年度に計上している部分については今事業を進めているところですので。ただ、それを目途に進めていることは間違いないところです。","id":"exchange-024"}]},{"id":"topic-03","title":"２番目、庁舎耐震改修工事の今後の予定","agenda":"２番目、庁舎耐震改修工事の今後の予定","exchanges":[{"speaker":"土井委員","kind":"質問","question":"工事ですから閉鎖したり、いわゆる補助１６３号線のほうをずっと下っていって、車が入るところから下がってくると。駐車場から上がってきて、また下へ戻ってしまうという通路を通らなければならないだろうというふうにもなりますので、案内は。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-025"},{"speaker":"林委員","kind":"提案","question":"区民の人は一生に１回しか来ない用件で区役所に来て、何かあそこの近くにおりられる階段をつけてほしいなというので、ぜひ要望しておきます。区議会事務局長にお聞きをするんだけど、こんなに議会棟、そういうことはいつごろお聞きになったんか尋ねました。","respondent":"桑村区議会事務局長","answer":"事前の当初のお話では、こういういろんなところの閉鎖というようなお話はあったのかもしれませんけれども、こういう形での話というのは６月の頭です。中でのいろんな議会運営のことについては、また別途こちらのほうで検討させていただいて…","id":"exchange-026"},{"speaker":"林委員","kind":"質問","question":"議会開催中くらいは何か通路があって、そこで議会に入れますよとか、そういう算段をできないものなんでしょうか。６月になって突然こういう話が出てくるというのは、私は、議会を無視とは言わない、軽視してるのではないのかなというふうに受け取るんですけれども。","respondent":"宍戸施設整備課長","answer":"案内の強化ですとか、なるべくそういった、傍聴の方々のご不便を少しでも少なくするような工夫をしていきたいと思います。工事上の工夫だけではなくて、案内の工夫、その他、幅広く考えていきたいと思いますので、よろしくお願いいたします。","id":"exchange-027"},{"speaker":"本多委員","kind":"質問・要望","question":"１点だけ、すみません、思ったことを述べさせてほしいと求めました。そこだけちょっと簡単に教えていただきたいんです。","respondent":"宍戸施設整備課長","answer":"委員の話のとおり、スペース的にできないというふうなこともございまして、破砕の工事がかなり多く発生しております。なるべく区民の皆様にもご迷惑をかけないよう、再度調査、検討したいと考えています。","id":"exchange-028"},{"speaker":"浅野副委員長","kind":"質問・要望","question":"火事とか、そういうときの避難ですね、そういう経路とかに大きな変更があるのかどうか。各部でしょうか、また必要性というものがあれば、ちょっとお聞かせほしいと求めました。","respondent":"阿部経理課長","answer":"この件につきましては、庁舎全体の職員には説明はしています。ただ、今、委員のおっしゃったようなこともありますので、再度、全職員に対して、避難経路含めた指示を出していきたいというふうに思っています。","id":"exchange-029"}]},{"id":"topic-04","title":"３番目、大崎中学校外壁改修その他工事請負契約","agenda":"３番目、大崎中学校外壁改修その他工事請負契約","exchanges":[{"speaker":"林委員","kind":"意見","question":"中身の問題、あまり触れないつもりですけど、９ページの図でいくと、荏原第四中学校の校庭の部分の下の道路、右から左へ一方通行なんですよね。車の出入りはどういうふうに、ここの一方通行のところの車の出入りはどういうふうになっているか、今わかりますかとの意見を述べました。","respondent":"宍戸施設整備課長","answer":"その辺少し警察等とも協議をしながら、なるべくであれば部分的に一方通行の解除をしながら、工事導線を取りたいなというふうに考えているところです。工事会社が決まりましたので、その辺鋭意詰めまして、具体的な工事を進めていきたいと考えていますが、今…","id":"exchange-030"},{"speaker":"林委員","kind":"意見","question":"そうすると、そこから車が、一般車両は入ってきてしまうと思うんです。詰まったり、いろいろとあるとあれなんで、特別にお願いをしておきますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-031"}]},{"id":"topic-05","title":"５番目、平塚小学校校舎・平塚幼稚園園舎解体工事請負契約","agenda":"５番目、平塚小学校校舎・平塚幼稚園園舎解体工事請負契約","exchanges":[{"speaker":"林委員","kind":"質問","question":"１９ページに書かれている中で、４の工事概要のところに「校舎の耐震化を図り、合わせて、当該工事に伴う撤去補修工事等をおこなう」と。撤去補修工事というのはどういう工事なんか尋ねました。","respondent":"宍戸施設整備課長","answer":"ブレース設置というのが屋内運動場にありますけれども、そういった部材を補強しながらもう一度設置するといったようなことを伴いますので、以降こういった工事の説明の際には気をつけようと思いますけれども。","id":"exchange-032"},{"speaker":"林委員","kind":"質問","question":"２１ページの一番下にあるような柱に対してのこういう工事をやるときに、素人判断の言葉だから正しいかどうかわからないけど、そういうような大ざっぱに言うと工事をするんだよと受け取っておけばいいんか尋ねました。","respondent":"宍戸施設整備課長","answer":"そういったような場合には棚を１回撤去をして、またその棚については再設置をしますといったような改修工事なので、そういったような工事を伴いますよという意味合いでの表現です。","id":"exchange-033"},{"speaker":"林委員","kind":"質問","question":"最後に、１９ページの表題に、ページごとに出てるんだけど、鈴ヶ森小学校7)・13)棟耐震改修その他工事、この工事で鈴ヶ森小学校の建物、それから屋内運動場、全部終わりか尋ねました。","respondent":"宍戸施設整備課長","answer":"昨年と２カ年にわたって工事を実はしておりまして、今年度の工事ですべて完了いたします。","id":"exchange-034"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/212618?Template=document&Id=1858#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2010-01-01&TermEnd=2010-12-31"}],"sourceMeta":{"pages":0,"characters":31349,"voices":111}},{"id":"h22-20100630-14","meetingId":"h22-cm06","date":"2010年6月30日","dateIso":"2010-06-30","committee":"行財政改革特別委員会","time":"午前１０時０２分～午後０時０５分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を1件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"堺委員長","kind":"質問・要望","question":"皆様からいただきましたご意見・ご要望等を踏まえまして、先日、理事者のご意見も伺いながら正副委員長で調整をさせていただきました。前回の委員会におきましても確認した点もありますが、改めて、本日この場をお借りいたしまして説明をさせてほしいと求めました。","respondent":"久保田行財政改革担当課長","answer":"第一日野小学校につきましては前回ご説明したとおりということで、９月以降、ＴＯＣに貸し付ける予定です。私からは詳しい説明は省略しますが、旧八潮南小学校につきましては区民活動交流施設として整備する予定で、平成２３年２月に開設する予定であります。","id":"exchange-001"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/438675?Template=document&Id=5886#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2010-01-01&TermEnd=2010-12-31"}],"sourceMeta":{"pages":0,"characters":4032,"voices":9}},{"id":"h22-20100701-15","meetingId":"h22-cm07","date":"2010年7月1日","dateIso":"2010-07-01","committee":"環境対策特別委員会","time":"午前１０時０２分～午後０時３６分","status":"正式会議録","sourceType":"formal","overview":"環境対策特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を47件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"飯沼委員長","kind":"質問・要望","question":"国と東京都の動きとのかかわりについては、早速、本日の調査内容に、ご要望を反映させていただきました。今年度１年間、このような形で進めさせてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-001"}]},{"id":"topic-02","title":"平成２２年陳情第９号、レジ袋有料化に関する陳情","agenda":"平成２２年陳情第９号、レジ袋有料化に関する陳情","exchanges":[{"speaker":"山元委員","kind":"質問・要望","question":"区から配布されているエコバッグというのでしょうか、大まかでいいんですが、量はどのぐらいあるのかということ。どのぐらいいらっしゃるのか、おわかりになれば、教えていただきたいと思うんです。","respondent":"工藤環境課長","answer":"品川区の世論調査を実施いたしまして、「買い物をするときには買い物袋を持って行く」、「マイバッグを持って行く」という項目を設けております。３８％の戻りがあった調査ですけれども、マイバッグの取り組みを常に行うという方が４０％、行動は高まっているとつかまえておりま…","id":"exchange-002"},{"speaker":"山元委員","kind":"質問","question":"小売りというか、小さなお店というか、そういうところではなさっていないんですか。やっぱり対象は、そういうスーパーのようなお店が多いのか尋ねました。","respondent":"工藤環境課長","answer":"品川区の区商連と連携しているマイバッグ運動の取り組みは、２円分のコインなんですけれども、このエコポイント制を指すものだと考えております。例えば、それがたまりましたら１００円のギフト券に交換するとか、そのような取り組みは広がっていると認識しております。","id":"exchange-003"},{"speaker":"川西委員","kind":"質問","question":"「必要ありません」と言ったら、レシートを見たら、買い物をした中から２円引いてあった。質問、はしです。","respondent":"工藤環境課長","answer":"昨年度から実施した事業でございまして、昨年度で言いますと、いわゆるイベント実施時にマイ箸運動の取り組みに賛同した方に対しまして。そういったモデル実施的な取り組みをやっているということであります。","id":"exchange-004"},{"speaker":"川西委員","kind":"確認","question":"１,３００万円は主にレジ袋、区商連がいろいろな運営の中で活用されているということでいいのかどうか、確認したいと思います。どうですか」なんて言ってくださる方は結構多いんですけれども、６本もたまっているから要らない」と言うぐらいなので、意見だけ申し上げます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-005"},{"speaker":"大沢委員","kind":"質問・要望","question":"ちょっと教えていただきたいんですが、１番に載っておりますけれども、ちょっと教えていただきたいのが一つ。それから、理由について、レジ袋無料配布中止に伴う収益金とありますが、これは一体どのような形にあらわれているお金なのか尋ねました。","respondent":"工藤環境課長","answer":"大手のスーパー、いわゆるポイント制を実施しているところで、辞退率が３０％前後と聞いております。区ではこのような取り組みを行っておりませんけれども、レジ袋１枚につき幾らの部分を、いろいろな手法があるです。","id":"exchange-006"},{"speaker":"大沢委員","kind":"質問","question":"商店街を含めて、ビニール袋・紙袋に関しては有料ではなくて、無料でお客様に提供にしているということで考えていいんでしょうかということが一つ。それを説明を求めました。","respondent":"工藤環境課長","answer":"小売店に関しては、いわゆる有料で支給しているというところは、私どもは、ないと把握しております。どういった使い道にするかということを考えてやっているということでありまして、主に環境分野に対しての充実を図っているということです。","id":"exchange-007"},{"speaker":"大沢委員","kind":"質問","question":"商品を袋に入れてお渡しするというような流れでやっているということですから、当然、限られてくると考えていいわけですね。","respondent":"岩田都市環境事業部長","answer":"レジ袋をくださいというと、２円で売ってくれます。だからそれは店によってそれぞれの考え方、引くのかという考え方だけで、一般論で考えるべきだろうと思います。","id":"exchange-008"},{"speaker":"大沢委員","kind":"質問","question":"現状を教えていただきたく、考えていいということで、よろしゅうありますね。はい、わかりました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-009"},{"speaker":"阿部委員","kind":"質問","question":"常識的に考えて、エコポイント制とレジ袋有料化は、二階立てにするということはあり得るんでしょうか。その場合のコスト負担というのは、区がすることになるんですか、それとも、商店がするのか。","respondent":"工藤環境課長","answer":"２点目の、いわゆるポイントシステムを考えて、最初の部分でかなり金額がかかったと思うんです。そういった意味では、またこのシステムを一から構築し直すという話になりますと、相当な金額を要すると思っているところです。","id":"exchange-010"},{"speaker":"阿部委員","kind":"意見","question":"実際にやるとなるとどういう仕組みかというのが決まったわけではないんですけれども、せっかくエコポイント制というのが、一定区内で普及している中で、有料化という違ったやり方に切り替える価値というのが、ちょっと私には見えにくいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-011"},{"speaker":"伊藤委員","kind":"確認","question":"品川区の傾向としては、増やしていく方向だと思うんですが、どういう具体的な商店街との対策をしているのかということを、ちょっとお伺いしたい。確認したいのが、そのほうが具体的な対策になると思うんですが、品川区の考え方を説明を求めました。","respondent":"工藤環境課長","answer":"地域の商店街と連携した取り組みでございまして、全国的に見ても、ほんとうに誇れる事業だと考えています。引き続き、普及・啓発を粘り強く行い、この運動を推進していきたいと考えています。","id":"exchange-012"},{"speaker":"伊藤委員","kind":"質問・要望","question":"そういういろいろな要望に対して、協力していただくように、仕組みは再構築してくださいとだけお願いしておきます。いろいろ混乱が起こったという話もちらほら聞こえてきたんですけれども、何かご存じのことがあれば、教えていただきたいんです。","respondent":"工藤環境課長","answer":"そういった部分に従って、いわゆるマイバッグの対応はしていただいているような状況でありますけれども、コンビニエンスストアに関しましては。今後の区の対応に私どもも注視している状況です。","id":"exchange-013"},{"speaker":"伊藤委員","kind":"質問","question":"条例ですから、私は、この杉並区の実績を通して感じました。意見ですね。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-014"},{"speaker":"中塚委員","kind":"質問・要望","question":"そういう意味で、マイバッグ運動の今後の課題について、品川区はどんなふうにお考えなのか伺いたいと思います。具体的にどう問題が想定されるというか、考えられるのか、ちょっとそこのご説明の中身を教えてほしいと求めました。","respondent":"工藤環境課長","answer":"どういった形で何かできるかということを、今後、区として検討しなければいけないと考えております。説明しましたけれども、価格に転嫁できるところはやはり大手であったり、体力がある会社だと考えています。","id":"exchange-015"},{"speaker":"中塚委員","kind":"質問・要望","question":"最後にもう一つだけ伺いたいのは、マイバッグ運動をされている方への、団体への支援があると、冒頭、ご説明がありました。どんなふうにお考えなのか、団体や個店への支援について、ちょっとご説明いただけますか。","respondent":"工藤環境課長","answer":"先ほど、冒頭に説明いたしましたように、地域団体の協力による環境啓発支援という部分もあります。団体が実施するイベントに際して、私どもが説明しまして、普及を図っているところです。","id":"exchange-016"},{"speaker":"浅野委員","kind":"質問","question":"環境の問題は、直接的な効果と間接的な効果というんでしょうか、そこら辺を考えていかなければいけないのかなと思います。そこら辺のバランスも含めて、直接的な効果と間接的な効果、区のお考えを聞かせてほしいと求めました。","respondent":"工藤環境課長","answer":"大体１７７万ｔと言われておりますので、その中で占める割合は大体約０.３％ぐらいになる、です。レジ袋という象徴的な部分を考えて、環境全体のことを考え、行動につなげていくという部分が間接的な効果だと考えております。","id":"exchange-017"},{"speaker":"浅野委員","kind":"質問","question":"２０万以上というと、１日に五、六百枚消費をするようなことなると思うんです。そこら辺に限定されるものなのか、どうか、ちょっとご意見を伺いたいと思います。","respondent":"工藤環境課長","answer":"年間２０万枚以上というのは、区内でどれぐらいかという部分に関しましては、私どもも把握しておりません。１日５００枚から６００枚使うということで、区内でどれぐらいかというのは、現時点で把握しておりません。","id":"exchange-018"},{"speaker":"浅野委員","kind":"質問","question":"条例を制定すると決まったわけではないので、この点はちょっと参考までにお伺いしたかったのです。例えば具体的にああしろこうしろと言うよりも、啓発を進めいくということをしていってもらえればと、そのように思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-019"},{"speaker":"西本副委員長","kind":"質問","question":"ですから、やはりそういうことも含めて、環境というのは見ていかなければいけないのではないかなと思うんです。マイナス面に対する対応の仕方とか、考え方を聞きたいと思いますが、いかがか尋ねました。","respondent":"工藤環境課長、岩田都市環境事業部長","answer":"そういった中で、当然、レジ袋が少なくなれば、業界の売上げが少なくなるわけですから、しぼんでくる。万引き等も起こりやすくなるという部分もあるわけですけれども、環境対策を推進する必要があると考えています。 それから、今回、ご提案の、条例でお上が国民を縛るというのは、極めて慎重にしなければ、私はいけないと考えています。まずこれが一番大きいというものがあれば、数値でお示しして…","id":"exchange-020"},{"speaker":"西本副委員長","kind":"意見","question":"今後、私たち、環境問題をやっていかなければいけない場合に、やっぱり何をしていかなければいけないのか。どうしても悪者扱いになってしまう部分があると思うので、品川区としてどうしていくんだという議論を、以上で終わりますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-021"},{"speaker":"川西委員","kind":"質問","question":"それらの方へのＰＲ活動というのは、どちらの課がなさるのですか、ということが一つですね。ですから、そういうことを考えると、やっぱりもう少し。","respondent":"工藤環境課長、太田品川区清掃事務所長","answer":"今年度はコイン何枚ぐらい作成するのかとか、そういった中で、予算を組み立てて実施しております。未加盟の商店街に対しては、私どもも、窓口となる区商店街連合会と対策を考えてまいりたいと考えています。 ３点目の、廃棄物減量等推進審議会ですが、先月、たまたま地区の連絡会がございました。発生抑制のところで、マイバッグ運動というお話はさせていただいていますけれども、特にそれに対してご意見というのはございませんでした。","id":"exchange-022"},{"speaker":"阿部委員","kind":"意見","question":"余分な部分を減らすにはどうしたからいいかという発想は、レジ袋製造業者の利益を考えるということは、ここは意図的にやっぱり考えることではない。区としては、その点はどうお考えなのかとの意見を述べました。","respondent":"工藤環境課長","answer":"環境対策を推進するという立場でやっていきたいと考えていますので、その考えは、阿部委員と話が異なっていないと思います。","id":"exchange-023"},{"speaker":"若林委員","kind":"質問","question":"マイバッグ運動の参加状況が、４４商店街で６０１店舗でいいんですか、「品川の環境と清掃リサイクル」という、これは去年版ですね。区商連の補助金というのか、委託金ですか、ここら辺の積算基準というのはわかるんですが、区商連はあまりやる気はないんか尋ねました。","respondent":"工藤環境課長","answer":"考え方もさまざまでございまして、カードを持ってきたりして、小さな商店街だと対応できないというのが実態ではないかと考えています。いろいろとこの取り組みへの考え方の違いがありまして、結果的には、６９商店街のうち４４商店街が加入されているです。","id":"exchange-024"},{"speaker":"若林委員","kind":"質問","question":"平成１４年度から、このままの状態で、果たしてレジ袋の削減はできるのか尋ねました。","respondent":"工藤環境課長","answer":"私どもとしても、すべての商店街が入っていないという実態がありますので、何らかの形で、区商連の事務局と詰めまして、商店街参加店舗数の掘り起こしはやっていきたいとは思っております。","id":"exchange-025"},{"speaker":"若林委員","kind":"質問・要望","question":"では、拡大できるように頑張ってほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-026"},{"speaker":"川西委員","kind":"意見","question":"ＣＯ2削減について、方法はいろいろありますけれども、有料化にすることが一つの方法であろうかと思っています。いろいろこれから１,３００万円が区商連に行っているけれども、大型店舗、あるいは中型店舗、それぞれ区の考え方、環境についての考え方との意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-027"},{"speaker":"伊藤委員","kind":"意見","question":"私たちの会派としては、まず、こういう環境対策を進めていく上で条例制定は必要最低限にするべきだと思っています。今の問題点を把握しながら、品川区は十分に対処していっていただくことをお願いしつつ、この陳情は不採択で臨んでいきたいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-028"},{"speaker":"中塚委員","kind":"意見","question":"レジ袋などプラスチックごみの総量をどう減らしていくのか、どういう手だてが有効なのか、それについても十分な議論は当然必要だと思います。こうしたやるべき対策、やっぱり問題があると思いますので、この陳情については不採択でお願いしますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-029"},{"speaker":"阿部委員","kind":"提案","question":"区内の環境問題、清掃問題について、いろいろと懸念を持たれて、こういったご提案をしてくださった陳情者には敬意を表したいと思います。レジ袋、その他の課題については、さらに検討していただきたいと思っていますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-030"},{"speaker":"高橋委員","kind":"質問・要望","question":"不採択。理由のところの、こちらの陳情の方の思いは十分に理解をさせてほしいと求めましたが、もっと啓発活動を進めることを要望していきたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-031"},{"speaker":"西本副委員長","kind":"質問","question":"いろいろな深い意味があると思っています。質問いたしましたけれども、しっかりとやっていきたいという思いで、今回は不採択としたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-032"}]},{"id":"topic-03","title":"特定事件調査の、地球温暖化対策に関すること","agenda":"特定事件調査の、地球温暖化対策に関すること","exchanges":[{"speaker":"阿部委員","kind":"質問・要望","question":"資料で幾つか教えていただきたいんですけれども、運輸部門１％増加で、このグラフで１９９０年から１３％増加しているように見えないんです。１３％というと、２万ｔ程度増加しているというんですけれども、１９９０年比で横ばいに見えてしまうのは、目の錯覚か尋ねました。","respondent":"工藤環境課長","answer":"数字でいっても確かに１３％増加、この表のとおりでございまして、２１ページをご覧になってください。こちらのほうを見ますと、１９９０年は３８万ｔで、それから４３万ｔに増えているということですので、ご了承いただきたいと思います。","id":"exchange-033"},{"speaker":"阿部委員","kind":"質問","question":"何か事業所の面積とか、数とか、そういうものに係数を掛けて出しているということなのでしょうか。個々の努力というのが反映されるというよりは、むしろ床面積とか、そういうものが反映された数字になるのか尋ねました。","respondent":"工藤環境課長","answer":"もう一つの要因としまして、産業部門がかなり温暖化対策を進めてきたという部分があります。ＣＯ2の換算ですけれども、それぞれＣＯ2の排出係数というものを掛け合わせまして、ＣＯ2の量を確定しているです。","id":"exchange-034"},{"speaker":"阿部委員","kind":"質問","question":"そうすると、この表からは、各部門がどの程度努力しているかということは、とりあえず読み取れないという理解でいいんですか。ではこれだけ増えてきた業務部門で、例えば、どういった支援策があるか尋ねました。","respondent":"工藤環境課長","answer":"こちらのほうも、本章の１７ページに、少し誤解がないような形で明記させていただいたところです。その場合に、機器を入れかえたり、逆に照明を変えたりとかいろいろな方法があろうかと思いますけれども、そういった考え方です。","id":"exchange-035"},{"speaker":"阿部委員","kind":"質問","question":"質問にならないかもしれませんけれども、この２０年間の変化を出すというのは、かなりミスリードを招く可能性が大ではないかと思うんです。とりあえず、今、何かこの意見に関するご見解があれば、いっていただければいいですし、なければ、とりあえず終わります。","respondent":"工藤環境課長","answer":"私どもとしましても、やはり正確に実態を把握したという部分で、このような形で、１９９０年度からの経過を出したところです。１９９０年度というのは、京都議定書に基づく国の基準年度であるということもありますで、このような形になったところです。","id":"exchange-036"},{"speaker":"若林委員","kind":"意見","question":"ＣＯ2の削減について、いきなり、１９９０年から数値がびっしりと出てきている。私は理解しているんですが、資料として出されたものであって、違いますかとの意見を述べました。","respondent":"工藤環境課長","answer":"品川区の中でデータが把握できるものは、ある部分におきましては、かなりの精度をもって出したとお考えいただきたいと思います。区レベルのデータの部分では入らないという考え方がありますので、今回は、入れてございません。","id":"exchange-037"},{"speaker":"中塚委員","kind":"質問・要望","question":"２５％削減にどう貢献しているのか、そもそもつながっているのかというところを、十分に説明してほしいと求めました。事業、事業の概要の説明はありましたけれども、これが２５％削減にどうつながっているのか、ご説明いただけますか尋ねました。","respondent":"工藤環境課長","answer":"削減率を何％下げるかという部分に関しましては、なかなか数量の把握は難しいと、考えております。どれぐらいの実測値を示すということは難しいと考えておりますが、全体としての削減量とか、時期を見ながら把握をしていきたいというのが考え方です。","id":"exchange-038"},{"speaker":"中塚委員","kind":"質問・要望","question":"希望的観測なのか、それとも、やらねばならないのか、そこをもう１回確認したい。このことを具現化していく、明らかにしていくことが必要だと思うんですけれども、いかがか尋ねました。","respondent":"工藤環境課長","answer":"いわゆる２５％というのは、いわゆる長期エネルギー受給計画等を最大限発揮した場は、かなりの削減が見込まれるということをうたっています。品川区の取り組みを盛り込んでおりまして、今回、お示しさせていただいたところです。","id":"exchange-039"},{"speaker":"中塚委員","kind":"質問・要望","question":"これがどうなんだということを伺いたいと思って質問したんですけれども、２５％の関係で、これがどうつながっているのかわからないわけですよ。これはもう事実なわけですから、それはまだわからないですから、。","respondent":"飯沼委員長","answer":"資料は、検討します。昼になったので途中ですけれども、この後、質問の予定のある方、ちょっと手を挙げていただけますか。","id":"exchange-040"},{"speaker":"伊藤委員","kind":"確認","question":"もう指摘されているわけですから、確認だけしたいのが、前々から指摘をさせていただいています。そういうことがあるわけですから、品川区はどの分野にどう展開していくかということを、改めてお答えほしいと求めました。","respondent":"工藤環境課長","answer":"環境学習講座の中でも、今、さまざまな企業と連携して、講座を実施してきています。小さな連携というものは、環境対策を進めることが課題だと考えていますので、連携という部分は十分に考えていきたいと考えています。","id":"exchange-041"},{"speaker":"浅野委員","kind":"質問・要望","question":"国の動き、東京都の動きも鑑みながら、継続的に行っていっていただきたいということを、一つ要望としておきます。１校は取り組んだところがあるということを聞いておりますが、随分取り組んでいるという話も伺っていますし、また表彰制度もあったかと思います。","respondent":"工藤環境課長","answer":"現在、児童の２０％のご家庭で実施されておりますので、その辺の取り組みを広げたいと、今、思っているところです。エコアクション２１に関しましては、私どもとしても力を入れてこの事業を検討したいですので、このような形で入れさせていただいたものです。","id":"exchange-042"},{"speaker":"浅野委員","kind":"意見","question":"同列には扱えないんですけれども、エコアクション２１と、品川区がやっているエコクリーン事業所、レベルは当然違うと思うんですけれども、こちらの品川区の取り組みが、ここであえて載っていなかったのは、何か意図があるのかというところで聞かせてほしいと求めました…","respondent":"工藤環境課長","answer":"エコクリーン事業所の認定事業は、重要な事業の一つでありますが、概要版の中では、少し新しい事業などを出していこうということで、今回、掲載しませんでした。","id":"exchange-043"},{"speaker":"浅野委員","kind":"質問","question":"そういう理由であれば、１行ぐらい増えてもいいかなという気もしますので、ぜひともそういうところにも気をつかってほしいと求めました。自然エネルギーの導入促進の４番目なんですけれども、下から２行目に「エコスクール」化を進め、ちょっとお伺いします。","respondent":"工藤環境課長","answer":"重点取り組み４の自然エネルギーの導入促進の中の、学校等に率先的に導入というところで、私ども、エコスクールということでやっているところです。当然、このような導入の促進を果たしたいということから…","id":"exchange-044"},{"speaker":"浅野委員","kind":"質問","question":"ここら辺の連携は、日ごろ何か行われているのかどうかというところについて、お聞きしたい。今後のエコスクール化に向けて、今後の計画、取り組みみたいなものを簡単にお示しほしいと求めました。","respondent":"工藤環境課長","answer":"今後のことに関しまして、教育委員会のほうに、そのデータ等見ながら進めていきたいと考えています。少し、そういった部分の活用等に関しましても、教育委員会と検討したいと考えています。","id":"exchange-045"},{"speaker":"阿部委員","kind":"質問","question":"参考までにお伺いしたいんですけれども、さらに区として力を入れていくべきではないかと思うんですが、いかがでしょうか。区ですから、シナモニで環境家計簿というのをのぞいてみると、これは一体去年からメンテナンスしていないのではないかと思ったんです。","respondent":"工藤環境課長","answer":"今、区が求められているものは、中小事業者に対しての省エネ診断的なものが大きいと考えておりますので、そのようなことを中心に、進めてまいります。メンテナンスされていると認識しておりますので、もう一度、ホームページのチェックをしながら確認したい。","id":"exchange-046"},{"speaker":"阿部委員","kind":"質問・要望","question":"そういったことも含めて、きめ細かい仕組みをぜひつくって、中小企業での省エネというのを進めていってほしいと求めました。結構動いてもらえるというお話がありましたので、それは中小企業にとっても役立つ話なので、ぜひここはきめ細かくやっていただきたいと思っています。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-047"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/270609?Template=document&Id=6190#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=15&TermStart=2010-01-01&TermEnd=2010-12-31"}],"sourceMeta":{"pages":0,"characters":44122,"voices":124}},{"id":"h22-20100706-10","meetingId":"h22-cm07","date":"2010年7月6日","dateIso":"2010-07-06","committee":"議会運営委員会","time":"午前１０時３３分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を15件整理しています。","topics":[{"id":"topic-01","title":"平成２２年陳情第１０号、議会基本条例の制定に関する陳情","agenda":"平成２２年陳情第１０号、議会基本条例の制定に関する陳情","exchanges":[{"speaker":"土井委員","kind":"意見","question":"議会をどう改革していくべきかということについては、我が会派は、特別委員会をつくって。趣旨を十分に重んじながら、議論の緒につくという方向に持っていっていただけるとありがたい、こんな思いでありますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-001"},{"speaker":"伊藤委員","kind":"質問","question":"議会の改革ということになるかもしれないけれども、逆に、今までやってきた議会の自由闊達な行動が妨げられる可能性もあるわけですから。ですから、一旦今日は持ち帰りさせていただいて、会派の中で十分に検討する。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-002"},{"speaker":"浅野委員","kind":"意見","question":"こういう形で基本条例を制定していくのかどうかということも踏まえて、再度、私どもも深い論議を会派の中でしていきたいと思います。気を引き締めていかなければいけない部分があると思いますので、もう少し時間をかけてじっくりと論議をしていくべきだと考えていますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-003"},{"speaker":"宮崎委員","kind":"意見","question":"でも、こういう趣旨でやってほしいという気持ちはわかる。今日、結論をどうするかというのは別としても、これが議会改革の方向で進んでいければと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-004"},{"speaker":"須貝委員","kind":"質問","question":"一歩でも、前に進むという気持ちが、私は必要ではないかと考えます。２３区の中でもまたさらに先駆的な区なのですから、問題点があれば、そこでまた改正していけばいいのではないかと考えます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-005"},{"speaker":"鈴木委員","kind":"質問・要望","question":"申し合わせ確認事項ということで、その中で、やっていることはご理解をほしいと求めました。自治基本条例的なものも、自民党としても検討していますが、まだなかなか答えが固まっていないというのが現状だというところです。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-006"},{"speaker":"伊藤委員","kind":"質問・要望","question":"独自の条例を制定しているわけですから、二、三回の議論で結論を出す話ではない。私たちとしては、今日は持ち帰りをさせていただきたいということを、お話をします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-007"},{"speaker":"土井委員","kind":"確認","question":"申し合わせ確認事項等もありましたが、何の問題もなくいって、申し合わせ確認事項になるやがゆえに申し合わせに過ぎないという部分もありですから。各会派の話等を伺っていると、この後、どう緒につけていくのかということ等でご努力いただくということが必要ではなかろうかと考えています。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-008"},{"speaker":"阿部委員","kind":"提案","question":"ですから、陳情の扱いもそうなんですけれども、これは提案ですが、まずは議論を始めませんか。この１周しただけでも、多分、ほんとうは議論したいんだと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-009"},{"speaker":"武内委員","kind":"意見","question":"この４年半が長いか、やっぱりある程度じっくりと時間をかけてやっていかなければいけないものだなということは思います。そういう話し合いをする場を、議会運営委員会なのか、どこかで設けるかも含めて、時間をかけてやっていきたいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-010"},{"speaker":"宮崎委員","kind":"質問・要望","question":"ですから、もうぜひ、そういうふうに議論を始めたいと思います。それとあわせて、住民の方からこういう要望が出ているわけですから、そこをあわせながら考えていきたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-011"},{"speaker":"宮崎委員","kind":"質問","question":"自民党、公明党が継続なので、流れとしては、そんな感じになっているんですけれども、私どもとしては、やっぱりそれぞれ議論を始めようとなっているわけですから、趣旨採択でいければと思っています。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-012"},{"speaker":"土井委員","kind":"質問・要望","question":"我々としては、いろいろな状況の中からは、継続という話をしますけれども、中身としては、先ほど、委員長にお話を申し上げましたように、４年半かかったという栗山町のお話を考えれば、その半年を今年やりたいという思いで、継続にさせてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-013"},{"speaker":"須貝委員","kind":"質問","question":"私は、区民からこういう陳情が出たということに対しては、ほんとうに驚いているというか、議会としても、議員としても恥ずかしく考えています。ですから、本日は、結論を出すということと、趣旨採択ということでお願いします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-014"},{"speaker":"土井委員","kind":"質問","question":"継続というのと、採択、趣旨採択、不採択、いろいろありますので、そのうちの継続というのは、結論を出すうちに入るんですか、入らないんですか、今のお話を伺っていると。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-015"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/868696?Template=document&Id=5132#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2010-01-01&TermEnd=2010-12-31"}],"sourceMeta":{"pages":0,"characters":10272,"voices":30}},{"id":"h22-20100720-6","meetingId":"h22-cm07","date":"2010年7月20日","dateIso":"2010-07-20","committee":"区民委員会","time":"午後１時０２分～午後３時３２分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を23件整理しています。","topics":[{"id":"topic-01","title":"を行います。 初めに、(1)の区民活動情報サイトの開設","agenda":"を行います。 初めに、(1)の区民活動情報サイトの開設","exchanges":[{"speaker":"山路委員","kind":"質問・要望","question":"非常にいいことだと思うんですけれども、ちょっと教えていただきたいんですけれども、地域ＳＮＳというものがありますよね。そういうこととの関連性といいますか、それはどういうふうになっているか教えてほしいと求めました。","respondent":"秋山協働・国際担当課長","answer":"今回の区民活動情報サイトにつきましては、ＳＮＳ機能ですとか、電子会議室ですとかという機能は入れてはございません。というのも、１つはマッチングを目的としていますので、今回はソーシャルネットワークサービスとか電子会議室については盛り込んではございません。","id":"exchange-001"},{"speaker":"山路委員","kind":"質問・要望","question":"そうなってくると、これ単独でスタートされるということは、個人ではだめになるわけなんですよね。今後どういうふうにしていくか、そういうねらいといいますか、どういうところにあるのか教えてほしいと求めました。","respondent":"秋山協働・国際担当課長","answer":"ボランティアの募集や、それから仲間を募ったりということで、その活動を活性化していくというのを目的の１つとしているです。","id":"exchange-002"},{"speaker":"山路委員","kind":"質問・要望","question":"行政にどういうふうに生かしていくか、そういう区民同士の活動主体と活動情報を求めている人をつなぐというだけのことか尋ねました。","respondent":"秋山協働・国際担当課長","answer":"ちょっと言葉足らずで申しわけございません。区との協働、基本構想でも区民との協働を進めるということでうたっておりますので、区民との協働をこちらで活性化させていきたいと考えております。","id":"exchange-003"},{"speaker":"山路委員","kind":"質問","question":"区のホームページと相互リンクとこの資料に書いてありますよね。ここはどういうふうな形で相互リンクしていくのか、説明を求めました。","respondent":"秋山協働・国際担当課長","answer":"区のホームページにも情報が載っているところがあります。区民の活動の団体については、相互リンクというのは、区民活動情報サイトのリンクのほうから区のホームページに飛ぶこともできるという意味です。","id":"exchange-004"},{"speaker":"渡辺委員","kind":"質問・要望","question":"あるいは委託の予算規模を伺いたいのと、どう導くのか、その点をお聞かせほしいと求めました。","respondent":"秋山協働・国際担当課長","answer":"ＮＰＯは今のところ、インターネットの得意なＮＰＯを想定していますので、今後検討して、詳細については詰めていきたいと考えているところです。広報広聴課と地域活動課と連携をしてやっておりまして、予算につきましては、全体でたしか７００万円程度だったと記憶しております。","id":"exchange-005"},{"speaker":"渡辺委員","kind":"質問","question":"区のホームページのところだけで言ったんですが、最初の期間だけでも、区の現状の特に目立つところにあってしかるべきかなという思いがあります。検討されているとは思うんですが、その点説明を求めました。","respondent":"秋山協働・国際担当課長","answer":"当然９月１日のサイトのオープンの際には、トップページのところのニュースのほうに掲載をしていくということで考えているところです。区と今までもおつき合いのあるところで、ウェブサイトの構築などをやっているところに、お願いをしていくという予定をしています。","id":"exchange-006"},{"speaker":"渡辺委員","kind":"質問・要望","question":"固有名詞を別に求めているわけじゃなくて、そういう性格のところでそのとおり進めてほしいと求めましたので、それ以上は特別ありません。最初の立ち上げの３カ月ないし半年、開いた上段のところにあるべきかなと思いましたので、そのほうがよろしいかと思う要望で終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-007"},{"speaker":"石田委員","kind":"質問・要望","question":"この２枚目のサイトの案というんですかね。その辺はどういうシステムでしていくのか教えていただきたいのと、寄附がネット上から可能になるのか、その辺を教えてほしいと求めました。","respondent":"秋山協働・国際担当課長","answer":"芸術に関しましては、文化・生涯学習・スポーツというところで芸術関係の団体も入っていただければと考えているところです。もちろんこちらで寄附の申し込みの要旨等が見られたりということはできますけれども、インターネット上での寄附まで可能ということではございません。","id":"exchange-008"},{"speaker":"石田委員","kind":"質問・要望","question":"それは要望で。その１つがまさに寄附の参加だと思うので、ぜひ検討していただいて、実現をしていただきたいなと思うので、これは要望で。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-009"},{"speaker":"菊地副委員長","kind":"質問","question":"２つだけ聞かせてもらいたいんですが、さっき予算が７００万円とおっしゃっていましたけれども、これは立ち上げのための予算という意味なんですか。それともう１つ、それと実際に登録をした団体の方は、その辺の違いをちょっと教えてくれますか。","respondent":"秋山協働・国際担当課長","answer":"最初の年に７００万円で、次の年からはもうちょっと低い金額、半分以下の金額だったと私どものほうでは記憶しています。これに関しては説明会等でも各団体に承認というのがありますので、繰り返し説明しようと思います。","id":"exchange-010"},{"speaker":"菊地副委員長","kind":"質問","question":"今のところがよくわからないんだけれども、承認の基準というのが当然あるんでしょうね。決まったＮＰＯ法人が勝手に判断をするわけではないと思うんですけれども、その辺の基準というのは一体どこにあるのかを教えていただけますか。","respondent":"秋山協働・国際担当課長","answer":"詳細は詰めているところですけれども、そういう内容が入っているものであれば承認はしないで、その内容を登録者に返すという形を考えているところです。","id":"exchange-011"},{"speaker":"菊地副委員長","kind":"意見","question":"そうすると、その基準内容というのは登録団体にのみ知らされる形式になるのか、それとも一般的にこのサイトを通じて、そういう基準を持っていますよということそのものも、このサイトを通じて当初掲載されるようになるのか、ちょっとそこだけ最後にとの意見を述べました。","respondent":"秋山協働・国際担当課長","answer":"利用規約という形で最初に表示をしますし、申込者の方にも利用規約というものをお配りして、それに同意をしていただいた上で登録をしていただくという形をとります。","id":"exchange-012"}]},{"id":"topic-02","title":"の在住外国人の地区総合防災訓練への参加","agenda":"の在住外国人の地区総合防災訓練への参加","exchanges":[{"speaker":"石田委員","kind":"確認","question":"９月から旧第一日野小学校はＴＯＣのほうに貸し出す予定だと思うんですが、この日程で大丈夫なのかという確認が１点と、確認を２点お願いいたします。","respondent":"秋山協働・国際担当課長","answer":"旧第一日野小学校につきましては、９月５日は使用は可能というふうに確認をしています。それから前回は大崎のほうは大使館の関係者が２０名だったんですけれども、これに加えて、在住の方に参加していただければと考えているところです。","id":"exchange-013"},{"speaker":"石田委員","kind":"質問・要望","question":"ただ幅を広げると、それこそ語学の問題とかというのが生じてくると思うので、そういったケアをとりわけフォローしていただきたいなと思います。なかなか大変だと思いますが、頑張ってほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-014"}]},{"id":"topic-03","title":"の品川区民芸術祭の実施","agenda":"の品川区民芸術祭の実施","exchanges":[{"speaker":"高橋委員","kind":"質問・要望","question":"１カ月以上あるので、今、この芸術祭の何が行われているかというのがどこかを見ればわかるのでしょうか。そのページというんでしょうかね、そういうのをつくる予定なんか尋ねました。","respondent":"堀越文化スポーツ振興課長","answer":"２０件程度広告をいただいておりますので、そこの部分についても、プログラムの作成費等には充てるという予定でおります。今、ご指摘いただいたような部分も含めて、できるだけＰＲができるようにしていきたいと考えております。","id":"exchange-015"},{"speaker":"山内委員","kind":"質問","question":"もちろんプロですからギャラも発生するといった中で、それとも中間に業者が入って、その業者がするのか。そういった場合にどうするのかという、その辺を説明を求めました。","respondent":"堀越文化スポーツ振興課長","answer":"若手育成という観点も入れていますので、そういった方々にご参加いただいているですとか、そういったことも含めて積極的にと考えています。例えばご紹介いただくですとか、この芸術祭が皆さんに親しみを持っていただけるような、そういう形で進めていきたいと考えています。","id":"exchange-016"},{"speaker":"石田委員","kind":"質問","question":"先ほど区民芸術祭の実行委員会は１０名ほどだと伺ったんですが、この方たちの平均年齢はどのくらいなんですか。ターゲットが、若い人にどうやって参加をしてもらうという工夫を、どのようなお考えがあるのかお聞かせほしいと求めました。","respondent":"堀越文化スポーツ振興課長","answer":"ジャンルについてはいろいろなジャンルから幅広くということで、ロックですとかクラシックという形で考えたということですね。ただ予想以上に若い方も参加されているなという印象を私のほうは思っております。","id":"exchange-017"},{"speaker":"渡辺委員","kind":"質問","question":"その区分けを、個々は別として、おおむねの割合で教えていただければなと思います。そういう意味で、今年新規でこれがというものはどれぐらいなのか、その辺をいただけたらと思います。","respondent":"堀越文化スポーツ振興課長","answer":"新規のほうといたしましては、表の(2)きゅりあん主催コンサートの４番プルミエコンサートシリーズ、これが新規のものになります。それから合唱団を募集してやるという形になりますので、新規がどうかという形になりますと、こちらが新たな内容として挙げたものに該当いたしま…","id":"exchange-018"},{"speaker":"渡辺委員","kind":"質問","question":"それでまた検証しながら、おそらく新規のものを増やしていくんだろうと思うんですが、現状の割合だけ、おおむねでわかれば教えてください。それと来年への方向性を。","respondent":"堀越文化スポーツ振興課長","answer":"割合といいますと、本数の割合ですか。","id":"exchange-019"}]},{"id":"topic-04","title":"の区立総合区民会館および区立体育館における指定管理者におけるモニタリング・評価結果","agenda":"の区立総合区民会館および区立体育館における指定管理者におけるモニタリング・評価結果","exchanges":[{"speaker":"菊地副委員長","kind":"質問","question":"ちょっと時間がないので１つだけお聞きしたいんだけれども、両方ですけれども、こういう業務をやってくださいねというような部分かもしれないですね。このモニタリングはどちらの視点から出されているものなのか、それの説明をお願いできますか。","respondent":"堀越文化スポーツ振興課長","answer":"指定管理者のほうから報告が上がってまいりますので、その報告を見ながら、総合区民会館と体育館につきましては文化スポーツ振興課のほうでやる。数字の部分は転記という部分もありますけれども、内容についての記述は文化スポーツ振興課で行っているものです。","id":"exchange-020"},{"speaker":"菊地副委員長","kind":"質問・要望","question":"モニタリングですから、これは指定管理者に要望しているわけではないですよね、この中身というのはね。区が責任を持つ部分と、指定管理者に責任を持ってもらう部分と、その辺の振り分けというのはどういうふうに見ていくといいんか尋ねました。","respondent":"堀越文化スポーツ振興課長","answer":"その中の指定管理の中で対応できるのかどうなのかという部分と、大規模な修繕業務というのは直接区のほうから工事を実施するという部分がありますが。受託者側からもいろいろな提案をいただいて、そういう積極的な提案を期待している…","id":"exchange-021"},{"speaker":"菊地副委員長","kind":"質問","question":"建築後何年間か経過をして、区有施設ですから、区としての長期の修繕計画というのは当然必要なんだと思うんですね。そうしないとどうしても全体が見えてこないので、つかみやすいのではないかなと思いますので、この辺はどうなんか尋ねました。","respondent":"堀越文化スポーツ振興課長","answer":"そういったものを出してもらいたいということが１つと、そういった実施時期、効率的に行いたいという部分も含めてあります。ちょっと説明も言葉足らずですが、大規模な部分については、区のほうで一定のイニシアチブをとりながら修繕をしているという状況です。","id":"exchange-022"},{"speaker":"山内委員","kind":"質問","question":"稼働率の考え方をお伺いしたいんですけれども、きゅりあんのイベントホールは３分割して使うじゃないですか。全体を使って初めて１００％の稼働率、イベントホールはなるのか、その考え方をちょっと説明を求めました。","respondent":"堀越文化スポーツ振興課長","answer":"はイベントホールを３分割でという今のお話ですけれども、利用率の算出をする分母の中に含めていますけれども、使用できないと。１つだけとっても使えないというところは、カウントできない部分がありまして、その部分については計算の中に入れておりません。","id":"exchange-023"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/397696?Template=document&Id=2586#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2010-01-01&TermEnd=2010-12-31"}],"sourceMeta":{"pages":0,"characters":22571,"voices":81}},{"id":"h22-20100720-7","meetingId":"h22-cm07","date":"2010年7月20日","dateIso":"2010-07-20","committee":"厚生委員会","time":"午後１時０２分～午後３時４１分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を24件整理しています。","topics":[{"id":"topic-01","title":"高齢者肺炎球菌ワクチン接種費用の一部助成","agenda":"高齢者肺炎球菌ワクチン接種費用の一部助成","exchanges":[{"speaker":"南委員","kind":"質問","question":"１万８,０００人というのは、どうか、ちょっと伺いたいと思います。対象者の２５％と設定した、こういう数字にとどまっているのかどうか、そのあたりのことを伺いたいと思います。","respondent":"吉田保健予防課長","answer":"接種券の送付につきましては、ご指摘のとおり、６５歳以上の区民すべてということで、本年度は７万３,０００人を対象にする予定です。約５割弱といったところが、毎年接種していただいているところですので、その数字を主な目標として…","id":"exchange-001"},{"speaker":"南委員","kind":"質問","question":"５０％まで広げたいという目標をお持ちで、そういう予算を組んでもいいのではないかと思うので、そのあたりのことを伺いたいと思います。非常に経済的に困窮しておられる方々も同時にいらっしゃるわけですから、せっかく助成制度を設けるわけですから、ちょっと伺いたいと思います。","respondent":"吉田保健予防課長","answer":"ぎりぎりのところで、広く周知はしていきたいと考えていますが、ぜひ打ってくださいというような言い方はできないところがあります。通常の季節性インフルエンザワクチンと同様の対応と考えておりますので、同じような扱いという形にさせていただきたいと思います。","id":"exchange-002"},{"speaker":"南委員","kind":"質問・要望","question":"私が伺いたかったのは、正確でなかったら教えていただきたいんですけれども、３,０００円を助成しても。ですから、それ以外の方々の希望をどういうふうに尊重するのか、その辺はどういうふうに整理したらいいのか尋ねました。","respondent":"吉田保健予防課長","answer":"これまで、任意接種につきましては、すべて一部助成という形で対応させていただいているところです。区の考えといたしましては、広く皆様に接種していただくことを一番に考えておりますので、一部助成で一律と考えております。","id":"exchange-003"},{"speaker":"南委員","kind":"質問","question":"それはそれとして伺いたいと思うんですけれども、その辺についても、対応をとるべきだということを意見として申し上げて終わりたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-004"},{"speaker":"山元委員","kind":"質問・要望","question":"９月１日から開始ということであるんですが、受けてしまった方に対しての何か助成というのでしょうか、何かお考えになっていらっしゃるのかどうか。安く受けたという方もいらっしゃいましたので、その辺も、どのように対応なさっているのかを教えてほしいと求めました。","respondent":"吉田保健予防課長","answer":"周知の方法ですが、８月下旬をめどに、６５歳以上の方すべてに封書でお送りする予定です。受けてしまった方への対応ですが、９月１日からの助成ですので、残念ながらお支払いができない状況です。","id":"exchange-005"},{"speaker":"山元委員","kind":"質問","question":"この接種の有効期限はどのぐらいなのか。５年ぐらいと聞いたんですが、それでよろしいんか尋ねました。","respondent":"吉田保健予防課長","answer":"以前は、一生に１回と言われておりましたが、最近では、５年以上の間隔をあけて再接種も可能と言われています。ただ、何回も続けて打てるかというと、そういうものでもなくて、３回以上の接種については、あまり推奨されていないというところもあります。","id":"exchange-006"},{"speaker":"三上委員","kind":"質問","question":"今の質問の中で、５年以上あけなければ、そういう言い方はおかしいのではないのですか。補助のやり方によっては、そういうことが可能だとは言えるかもわからないけれども、そういう説明では、ちょっとおかしいと思いませんか。","respondent":"吉田保健予防課長","answer":"先ほど申し上げましたのは、９月１日以前に接種された方については、残念ながら、今回の助成対象にはならないです。年齢的に、あるいは８０歳になってもう一度お受けになりたいというご希望があった場合には、その券を使って助成をお受けになることができるです。","id":"exchange-007"},{"speaker":"三上委員","kind":"質問","question":"３回打てるなんていう言い方をしていると、５年経ったらまた来るみたいな、そんな雰囲気に受けとめられかねないではないですか。これははっきり言っておきたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-008"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"実際にかかったお金から３,０００円を引くというご説明でしたけれども、３,０００円引いて、そこを説明ほしいと求めました。一部助成と全額助成との考え方の違い、そこが一体何なのか、ご説明いただけますか。","respondent":"吉田保健予防課長","answer":"それから、一部助成と全額助成ですが、区としては、これまで任意接種につきましては、一部助成という考え方で一貫して助成を行ってきたところです。すべて全額助成ということで対応していますので、任意接種につきましては、一部助成とお考えいただければと思います。","id":"exchange-009"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"３,０００円を引いた後にかかる負担が３,０００円から５,０００円だということでよろしいのでしょうか。それが必要だとお医者さんからの指摘がきっかけなのでしょうか、そうなるわけですから、その理由はどこにあるのか。","respondent":"吉田保健予防課長","answer":"小児の任意接種につきましても、３,０００円という考えでやってきているところですし、おおむね半額程度といったことを目標にしています。区外でも積極的にお受けいただくということを考えていまして、その対応として、償還払いというものを設けさせていただいたというところで…","id":"exchange-010"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"同じように助成が使えますけれども、今回は償還払いという制度になってしまう、その理由はどこにあるのか伺いたいと思います。当然あるでしょうけれども、こういう場合の償還払いの制度も必要ではないかと思うんですけれども、その点はいかがか尋ねました。","respondent":"吉田保健予防課長","answer":"２３区内相互乗り入れということで、ほかの任意予防接種につきましては、既にすべて予防接種では償還払いを実施させていただいているところです。区民の利便性も考えて、今回、対応させていただいているということです。","id":"exchange-011"},{"speaker":"中塚副委員長","kind":"意見","question":"限られた財源とおっしゃいますけれども、区民の健康を考えるならば、私はやっぱり無料化も検討すべきだと思います。行政区の違いで受けられる助成が変わるという制度は、しっかりと改善が必要だと思いますので、その点は指摘をしておきたいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-012"}]},{"id":"topic-02","title":"平成２１年度指定管理者の管理に対するモニタリング・評価の結果","agenda":"平成２１年度指定管理者の管理に対するモニタリング・評価の結果","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"それについて、どうなのかということを伺いたいと思います。やっぱり５ページにセルフチェックと書いてあるんですけれども、これはどういうものなのか、ちょっと教えてほしいと求めました。","respondent":"冨岡高齢者福祉課長","answer":"全体的に経管栄養の部分など、医療対応の方が増えているということも、全体的に短くなっている一つの証拠であるかなと思います。そういったその人ならではの情報を１枚のシートにつくりまして、それを共通のケアの情報として対応している、これは独自で活用しているシートです。","id":"exchange-013"},{"speaker":"南委員","kind":"質問・要望","question":"ですから、１００％までとは行かないまでも、それぞれの施設でどういうふうに確保されようとしておられるのか。聞いていらっしゃるところで結構ですから、こういうふうな努力をしていますみたいなものを、教えていただきたいというのが２点目です。","respondent":"冨岡高齢者福祉課長","answer":"１００％を超える部分が出てきているというところで、当然、入院や何かの状況を考えながら進めていくということは必要なのかなと考えています。医療対応が増えているですが、人員の中…","id":"exchange-014"},{"speaker":"南委員","kind":"質問・要望","question":"そこの生活がその方の人生になるわけですから、できるだけ努力をしていただきたいと、ちょっと要望として思います。ちょっと蛇足的な方向になってしまうのかという気もしないでもないんですけれども、要望として訴えておきたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-015"},{"speaker":"稲川委員","kind":"質問・要望","question":"１００％なのか、１２０％だったらオーケーなのか、どういう感覚なのかを教えていただきたいということ。逆に行政として何かするのか、どうなのか、説明を求めました。","respondent":"冨岡高齢者福祉課長","answer":"いろいろな考え方があると思いますが、特別養護老人ホームは９５％ぐらいいけば、ほんとうに相当利用されているところだと考えています。１年で結果がだめだったら、最終的な部分は、次の指定の問題となるかと思います。","id":"exchange-016"},{"speaker":"稲川委員","kind":"質問","question":"利用料が８,１００万円余ですか、平成１９年度は９４％で６,９００万円余というのは、どうなのか。いろいろ思ってしまうのですが、その辺、詳しく説明を求めました。","respondent":"永尾障害者福祉課長","answer":"利用者の所得に応じて金額も変更になってきますので、ほぼ利用率が上がれば、利用料も上がってくるのではないかということは推測できます。平成２１年度が初年度なので、平成２２年度の結果を見ないと、まだ、その辺はきちんとしたお答えができません。","id":"exchange-017"},{"speaker":"稲川委員","kind":"質問","question":"平成２１年度に新法で、では、平成１９年度と平成２０年度を比較したときは、別に新法ではないわけですよね。１,０００万円近く違うのは何でか尋ねました。","respondent":"永尾障害者福祉課長","answer":"障害者の利用料の算定の方法については、平成１５年に支援費制度になって、また平成１８年に障害者自立支援法のほうに変わりまして、その間に結構見直しがいろいろ入っておりますので、単純に比較するのが難しい状況になっております。","id":"exchange-018"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"伺いたいのは、そこをどんなふうにお考えなのか、ご説明ほしいと求めました。予想以上の入院者がなぜ生れているのか、その背景をどんなふうに考えているのか、ご説明いただけますか尋ねました。","respondent":"冨岡高齢者福祉課長","answer":"そういう状況が出て、入院が長くなったりした場合には、新たに入所の対応をするということがうまくいかなかったということであります。やはり個々のケースで、毎年いろいろ変わるような部分があって、あくまでも、結果的に読めなかったということだろうと思います。","id":"exchange-019"},{"speaker":"中塚副委員長","kind":"質問","question":"高齢者ですから、ぎりぎりの状態になってようやく特別養護老人ホームの入所がかなうという実態が背景にあるのではないかなと思っているんです。伺いたいのは、区はどんなふうなお考えを持っているのか、ご説明いただけますか尋ねました。","respondent":"冨岡高齢者福祉課長","answer":"現に入所されている方が、どういう状況で入退院しておられるかという問題と、整備するという問題、ちょっとつながってまいりません。多くの方に入っていただきたいという問題と、全体がどうだということは、ちょっと違う話だと理解をしています。","id":"exchange-020"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"ほんとうに求められているのに、半年ないし１年でお亡くなりになってしまう、そういう話をよく伺うんです。この評価結果では、そこに一言も触れていないんですけれども、その点はどのようにお考えなのか尋ねました。","respondent":"木下健康福祉事業部長","answer":"やはり医療機関での対応が、福祉のほうから見ての場合なんですけれども、そういう傾向が見られるということかと思います。そういういろいろな要因が絡んでおりますので、今のご指摘なようなことだけがこの背景にあるということは当たらないと考えています。","id":"exchange-021"},{"speaker":"中塚副委員長","kind":"意見","question":"今回の指定管理者の管理に対するモニタリング・評価の結果についてですけれども、ぜひ、施設の状況に照らして、整備が足りないもの、そして充実が必要なもの、そういった点はしっかりと検討が必要だと、改めて特別養護老人ホームをしっかり整備することが必要だと、私は思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-022"},{"speaker":"山元委員","kind":"質問","question":"７ページの八潮在宅サービスセンターの下の、ほんとうに車がとめられなかったり、車まで行くのにとても時間がかかると思うんです。とめられないところにとめさせるようなこととか、利用者に負担がかかるわけですけれども、何かそういうことはできないのか尋ねました。","respondent":"冨岡高齢者福祉課長","answer":"利用者を１階まで連れてきていただくようなことができるものについては、そんなふうな形で対応して、できるだけしていると聞いております。","id":"exchange-023"}]},{"id":"topic-03","title":"行政視察","agenda":"行政視察","exchanges":[{"speaker":"南委員","kind":"質問","question":"そうすると、４時間というのは、たっぷりな研修になるんですけれども、大体２泊３日の３日間の中で、どんなプログラムになっていくのでしょうか。１日、１カ所という感じですよね。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-024"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/360687?Template=document&Id=3274#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2010-01-01&TermEnd=2010-12-31"}],"sourceMeta":{"pages":0,"characters":34344,"voices":65}},{"id":"h22-20100720-8","meetingId":"h22-cm07","date":"2010年7月20日","dateIso":"2010-07-20","committee":"建設委員会","time":"午後１時０３分～午後３時１１分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を42件整理しています。","topics":[{"id":"topic-01","title":"平成２２年８月都営住宅入居者募集","agenda":"平成２２年８月都営住宅入居者募集","exchanges":[{"speaker":"藤原委員","kind":"質問・要望","question":"都営住宅なので、答えられる範囲で結構なんですけれども、いわゆる福祉住宅ですよね。大ざっぱでいいんですけど、大まかな流れというか、実績がわかれば教えていただきたい。","respondent":"柏原住宅担当課長","answer":"一定の期間、最終的には高額所得者というふうな位置づけになりましたら、基本的には退去していただくという形で流れているはずです。区営住宅も同様にやっておりますので、都営住宅も同じ法律でやっておりますので、同じようにやっているはずというふうに考えております。","id":"exchange-001"},{"speaker":"藤原委員","kind":"確認","question":"都営だから、最後にはいわゆる家賃を払わない方みたいに裁判をしてまで出させるぐらいの措置をしているのか。都営のあれだから、聞けないけど、その辺はがっちり、みっちり、やっていっているのかということだけは確認の意味で説明を求めました。","respondent":"柏原住宅担当課長","answer":"そこは入れない、おそらくですけれども、いろんな形を使って退去していただくということでご理解はつくれるものというふうに思います。そういった方たちが出てきた場合には退去していただくということで進めていくということで考えております。","id":"exchange-002"},{"speaker":"安藤委員","kind":"質問・要望","question":"単身者向け住宅の収入要件といいますか、どれぐらいなのかという、大体月収にするとどれぐらいになるんでしょうか。シルバーピア住宅というのは何なのかご説明いただきたいのと、年に４回大きく都営住宅の募集がありまして、その理由を説明を求めました。","respondent":"柏原住宅担当課長","answer":"緊急時対応のための生活協力員、バーデンと言われたり、もしくは通勤してそういった方たちをサポートするといったことの住宅です。一般の方ですとおおよそですけれども、大体年間で２００万円程度です。","id":"exchange-003"},{"speaker":"安藤委員","kind":"質問","question":"２００万円ぐらいといいますと、新聞は毎月３,０００円以上しますので、なかなか購買できない方がかなりいらっしゃると思うんですね。ですから、そこら辺はどうお考えなんか尋ねました。","respondent":"柏原住宅担当課長","answer":"お問い合わせいただいたという方がかなり多いというふうに感じておりますので、やり方としましては、こちらのほうが中心になってくるんだろうなというふうに考えております。","id":"exchange-004"},{"speaker":"安藤委員","kind":"質問・要望","question":"ぜひ広報広聴課などとも連携をとって、広報「しながわ」の全戸配布も含め、さらに届くように改善していただきたいなということで要望します。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-005"}]},{"id":"topic-02","title":"の平成２２年度地区総合防災訓練・職員防災訓練","agenda":"の平成２２年度地区総合防災訓練・職員防災訓練","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"参加者の人数が昨年は１万４,０００人ということなんですが、経年的に言いますと、参加者の方は増えてきているのか。例えば町会以外の参加者の方々というんですかね、そういうような方々というのは、参加しているのはどういう人が参加しているのかお伺いします。","respondent":"佐藤防災安全担当課長","answer":"ご存じのとおり各中学校にＤ級ポンプを配置していることから、今年度につきましては、８中学校が地区総合防災訓練に参加する予定です。そのほか、昨年度も各大使館に声をかけて、外国人が参加するということも、今年度も同様に実施する予定です。","id":"exchange-006"},{"speaker":"安藤委員","kind":"質問・要望","question":"これからも頑張っていただきたいんですが、これからも参加者を増やしていくためにどんな工夫をしていくお考えがあるのかというのをお伺いします。勉強できるというのがすごく明確になれば、そういった広報上の工夫とかを含めて、参加者をこれから増やしていく考えをお伺いします。","respondent":"佐藤防災安全担当課長","answer":"９月１日の児童引き渡し訓練において、そういうところでも実施し、他の中学校でも波及できることを検討してまいりたいと考えております。やはり、基本的な訓練を毎回毎回実施することによって体が動いて、基本的な訓練については引き続きやらせていただきたいと考えております。","id":"exchange-007"},{"speaker":"安藤委員","kind":"質問・要望","question":"何で難しい面があると思っていらっしゃるのかというのをちょっともう少し聞かせていただきたいのが１点と、いつぐらいから実施されているのか、その２点をお願いします。","respondent":"佐藤防災安全担当課長","answer":"微増でも先ほど申し上げたとおり、新たな訓練を導入させたり、助言したりして増やしていきたいという考えです。自衛隊のヘリコプター離発着訓練につきましては、昨年度から天王洲野球場で実施している訓練です。","id":"exchange-008"},{"speaker":"阿部副委員長","kind":"質問","question":"防災訓練は防災訓練で大切だとは思うんですけれども、そういったことがなかなか訓練から見えてこないなと何となくいつも感じているところです。ですから、今のは今のでいいんですけれども、何かそういった視点を加えた工夫というのも今後あればいいなと思うんですが、いかがか尋ねました。","respondent":"中山防災課長","answer":"それも３日間ではなくて、もうちょっと長い期間。備蓄倉庫をどうするか、これを今後３８棟の管理組合に私どもが働きかけまして、ちょうどそういう話が出てきているところです。","id":"exchange-009"},{"speaker":"阿部副委員長","kind":"意見","question":"５階、１０階ぐらいであっても、やっぱり戸建てとは違う逃げ方みたいなものがあると思うんですね。超高層に完全に絞り切らないで、ある程度集合住宅ということで広く使えるような何か方策というのも考えていただければいいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-010"}]},{"id":"topic-03","title":"の戸越幹線貯留管中流部整備工事における今後の対策","agenda":"の戸越幹線貯留管中流部整備工事における今後の対策","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"冊子の２３ページのまとめのところなんですが、原因が完全にわからなくても、対策というのは立つのかどうかというのをちょっと知りたいんですね。回覧板などは出したと思うんですが、ポスティングは現場から半径何メートルとか、そういう決まりとかはあるのかお伺いします。","respondent":"藤橋都市整備下水道課長","answer":"これは資料の２２ページのところをご覧いただきたいと存じますが、先ほど説明した図ですけれども、さまざまな角度から原因を調査いたしました。今回は７月２日の事故調査検討委員会第３回の会合が行われた以降…","id":"exchange-011"},{"speaker":"安藤委員","kind":"質問・要望","question":"その範囲とかはいろいろ課もおありと思うんですが、ぜひやっていただきたいと思うんですが、いかがか尋ねました。","respondent":"藤橋都市整備下水道課長","answer":"これまでも３月１６日の出水以降、地域の方々へ直接区の職員が出向いて説明を行ってまいりました。ただ、改めて２回に分けて説明会を開催するという形をとりましたので、十分地域の方々への案内をさせていただいたというふうに考えております。","id":"exchange-012"},{"speaker":"安藤委員","kind":"質問・要望","question":"要望です。工法で新たに区から２.８億円というのは、事業負担という点ではどのようになるのか、お金の出どころはどこになるのかお伺いしたい。","respondent":"藤橋都市整備下水道課長","answer":"報告書の２７ページ、２８ページの一覧表で示していますお金につきましては、この対策工法以外に現場で発生する経費が多々あります。下水道局からの受託事業ですので、基本的には品川区の負担はなく、東京都下水道局が最低限必要な費用を負担するという形になります。","id":"exchange-013"},{"speaker":"阿部副委員長","kind":"確認","question":"すみません、ちょっと確認をさせてください。特に業者側には落ち度がなくて、都なりがこのエキストラの費用については負担をするのだというところで決着したということでよろしいんか尋ねました。","respondent":"藤橋都市整備下水道課長","answer":"したがいまして、事故調査検討委員会での調査検討を行ってきた中で、そして施工に関して積極的に協力するという立場をとってきてあります。対策について、あるいはこれまでかかった経費につきまして、施工業者も負担するということになろうかというふうに考えております。","id":"exchange-014"},{"speaker":"阿部副委員長","kind":"確認","question":"これは最大径であったということなんですけれども、この大きさではふだんは別の工法をとっているということなんですか。最大径１２ｍあったら、普通はアーバンリング工法ではなくて、別のをやっているけど、今回は大きいけど、これをとったということか尋ねました。","respondent":"藤橋都市整備下水道課長","answer":"１２ｍまでできないというわけではなくて、いろいろと状況を考えて、この方法を検討されたという状況です。２番目、あるいは東京都下水道局でも１１ｍ規模の同じような工法を採用しているところがありますので、幅広い工法の中で選定されたです。","id":"exchange-015"},{"speaker":"松澤委員","kind":"質問","question":"やっぱり一番大変なのは三ツ木公園のそばなわけですから、２３日、２６日に開くというのはよくわかりますよ、丁寧に。何で三ツ木会館で２回ともやらないんか尋ねました。","respondent":"藤橋都市整備下水道課長","answer":"今回の貯留管自体は、二丁目も含めまして、やはり全体についてきちんと説明していく必要があるというふうに考えて２回開催したい次第です。これに限らず逐次説明会なり、昨年度実施しましたように、地域の方々に直接説明して。","id":"exchange-016"},{"speaker":"阿部副委員長","kind":"質問","question":"この対策方法の選定表みたいなものを、住民説明会で出されるんでしょうか。２７ページの遮水性能のところに（安定性）と書いてあって、この資料は、もし外に出ることがあるなら少し慎重にされたほうがいい。","respondent":"藤橋都市整備下水道課長","answer":"地元説明会におきましては、やはりわかりやすく説明しなければなりませんので、パワーポイント等でわかりやすく整理した資料をお示しする予定です。そういったものを使ったり、あと模型をちょっと使って、立体的にもう少し地域の方が見られるような方法を考えております。","id":"exchange-017"},{"speaker":"安藤委員","kind":"質問・要望","question":"ちょっとそこら辺がわからないので教えていただきたいのと、運営委託料と使用料収入の関係がわからないので教えてほしいと求めました。たびたび出てきます利用者から要望のあるきめ細かな料金設定とは、何を、どういうことを指しているのかお伺いしたいと思います。","respondent":"藤木交通安全担当課長","answer":"こういったいろいろな要望が私どもに来る中で、一定時間無料とかにはできないのかとか、そういうご要望なども来ております。その辺の検討はしていく必要があります。","id":"exchange-018"},{"speaker":"安藤委員","kind":"質問","question":"委託料が２億円少しで、これは２億円に届いていないので、そういうことですか。アンケート実施というのはすごいいいことだと思うんですが、やっぱり利用者のアンケート実施に至る背景とかというのは、何かあったんか尋ねました。","respondent":"藤木交通安全担当課長","answer":"管理員に対する印象、あと要望事項、全体的な満足度というようなものを調査させていただきました。","id":"exchange-019"},{"speaker":"安藤委員","kind":"提案","question":"それはどっちかというと区のほうでそういうことをやってほしいというのでやってもらっているということなんでしょうか。今後、なかなかそういう提案が向こうから出てこないというのは何か原因があるんか尋ねました。","respondent":"藤木交通安全担当課長","answer":"こちらのほうからお願いして、それで区のほうで承認して、じゃあこういうことをやってくださいということでやらせていただいております。平成２１年度中は目立った提案が出されなかったということで、あとは区が現在検討されている五反田の地区あたりでは、提案がなかったです。","id":"exchange-020"},{"speaker":"安藤委員","kind":"提案","question":"ちょっと昨年の半ばに出されたという五反田の話とかというのは、それはそれで立派な提案というか、大事な現場からの提案だと思うので、それはこたえていく必要があると思うんですが、その点に関しては、区としてはどのように対応したということなんか尋ねました。","respondent":"藤木交通安全担当課長、岩田都市環境事業部長","answer":"昨年の９月に増設させていただきまして、もろもろの問題を現在検討して、実施に向けてどうにか実現したいと検討を進めているところです。 一方の撤去・保管のほうは、公権力の行使を伴う事業ですので、指定管理業務にはできないということで、区の直轄事業としてやっているわけです。一番望ましい撤去費用のかけ方、それから維持管理のあり方というトータルで提案をしなさい…","id":"exchange-021"},{"speaker":"藤原委員","kind":"確認","question":"一つ確認をしたいんですが、今まで品川区において利用者負担ということで有料だ無料だということをずっとやってきたわけですよね。確認なんですけど、また無料に対しての検討というのを区として始めちゃうんか尋ねました。","respondent":"藤木交通安全担当課長、岩田都市環境事業部長","answer":"藤原委員がただいまおっしゃったとおり、駐輪場の使用料というのは、法令上、公の施設の使用に対する反対給付という性質を有するものです。せっかく有料… あるいは商店街、当然そういう事業者の方々が一定の負担をする中で、１時間無料ということも可能は可能です。ただ、これについては、やはり事業者との今後のそういう話し合いが必要だということでご理解をいただきたいと思います。","id":"exchange-022"},{"speaker":"松澤委員","kind":"質問・要望","question":"住宅についてお伺いしたいんですけど、そのほかが品川宅建管理センターということですが、この管理委託料がそれぞれ予算で幾らになっているのか。それと、家賃はどれぐらいあったのか、その管理委託料というのは、家賃の何パーセントぐらいになるのかという数字を教えていただきたい。","respondent":"柏原住宅担当課長","answer":"１億９,９７３万１４円、宅建管理センターのほうにつきましては、管理委託料というのがそのまま精算した金額です。大体２５％ぐらいなんですけれども、その細かい数字はちょっと今あれなんですが、２０％を切るぐらいになるんではないかです。","id":"exchange-023"},{"speaker":"松澤委員","kind":"質問","question":"そのパーセンテージで聞いたんですが、そんなに高いんですか。間違いじゃないんか尋ねました。","respondent":"柏原住宅担当課長、片田防災まちづくり事業部長","answer":"大体２０％を切るぐらいかというところで、それから所得等の考え方で決まっておりますので、こういった形になっているです。管理に関しては… 今この数字だけで言いますと、実質的には国の補助金を入れると１０％台と言いましょうか、２０％は当然切る金額での委託金になってきていると。… 申しわけございません。小破修繕であるとか、大規模的な修繕であるとか、そういった工事費も全部含めた形でこちらの委託料に入っております。","id":"exchange-024"},{"speaker":"松澤委員","kind":"質問","question":"あのね、いいですか。本来利益なんか出しちゃいけないものなんですから。","respondent":"岩田都市環境事業部長、柏原住宅担当課長","answer":"役所ですから大体５０年から５５年で償却しますけども、大体４０年で償却してしまいますので、おそらくマイナスになる可能性はあります。それに税を投入しているわけですから、当然トータルではマイナスになってしかるべきだと… 家賃に対して５％ぐらいです。入居管理。","id":"exchange-025"},{"speaker":"松澤委員","kind":"質問","question":"今の時代ですから。どうです、その辺、考えたことないんか尋ねました。","respondent":"冨久増用地担当課長","answer":"おそらく民間で言えばサブリース契約あたりを想定しているのかなというふうに考えられるんですが、大家はあくまで役所であるという認識の前提ですので、単純に民間と比較をしていくというのはかなり難しいのではないかというふうに考えております。","id":"exchange-026"},{"speaker":"松澤委員","kind":"意見","question":"ただ大変だということなんです。その辺をしっかり考えていただいて、今度は本会議でやりますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-027"},{"speaker":"阿部副委員長","kind":"質問・要望","question":"放置自転車が減れば撤去費用だって減るわけですから、指定管理者に対して検討するように指示しているというようなご答弁をいただいたかと思います。個人的に、東急の高架下とか、ああいうのは使えないんでしょうかね。","respondent":"藤木交通安全担当課長、岩田都市環境事業部長","answer":"この辺は、先ほど部長からも説明しましたとおり、原則として通勤通学の方を対象に我々の自転車駐輪場の解消対策をやっているわけです。歩道上をどうにか使いたいみたいなことを考えてはいるんですが… 引き続き区が経営していかなきゃいけないだろうという基本的な考えを持ちながら将来の駐輪場のあり方というのを今検討していくと。あれだけ市街化したところで、そのときには駅広の再構築も含めて…","id":"exchange-028"},{"speaker":"阿部副委員長","kind":"質問・要望","question":"実際には、ちょっと置いて、何か銀行かなんかに行ってすぐ帰ってきてというような使い方は実際にしているわけですからね。そうでないと、やっぱり放置自転車を置くなと区民に対して言えないですから、五反田については、今あの状況では。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-029"},{"speaker":"渡部委員","kind":"質問","question":"パーセンテージででてきているんですけど、何をもって分母と分子になっているのか教えてください。見方がわからない。","respondent":"藤木交通安全担当課長","answer":"当日利用ですと、例えば一つのラックに対して、お二人の方が利用したとなると、それは２００％になります。その辺の年間を通じてならした数字がこちらです。","id":"exchange-030"},{"speaker":"渡部委員","kind":"質問","question":"ということは、例えば自転車の当日利用が８９.１％とありますけど、このときの分母というのは１００ではないわけですよね。３００とみなしているのかという分母の基準を教えてもらわないと、２回転とみなしているのか、１ラックに対してあるのかどうかということなんです。","respondent":"藤木交通安全担当課長","answer":"１ラックに対して１日１台、１件ということになります。","id":"exchange-031"},{"speaker":"渡部委員","kind":"確認","question":"じゃあ確認だけします。今回１２０何％というのがあったので、１００個あるところに１２０台入っているという計算ですよね、イメージとして。","respondent":"藤木交通安全担当課長","answer":"そうです。","id":"exchange-032"},{"speaker":"若林委員","kind":"質問","question":"自転車のほうなんですが、今後利用料制度も考えられるかどうか、考えるなんていうことはできないんでしょうか。責任を持っているわけですが、指定管理者もそこで何か責任といったらいいんですけど、何か努力をする部分というのはあるんか尋ねました。","respondent":"岩田都市環境事業部長、柏原住宅担当課長","answer":"例えば大井町駅の東口なんていうのは、常に満杯状態ですけれども、天王洲アイルは２０数％の利用ということで、余りにも差がある。したがって、満杯のところは料金を上げられるかということも含めて… 指定管理者のほうは、６月の公募の時期があるんですけれども、随時募集という形で指定管理者にしていただきます。表の出し方につきましては、ちょっと一定の区全体のフォーマットでやっておりますので…","id":"exchange-033"}]},{"id":"topic-04","title":"行政視察","agenda":"行政視察","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"かなり密集住宅というところとはちょっとイメージが違うような感じがするので、これももう少し時間をかけてぜひしていただきたかったなあという印象があるので、ちょっと次回以降の運営に生かしてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-034"},{"speaker":"阿部副委員長","kind":"質問","question":"ですから、これでだめなら行かない。二者択一ぐらいの、そういった状況であるということもあわせてご理解をほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-035"},{"speaker":"若林委員","kind":"質問","question":"この景観まちづくりのかぎ括弧の中は、何か公式に出るんでしょうか。表に出るのか。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-036"},{"speaker":"阿部副委員長","kind":"意見","question":"これはそれぞれの都市がこのテーマで一つの事業を進めているという面が大きいです。私たちが盛岡でぜひお城を見ようということではなくて、このまちはお城を中心とした景観まちづくりをしているとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-037"},{"speaker":"若林委員","kind":"意見","question":"区民にどういうふうに出るのか。委員会報告とか、ホームページ等々との意見を述べました。","respondent":"原委員長","answer":"基本的にはないと。ないというのは、具体化として、今丸印がついているところは出していこうという考えで、正副では考えております。","id":"exchange-038"},{"speaker":"安藤委員","kind":"質問・要望","question":"今委員長から説明いただいたんですが、３番目の秋田市のほうの市街地再開発というところですけれども、これもこちらの選定から見るというか、何を視察に行くのかというのを説明していただきたい。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-039"},{"speaker":"安藤委員","kind":"質問","question":"ちょっとどうしても行かなくちゃいけないという必要性が、それは委員長にちょっとご意見を伺いたいというか、私はそういうふうに思います。","respondent":"原委員長","answer":"前回のお話の流れとして進めてきたのは、行くという方針を前提のもとに正副で案をまとめさせていただきました。一応取り決めとして、建設委員会としては行こうということで、都市を探したという状況です。","id":"exchange-040"},{"speaker":"安藤委員","kind":"質問・要望","question":"ちょっとやっぱり議論の日数が足りなかったというのが今回かなり厳しい状況にあったと思います。最初の意見に戻るんですが、要するに次回視察を検討していく上で、この委員会運営にぜひ改善をしていっていただきたいなという私の意見です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-041"},{"speaker":"渡部委員","kind":"質問","question":"僕自身も実は候補地が難航しているんだという話を伺ったときに、ああいうところに行ってみたいなというのを実は正副には発言させてもらいました。正副、お疲れさまでした。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-042"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/483234?Template=document&Id=3984#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2010-01-01&TermEnd=2010-12-31"}],"sourceMeta":{"pages":0,"characters":38093,"voices":118}},{"id":"h22-20100720-9","meetingId":"h22-cm07","date":"2010年7月20日","dateIso":"2010-07-20","committee":"文教委員会","time":"午後１時０２分～午後３時１２分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を29件整理しています。","topics":[{"id":"topic-01","title":"の平成２２年度「通学区域の弾力化」に関するアンケート調査結果","agenda":"の平成２２年度「通学区域の弾力化」に関するアンケート調査結果","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"選択制が始まって１０年、１１年、大きな流れのこの１０年間を見ている部分の評価とか課題とかがあったら教えていただきたいです。そういう部分で、これは全体的な平均なんですけれども、その辺の違いが出ているかどうかというところをまず説明を求めました。","respondent":"富田学務課長","answer":"やはり施設一体型一貫校については、それを理由として選んでいる方々が当然のことながらかなりの割合でいらっしゃるというのは聞いております。一体型の一貫校ほどは多くないですけれども…","id":"exchange-001"},{"speaker":"飯沼委員","kind":"質問・要望","question":"私たちが知るすべがあるのかどうか、そこが１つと、傾向的な部分で地元の学校を選んでいるという具体的なパーセンテージ的にもあるんですか。その辺の変化というのを知るすべがあるのか、ちょっとそこも説明を求めました。","respondent":"富田学務課長","answer":"申しわけないんですが、学校ごとの数字につきましては、さまざまな学校ごとのそういった差異がかなり出てくる場合もあります。今後の学校経営に役立ててほしいということを目的として学校にお知らせをしているものですので、ちょっとこちらでの報告というのは控えします。","id":"exchange-002"},{"speaker":"飯沼委員","kind":"質問","question":"その二極化現象というのはどうとらえていらっしゃるのか１つ伺いたいのと、地域の方々の意見もぜひアンケートとかでとられたらよいのではないかなと思うんですが、その辺はいかがか尋ねました。","respondent":"富田学務課長","answer":"毎年毎年保護者の方々それぞれのお考えで選ばれており、固定化されているというようには全く考えておりません。学校を選ぶ、我が子をどの学校に進学させるかということについてのアンケートですので、ちょっと地域の方向けのものとは異なるということです。","id":"exchange-003"},{"speaker":"飯沼委員","kind":"質問","question":"保護者の皆さんに向けてのアンケートは、これ以外にほかにどういうものがあるのかということを説明を求めました。","respondent":"和氣小中一貫教育担当課長","answer":"これ以外に、毎年３月にすべての保護者、１年生から９年生までの保護者すべての３分の１を対象にしたアンケートをとってあります。これはまたまとまり次第、検証を順番に出します。","id":"exchange-004"},{"speaker":"西本委員","kind":"質問","question":"途中抜けている数字がないですか。なので、それはどこへ行ってしまったんですかねところが１つ。","respondent":"富田学務課長、和氣小中一貫教育担当課長","answer":"「学校の特色ある教育活動を考えて」ということで、小中連携、教育活動全般で選んでもらおうということで変えたということです。これが昨年度４番目の選択理由であったということです。 しっかりと説明をするという機会が大変少ない、改めてプロジェクトチームを組みまして、いかに周知を図っていくのか。研究をし、具体化を進めているところですので…","id":"exchange-005"},{"speaker":"西本委員","kind":"質問","question":"やっぱり地域の学校というべきだと思っているので、その辺の動きがどういうふうになっているんですかということをお聞きしています。この中にやっぱり友人・知人からの情報によってという部分があるものですから、そうならないようにするためにも、それは今後。","respondent":"富田学務課長","answer":"どれをとっても、さまざまなお答えの方がいらっしゃるわけで、お一人一人のご家庭により違うということもある。新しいそういった課題を考えていく大きな参考になるのではないかなと、このアンケートについては思い、毎年実施をしているところです。","id":"exchange-006"},{"speaker":"西本委員","kind":"質問","question":"選択ですから、選択基準は個々によって違うかもしれないのは当然なので、このアンケートの結果がいろいろあるというのはわかるんですよ。でも、それに対してどういうふうな方式のものをやっているんですか、どういう方向性にあるんですかということをお聞きしているんですけれども。","respondent":"若月教育長","answer":"そして時期を決めて比較検討するということには非常になじみにくい部分がありまして、各学校は努力しています、頑張っています。しかし、今申し上げましたように、各学校個別の課題は私たちも認識しています。","id":"exchange-007"},{"speaker":"井上委員","kind":"質問","question":"その人たちにとって２がどうであったかという評価の仕方が必要で、それはここには出されていないけれども、学務課としてそういう方法でやっているのか尋ねました。","respondent":"富田学務課長","answer":"これはクロス集計をしたものではないので、それぞれの単純集計、大きく分けたごとの単純集計ですけれども、かなり特定される形での自由意見等もありますので、そういったものを含めて、それは学校にこういった意見があるということは伝える仕組みがあるところです。","id":"exchange-008"},{"speaker":"井上委員","kind":"質問・要望","question":"それを区が求めていくような方向に進めていくという意味では、検討していただきたいというふうに思うんですが、考え方としていかがか尋ねました。","respondent":"富田学務課長","answer":"このアンケート調査の集約の中でも、これも１つのシステムを使ってやっております。例えば全体の数の中で１,４０５人が従来の指定校に行ったことで、こういった全体の傾向が大きくつかめればいいものというように考えております。","id":"exchange-009"},{"speaker":"井上委員","kind":"質問・要望","question":"教育長は、そういうところに対して感情的な意見で正確なデータではないというような議論が行くのはすごくいけないことだというふうに思うんですね。これは要望させていただきたいというふうに思いますので、ぜひ検討してほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-010"},{"speaker":"金野委員","kind":"質問","question":"２つほど委員の質問の中でご説明があったのが、数字から見るねらいというのでしょうか、そういったところはどのようにお考えか尋ねました。","respondent":"富田学務課長","answer":"小学校については平均で８.３９％ということで、選択肢３つの中ではかなり高いなというのが印象です。これは本当にその学校長によりかなりの幅があるわけでございまして、学校に返すに当たっては非常に参考になったのではないかと考えております。","id":"exchange-011"},{"speaker":"金野委員","kind":"質問・要望","question":"生徒、保護者にかかわって、さらにかかわっていただきたいということを要望しておきます。それはあくまでも選択ですからあれなんですが、公立学校がそこを目指して頑張ってくださっているからこそ、そこら辺のところを要望します。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-012"},{"speaker":"西本委員","kind":"質問","question":"リーダーシップはどうやって判断するんだろうなと、すごく不思議な設問だなと思っているんですけれども、これは何か理由があるんですか。簡単にリーダーシップと書いてある人が多いからということなんか尋ねました。","respondent":"富田学務課長、市川教育次長","answer":"リーダーシップというのは１つの象徴でありまして、学校行事等もありますので、かなり積極的に学校に行かれています。あるいはしてくれなかったとか、校長先生の説明が本当によかったとか… いわゆる口コミ、地域の評判ですとか、そういうものでさまざまあると思います。個別の学校にとっては、それが今後の学校をどうするかということにとって大変ウエイトのある判断要素になるというように考えております。","id":"exchange-013"},{"speaker":"西本委員","kind":"質問・要望","question":"兄弟関係でというのであれば、経営がどうされているかとわかると思うので、いいという人はここに丸をつけるのだろうなと思うんですね。もうちょっと細かく分析結果をしてあげないと、いい方向にできるようにアンケートの結果を利用していただきたいなと、意見で終わりたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-014"},{"speaker":"伊藤副委員長","kind":"質問","question":"それから、公立中学校の設問の中の２０番、「男子校または女子校だから」、これは公立のほうは要らないんじゃないでしょうか。その２つを質問させてほしいと求めました。","respondent":"富田学務課長","answer":"無記名で回答をいただいておりますので、公立のお子さんだけこの用紙とかということで選別することができませんので、申しわけありません。設問自体を入れることがどうかということについては検討したいと思います。","id":"exchange-015"},{"speaker":"伊藤副委員長","kind":"確認","question":"済みません、質問の仕方がわかりにくかったですかね。同じ意味で、中学校がないのかなという素朴な疑問なんですけれども、何かしらもしお考えがあるのであるならば説明を求めました。","respondent":"富田学務課長","answer":"これは正式には小学校という位置づけを小中一貫校の小学校の部分についてもしておりますので、このような表現をしておりますが、回答しにくいというようなことも考えられますので、これについては検討したいと思います。","id":"exchange-016"},{"speaker":"井上委員","kind":"質問","question":"指定校があるわけで、すべきではないというふうに私は思っているので、簡単に検討しますとか言ってほしくないなというふうに思うんです。意見としては、そこが指定校という人はいるわけで、ちょっと違うのではないでしょうかということを意見としてだけお伝えしておきたいと思います。","respondent":"富田学務課長","answer":"わかりにくい答弁で申しわけございません。どちらの小学校に入学しましたかのところに、小学校（小中一貫校）ということでの表記に変えることは検討できるかなと考えています。","id":"exchange-017"}]},{"id":"topic-02","title":"の児童扶養手当制度改正","agenda":"の児童扶養手当制度改正","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"５年間たったらなくなる、その制度がどうなっているのかと、父子家庭も全く同じかどうかということを説明を求めました。","respondent":"安井子育て支援課長","answer":"就労支援にも力を入れるということで、就労支援の相談員も各自治体で増員して、顔を合わせての支援を行うとかということで。やはり基本的に手当をばっさりただ切るという方針でやっているわけではありませんので、なるべく自立支援のほうへ向かっていただきたいということで。","id":"exchange-018"},{"speaker":"飯沼委員","kind":"質問","question":"ちょっと心配だったのでお聞きしました。一律に切るというのではなくて就労支援を力を入れているということなので、ぜひその方向で行ってほしいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-019"}]},{"id":"topic-03","title":"の平成２１年度指定管理者による管理に対するモニタリング・評価の結果","agenda":"の平成２１年度指定管理者による管理に対するモニタリング・評価の結果","exchanges":[{"speaker":"井上委員","kind":"質問・要望","question":"どういうふうに評価をされているのか、ちょっとそこの辺の状況をお知らせいただきたいのと、その部分を説明を求めました。","respondent":"安井子育て支援課長","answer":"やはり継続的にどういうことが行われるかというところと、一方では、こちらについては子育て支援センターの事業の充実を図っていきたいということで。そういうところへ違った見方でアンケート等も含めて評価していただくのが一番公正なのではないかということで…","id":"exchange-020"},{"speaker":"井上委員","kind":"質問","question":"延べ件数が２４８件ということは、どういう体制でいらっしゃるのか、ここのところの体制をちょっと説明を求めました。","respondent":"安井子育て支援課長","answer":"それからお母さんに対応する方と、それから、家の中の状況をよく見せていただくということも必要になるのかなと考えています。別にハウスキーパーではありませんので、お掃除に行くのが仕事ではないんですけれども、大体１回行くと３時間ぐらいかかってしまいます。","id":"exchange-021"},{"speaker":"井上委員","kind":"質問","question":"２ページ目で、評価事項のところで2)なんですけれども、これは何ですか。ちょっと説明していただけますか。","respondent":"吉岡保育課長","answer":"６月２６日ですけれども、中小企業センターで、「子どもの夜更かしは大丈夫？そのような保育、教育の研究活動をしています。","id":"exchange-022"},{"speaker":"井上委員","kind":"質問","question":"上級保育学校というそのものがどういうものなんですかと。そこでやっている研究なのか、どういう組織をつくったのか、よくわからないんです。","respondent":"吉岡保育課長","answer":"済みません、補足します。幼稚園教諭等が、今言ったようなテーマに基づきましていろいろ研究をしたり、シンポジウムを開催するなどというような活動をしているものです。","id":"exchange-023"},{"speaker":"井上委員","kind":"質問","question":"ということは、ぷりすくーるも独自で研修の場をつくられているということでよろしいんか尋ねました。","respondent":"吉岡保育課長","answer":"さようです。","id":"exchange-024"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ホームページを開いたんですが、申しわけない、古いんですよね。必要なときに使えているのかどうかとか、内容的なことを教えていただきたいのと、職員体制も説明を求めました。","respondent":"安井子育て支援課長","answer":"子育て支援センターについては、子育て支援センター、そういったものにも２４時間で対応しております。常に区役所で定年まで雇っていることはなかなか難しい方であるという方が２人ほど入っておりまして、そういった方がやはり入っております。","id":"exchange-025"},{"speaker":"飯沼委員","kind":"質問・要望","question":"そこを教えていただきたいのと、平成２１年度から運営費の増額をすると書いてあるんですが、この辺のことを具体的に教えていただきたいのが１つです。要望や不満を事業所に言いやすいかどうかというところで、「いいえ」が８％とか、この辺の改善点とかをどうとらえていらっしゃるのか説明を求めまし…","respondent":"安井子育て支援課長、吉岡保育課長","answer":"改善が必要とされた原因の分析及び対応方針というところとも関連しているんですけれども、今日、そこら辺が２４時間体制でシフトを組んでいるので。特養等の施設… 要望やトラブルへの対応についての満足度というのは５割弱程度でございまして、前回、やはり５割をちょっと超える程度でございましたので。その辺の検討等も重ねている中ですけれども、その辺…","id":"exchange-026"},{"speaker":"飯沼委員","kind":"質問","question":"平成２１年度からということは、その辺がわかったら、その辺がどのように増えたのか違いを説明を求めました。","respondent":"吉岡保育課長","answer":"子ども１人当たり、それプラス品川区としての保育に対する考え方の上乗せ分という構成にしまして、この経費の算定をするように考え方を変えたです。延長加算、そういう研究研修の取り組みもしておりますので…","id":"exchange-027"},{"speaker":"西本委員","kind":"質問・要望","question":"先ほどから苦情処理の問題が出ていると思うんですけれども、では、親の満足は１００％かなえるべきものなのでしょうか。それはどういうふうにとらえているのでしょうかということをお聞きしたい。","respondent":"吉岡保育課長、安井子育て支援課長","answer":"理由の説明なり、やはりちょっと５０％というのは、そういう対応の仕方等も含めた問題で若干改善するところはあるかなというように思っています。それも平成２１年度が始まったばかりでまだ１年しか終わってございませんので… 基本的にショートステイについても６泊までということで、そういうご意見もあるんですけれども、それは基本的にはできません。私どもの子育て支援センター自体が虐待防止ということで…","id":"exchange-028"},{"speaker":"西本委員","kind":"質問・要望","question":"恒常的に使っている方はいらっしゃらないんですかというのをお答えいただきたいんですが、保育園が１０時まで預けているよという現実があります。じゃあ、５年先に下げてもいいんじゃないのというような議論になると本末転倒かなというふうに思っているので、その考え方を説明を求めました。","respondent":"安井子育て支援課長、吉岡保育課長","answer":"３日ぐらい前までに申し込みいただくという形になっていまして、そういったときにやむを得ず利用するという方がいる形になっています。どうしても連れていけないという、問題のあるものについては… 先ほど申し上げましたように、指定管理をお願いして、よりよい保育を目指してやっていただきたいという気持ちは私どもも同じです。経営、運営ですので…","id":"exchange-029"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/746735?Template=document&Id=4706#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2010-01-01&TermEnd=2010-12-31"}],"sourceMeta":{"pages":0,"characters":39740,"voices":86}},{"id":"h22-20100721-14","meetingId":"h22-cm07","date":"2010年7月21日","dateIso":"2010-07-21","committee":"行財政改革特別委員会","time":"午後１時０２分～午後３時０１分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を35件整理しています。","topics":[{"id":"topic-01","title":"の事務事業評価に関すること","agenda":"の事務事業評価に関すること","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"この前の５年間やった目的の中に、そういった目的があったのかどうかお伺いします。５年間続けた事務事業評価を、その理由とそれをまた今回改めて復活させるといいますか、その目的をお伺いします。","respondent":"久保田行財政改革担当課長","answer":"区民ニーズにきめ細かく対応した業務の遂行、事務事業評価という手法を使いまして、行財政改革をとり進めてきたところです。さらなる新たな事務事業評価の仕組みを検討するといったところで、少子高齢化の進展等、そうした区政運営を進めていきたいと考えているところです。","id":"exchange-001"},{"speaker":"安藤委員","kind":"質問","question":"前回の５年間の事務事業評価で、以前の５年間、事務事業評価の削減コストは大体どれぐらいになると概算しているのか伺います。","respondent":"久保田行財政改革担当課長","answer":"０.２とか、そういったものが減になってまいりますので、職員の削減が図られているといったところです。事務事業評価全体でいきますと、それら総体的にプラスマイナスといったところもありますので、一定のコスト削減が図られたということはたしかです。","id":"exchange-002"},{"speaker":"安藤委員","kind":"質問","question":"評価が実際事業の見直しとどうつながっていくのかというんですか、工程表というんですか、お伺いしたいのと。そういう意味で、あと区民の皆さんの意見とか、声はどういうふうに反映させていく仕組みがあるのかをお伺いします。","respondent":"久保田行財政改革担当課長","answer":"工程表につきましては、事務事業評価につきましては、来年度の予算編成や実施計画等のローリング等に反映させていきたいというところがありますので。外部の方の意見を取り入れるという仕組みは今の段階では取り入れてございませんけれども…","id":"exchange-003"},{"speaker":"安藤委員","kind":"質問","question":"今回やる事務事業評価の公開の方法というんですか、どういうふうに公開、どのタイミングでどういう形で行うのかというのを重ねてお伺いしたいのと。先ほどの質問の中で、住民福祉の増進というところが自治体の役割なわけですから、そこら辺はどういうふうに担保していくのか。","respondent":"久保田行財政改革担当課長","answer":"公開の時期ですけれども、６月最初の調査事項概要のときにもご説明いたしましたが、区民にも公表していきたいと考えているところです。例えば、世論調査等も定期的に行っておりますので、そうした中で区民のニーズというものを十分把握していきたいと考えているところです。","id":"exchange-004"},{"speaker":"安藤委員","kind":"質問","question":"どういう形で考えているのか、サービスを低下させないというところが両立しているのかどうかというのは、評価が分かれるところだと思うんです。もうちょっと課題があると思っているのか、そこら辺はどのように評価しているのか、それだけお伺いします。","respondent":"久保田行財政改革担当課長","answer":"こうした事務事業評価を行ったということにつきましては、ホームページ等を通じて、区民に広く周知を図っていきたいと考えているところです。民間委託を進めてきたところでございまして、活用しながら、それぞれの事業を進めているところです。","id":"exchange-005"},{"speaker":"安藤委員","kind":"質問","question":"図書館の問題もありますし、給食の問題もあります。そういった評価というんですか、区としてはどういうふうに評価をしているのかというところを聞いたので、ちょっとそこら辺をお伺いしたいと思います。","respondent":"久保田行財政改革担当課長","answer":"民間委託を進めている事業につきましては、それぞれの事業の中において、委託をすることによって効果が上がってきたと考えているところです。こちらの取り組みについても、我々ではできない民間のノウハウというか…","id":"exchange-006"},{"speaker":"稲川委員","kind":"質問・要望","question":"１点お伺いしたいんですが、イコール委託という手法というんですか、それしか考えられていないんですか。それはやるべきかどうかというのを議論したときに、ＰＰＰというんですか、その種類を教えてもらいたいんです。","respondent":"久保田行財政改革担当課長","answer":"民間委託を例にご説明してきたところですけれども、民間との役割分担というと、いろいろな形があろうかと考えています。役割分担を明確にした上で、そうした手法を取り入れながら、効率的に事業を進めていきたいと考えているところです。","id":"exchange-007"},{"speaker":"稲川委員","kind":"質問","question":"いいところもあれば、悪いところもあるという部分で、そういう研究もちゃんと進めているのかどうなのかというのを教えてください。もう委託ではなくて、どんどん違う手法に転換していっているような感じがするんですけれども、その辺をお答えください。","respondent":"久保田行財政改革担当課長","answer":"民間事業者がやっているところで、事業としては十分、区の役割ではないだろうといったものもあるかと将来的には想定しています。私どもとしましても、最終的には行政ではなくて、民間がその事業をやっていくといったこともあると考えております。","id":"exchange-008"},{"speaker":"渡部委員","kind":"質問","question":"前回、平成１３年から事務事業評価をされていて、今度は平成２２年度ということで約９年たって、確かに世の中が大分変わってきていると思います。私は人の補充というんでしょうか、逆に公務員が増える可能性というのもあるのではないかと思うんですが、その辺はどのようにお考えか尋ねました。","respondent":"久保田行財政改革担当課長","answer":"拡充ということで、人の補充も必要かです。公務員を増やさなければならないという考えは持ってございませんで、その両端の中で、両方の視点を持ちながら進めていきたいと考えております。","id":"exchange-009"},{"speaker":"渡部委員","kind":"質問","question":"例えば、ＬＥＤランプのようなものだって、そのように言われ始めています。今回は評価をするわけですから、平成２１年度までの中でどうだったというものでしょうけれども、ちょっと教えていただけますか。","respondent":"久保田行財政改革担当課長","answer":"導入について検討しているといったところでは、非常に長期的な視点も持ちながら、それぞれの事業に取り組んでいるです。平成２１年度につくりました中長期改修計画等もありますが、事務事業評価についても行っていかなければならないと認識しております。","id":"exchange-010"},{"speaker":"井上委員","kind":"質問・要望","question":"そういう部分をぜひ明らかにしてほしいと思うんですけれども、その辺をもう少し積極的に対応できないかということでお考えを伺いたいと思います。しっかりとやってほしいというところで、区民ニーズの把握というところをもう少し踏み込んでお答えほしいと求めました。","respondent":"久保田行財政改革担当課長","answer":"今回区長の施政方針でもございましたように、効率性といったように、事業の見直しを積極的に行っていきたいと考えているところです。先ほど日ごろの職務を通じてということでご説明いたしましたが、こうしたものも踏まえながら、区民ニーズについて十分把握しています。","id":"exchange-011"},{"speaker":"井上委員","kind":"質問・要望","question":"今やっているのがどうかという範囲ではわかりますけれども、そこのところは検討していただく必要があるかなということで、要望します。反映する方法の検討だと私は理解したいんですが、それでよろしいのかどうかという確認をまず先にさせてほしいと求めました。","respondent":"久保田行財政改革担当課長","answer":"平成２２年度から再開したところですけれども、こちらについては、これまでご説明してきたところです。ステップとしての事務事業評価をどうしていくかといったところでの課題だと認識しておりますので、こうした意見を取り入れて、できるだけ公平性。","id":"exchange-012"},{"speaker":"井上委員","kind":"質問","question":"区が積極的に実施すべき事業であるということは、そこはどういう基準で、区民にとって区が積極的に実施すべき事業であると判断しているのか。これを見る限り全然差がないのではないかと思うんですけれども、どういうふうな基準をここで考えているのかということ、まずそこをお願いします。","respondent":"久保田行財政改革担当課長","answer":"区が実施主体となる必要がないものについてはＤという評価になるということで、ＣとＤというのを分けているところです。実施手法が、もしかしたら、必要な部分の余地が残っているという事業手法である場合にはＢという評価をつけていくと考えているところです。","id":"exchange-013"},{"speaker":"井上委員","kind":"質問・要望","question":"Ｂ、Ｃ、Ｄという評価でイメージされるものというのは少し検討いただきたいと思うものがあります。検討の余地があるのかどうかわかりませんが、そういう意見に対して何かお考えがあれば、お聞かせほしいと求めました。","respondent":"久保田行財政改革担当課長","answer":"この中でそういったものの補足的な説明を加えていって、説明書き、何でＡなんだ。横断的に評価もしていくといったところも非常に大切ではないかと考えていますので、事務事業評価を実施していきたいと考えているところです。","id":"exchange-014"},{"speaker":"石田委員","kind":"質問・要望","question":"ここが合計で１６６事業あるんですが、平成１３年度から平成１７年度で廃止・中止、または完了する事業と見直しを含めると３２０事業あるんです。そのうちの約半分の１６６事業が載っているというのはどういった理由があるのか、まず、その２点を説明を求めました。","respondent":"久保田行財政改革担当課長","answer":"現在、一次評価を事業部長がやっているところでございまして、これは６月２日の本委員会におきましてご説明してきたところです。６ページの各年度の評価実施状況のＣとＤの部分が、８ページにおきましては、数字を書かせていただいているものです。","id":"exchange-015"},{"speaker":"石田委員","kind":"質問","question":"半分ということは、残りの１６０事業近いものというのは重なっている部分として考えていいんでしょうか。単純計算したら、３２０事業から重複している部分というのはわかるんですけれども、その辺の数の整合性についてもう一度改めて説明を求めました。","respondent":"久保田行財政改革担当課長","answer":"予算の編成に取り組んでいきたいと考えているところでございまして、一定の時期、予算とセットという形で公表をしていきたいと考えているところです。精査をしてまいりますと、１６６事業という形で、８ページには書かせていただいているといったところです。","id":"exchange-016"},{"speaker":"石田委員","kind":"質問・要望","question":"９ですから、５年間の事務事業評価、多分そう思ってしまうと思うんです。平成１８年度に６２事業の見直しを継続して、その後どうなっていったのかというのを、教えてほしいと求めました。","respondent":"久保田行財政改革担当課長","answer":"重複している部分を除くと１６６事業ですが、手元にこれまで５年分の評価、ご報告等をさせていただきたいと思います。平成１８年度、平成１９年度の中でそれぞれ事務事業評価の結果に基づいて、現時点では見直しは済んでいると考えているところです。","id":"exchange-017"},{"speaker":"須藤委員","kind":"質問","question":"煩雑過ぎる仕組みというのがどういうふうに変えられたのか、今いろいろ質問があった、今までのは何だったという話になってしまうと思う。その点について説明を求めました。","respondent":"久保田行財政改革担当課長","answer":"数量化についても各所管課があまり悩まなくても事務作業ができるような形がとれればというところで、こうした形をとらせていただいたところです。そうした部分につきましても今後改善をしていきたいと考えています。","id":"exchange-018"},{"speaker":"須藤委員","kind":"質問","question":"このこと自体が１つの仕事になってきて、どうしてもそういう人に集中していってしまうのではないかという思いがあるので、そのあたりはいかがか尋ねました。","respondent":"久保田行財政改革担当課長","answer":"やはり職員に問題意識を持たせるということであれば、多くの職員がこうした事務事業評価の作業の中でかかわるといったことも必要だと思います。たたき台となるものは書いていると考えていますので…","id":"exchange-019"},{"speaker":"菊地委員","kind":"意見","question":"行政改革の１つの手法なんだと思いますけれども、説明責任の問題だとか、評価を進めていく上ではまず透明性が一番重要な部分ではないかと思うんです。この３つの必要性とか、ここにはっきりと入れるべきなのではないかと私は思うんですけれども…","respondent":"久保田行財政改革担当課長","answer":"私ども、透明性というものも大変重要だと考えております。私どももきちんと公表していくといったところですので、そういった中で透明性、公平性というものも担保していきたいと考えています。","id":"exchange-020"},{"speaker":"菊地委員","kind":"質問","question":"最初、初年度やったときから９年目になるわけですよね。この行政評価の中に、今後の課題だと言っているんですけれども、取り入れられなかった理由というのは何なんか尋ねました。","respondent":"久保田行財政改革担当課長","answer":"新たな仕組みでとり行いたいですので、第１段階の時点で外部の方の意見を取り入れるということが仕組みとしてなかなか難しいのではないか。その意味では区が主体となって事業を実施している点では、今回は外部評価を取り入れなかったです。","id":"exchange-021"},{"speaker":"菊地委員","kind":"意見","question":"やっぱりどうやって説明責任を果たしていくのか、情報公開をしてきたのかどうかということも、１つの評価の基準なんだと思うんです。もう一度そこを、ご意見をいただけますかとの意見を述べました。","respondent":"久保田行財政改革担当課長","answer":"私どもでも５年間実施してきたという成果と課題はありますが、まずは第１段階として、区の内部評価という取り組みをさせていただいたです。外部評価等につきましては、次の段階での課題であると認識しておりますので、まずは区が主体として内部評価をさせていただいたです。","id":"exchange-022"},{"speaker":"鈴木委員","kind":"質問","question":"ですから、ここの部長の評価というのは、どういうふうに出てくるのかなというのが、そこら辺を見てみたいという気もするんです、自分とすると。その辺、部長職としてどのようにとらえていくのかなという考え方をちょっと教えてもらえばと思います。","respondent":"日下部企画部長","answer":"先ほどの５年間の評価結果を見ても、廃止すべきものに対して、継続すべき事業というのが結構ウエイトが高いということがあります。継続とはいっても、きちんと自覚をして、記述についても十分な工夫をしていく必要があるのではないかと考えます。","id":"exchange-023"},{"speaker":"鈴木委員","kind":"質問・要望","question":"今までの話の中で、それだけしっかりチェックしているなというのは感じていますので、ぜひその辺もこれから気をつけていただきたいなと思います。係長、その辺も下の担当の係の方にもわかるようなメッセージをしっかり出していただきたいなと思って、その辺をお願いいたします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-024"},{"speaker":"井上委員","kind":"質問・要望","question":"内部資料ということで書くのではなくて、最初からそういうことを前提にという職員の意識も変えていただきながら公表すると。その辺は前向きにというか、絶対にというか、公表していくという方向できちんとまとめてほしいということをぜひ要望したいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-025"}]},{"id":"topic-02","title":"の公有地活用に関すること","agenda":"の公有地活用に関すること","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"少々手狭でも、技術も発展しているわけですから、利用していくのが必要かなということを感じました。くどいようなんですけれども、そういったところではどういうふうに仕組みを担保されるお考えがあるのか、それをお伺いします。","respondent":"久保田行財政改革担当課長","answer":"庁内検討会の中で跡地、中長期的な視点も含めまして、これから検討していきたいと考えています。議会にもそれぞれご報告させていただいているところですので、そうした中で区民の方から寄せられる意見等も検討していきたいと考えているところです。","id":"exchange-026"},{"speaker":"安藤委員","kind":"質問・要望","question":"あまり長くやれないんですけれども、具体的にどういう仕組みで庁内で検討されていくのかというのを、スケジュールをもって教えていただきたいんです。どういう案を出していくのか、どういうメンバーでというところをもう少し、ぜひ明確にわかりやすいように教えていただけるとありがたいです。","respondent":"久保田行財政改革担当課長","answer":"庁内検討会の詳細につきましては、全庁にわたる部分ですので、事業部長を中心としたメンバー構成にしていきたいと考えているところです。跡地についてそれぞれ現在どうなっているかといった状況等もご説明していきながら、また…","id":"exchange-027"},{"speaker":"安藤委員","kind":"質問","question":"この１から７全部なんでしょうか。それを具体的にお伺いしたいと思います。","respondent":"久保田行財政改革担当課長","answer":"今まで跡地等を活用する中で検討してきた延長線上ということで、跡地というものについての検討をいただければと考えているところです。ですから、これまで検討してきたものの延長線上にある検討会というような意味合いでご説明させていただいたところです。","id":"exchange-028"},{"speaker":"安藤委員","kind":"確認","question":"庁内検討会で検討するものは、この１から７全部なんですか。それを確認したいんです。","respondent":"久保田行財政改革担当課長","answer":"今お手元にお配りしています資料の中にありますように、７つの跡地がありますので、こちらを中心に検討をしていきたいと考えています。その中で、こちらの行財政改革特別委員会にご報告させていただきまして、議会からご意見をいただければと考えているところです。","id":"exchange-029"},{"speaker":"安藤委員","kind":"質問","question":"それぞれについて原案ができ上がり次第、随時、行財政改革特別委員会にその案が出されるということでよろしいんでしょうか。以前の平塚小学校のような感じなんか尋ねました。","respondent":"久保田行財政改革担当課長","answer":"イメージとしては平塚小学校のときに利用計画案を立てたものの形で議会にご報告をしていくという形です。検討の形ですけれども、今回この７つについて、こうした会を設置できればと考えているところです。","id":"exchange-030"},{"speaker":"井上委員","kind":"質問・要望","question":"その辺のところを説明いただきたいということと、もう１つ、説明を求めました。","respondent":"久保田行財政改革担当課長","answer":"活用計画が決まった時点で、建物についての処分をどうするかといったところが決まるものと考えています。１つの時期にということではなくて、素案というか、原案ができた時点で個別の施設についてそれぞれご報告をしていきたいと考えているところです。","id":"exchange-031"},{"speaker":"井上委員","kind":"質問","question":"１番目のところ、区がその土地を貸してあげて、リース会社が建てたという認識なんでしょうか。どういう所有でというところからわからないんだと思うので、今後区はここをどういうふうに使うことができるのか、説明を求めました。","respondent":"久保田行財政改革担当課長","answer":"大崎在宅サービスセンターは平成２５年の春には大崎の再開発のビルの中に戻ります。それ以外のもともとあった建物については、その跡地活用の内容によってどうするかというのを含めて、検討していきたいと考えているところです。","id":"exchange-032"},{"speaker":"井上委員","kind":"質問","question":"本当にその場所が適正であるかどうかという、ある既得権益ではなくて、そういう見直しも建物の中では必要になるケースもあるかと思うんです。はなくて、そういう検討というのはいろいろな時期にされるべきだと思うんですが、そういうことはされないんか尋ねました。","respondent":"久保田行財政改革担当課長","answer":"１つ閉鎖をするといった考え方もあったんですけれども、閉鎖をしますと、どちらかで仮営業をしなければならないということを基本方針に考えたときに。地域の状況等も踏まえながら、適正な配置ができるように、適正な活用ができるように検討していきたいと考えているところです。","id":"exchange-033"},{"speaker":"井上委員","kind":"質問・要望","question":"ここは区の耐震工事をしている部分の場所をもう少し有効活用すべきではないかと、トータルで場所の検討もあわせてぜひしてほしいと求めました。これは要望でいいです。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-034"},{"speaker":"石田委員","kind":"確認","question":"当初予定されている平成２５年より前にリース期間が終わるような表記がされていたんですが、その辺の確認をしたいと思います。","respondent":"久保田行財政改革担当課長","answer":"あれは平成２５年１月か、平成２４年１２月ぐらいの表記だったと思うんですけれども、確かに平成２４年度いっぱいまではリース期間としてはもっていると聞いております。","id":"exchange-035"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/438675?Template=document&Id=5888#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2010-01-01&TermEnd=2010-12-31"}],"sourceMeta":{"pages":0,"characters":39035,"voices":78}},{"id":"h22-20100722-15","meetingId":"h22-cm07","date":"2010年7月22日","dateIso":"2010-07-22","committee":"環境対策特別委員会","time":"午後１時０２分～午後２時４０分","status":"正式会議録","sourceType":"formal","overview":"環境対策特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件整理しています。","topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/270609?Template=document&Id=6192#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=15&TermStart=2010-01-01&TermEnd=2010-12-31"}],"sourceMeta":{"pages":0,"characters":2722,"voices":11}},{"id":"h22-20100726-5","meetingId":"h22-cm07","date":"2010年7月26日","dateIso":"2010-07-26","committee":"総務委員会","time":"午後１時０１分～午後５時１８分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を47件整理しています。","topics":[{"id":"topic-01","title":"最初に、報告事項を聴取します。 それでは、(1)区民活動情報サイトの開設","agenda":"最初に、報告事項を聴取します。 それでは、(1)区民活動情報サイトの開設","exchanges":[{"speaker":"堺委員","kind":"提案","question":"何点か確認で教えていただきたいんですけれども、たしか平成２１年２月の第１回定例会のときに、この導入を提案した経緯があるんです。特に力を入れた箇所というんですか、特徴点というか、そういった点について教えていただけますかとの意見を述べました。","respondent":"中川原広報広聴課長","answer":"今回は、活動を始める人と活動をしている方々が、現在の情報を共有するというところに重点を置かせていただいているところです。まずは、皆さんの活動の紹介をして、いろいろな方に参加をしていただくきっかけの情報の提供というところを重視した形のサイトになっています。","id":"exchange-001"},{"speaker":"堺委員","kind":"質問","question":"ＲＦＰというんですか、そういう選択等もあるようですけれども、そういう形の業者選定をなさったのかどうか。これから検討するのか、もう既に決まっているのか、その辺はどうなんか尋ねました。","respondent":"中川原広報広聴課長","answer":"４月末に簡易プロポーザルを行いまして、また選定会議を行いまして、業者が決定しております。区民との協働という形で、直接区がやるのではなくて、区民の方のＮＰＯ法人にソフトの運営方面に入っていただくということで考えているものです。","id":"exchange-002"},{"speaker":"堺委員","kind":"質問","question":"７月１７日の参加希望者のサイトの説明会の件なんですけれども、１２０名ということだったようですけれども、どうか。あれば、どこまでなのか、その辺のところはどうなんか尋ねました。","respondent":"中川原広報広聴課長","answer":"今年度の契約の内容では、登録する団体は１,０００団体まで可能です。それは、今のところ、３００団体ぐらいまでという形でご用意はしているところです。","id":"exchange-003"},{"speaker":"堺委員","kind":"質問・要望","question":"最後にちょっと確認しておきたいのは、例えば改善要望とか、そういったものが出てくるかもしれないという気もするんです。仮にそういう要望等があれば、その辺のお考えは、どうなんか尋ねました。","respondent":"中川原広報広聴課長","answer":"７月１７日の説明会で集まっていただいた１２０名の方たちとお話をしますと、ちょっとパソコンは、という方まで幅が広いんです。こういうものもあるといいねというふうにやっていくのが、皆さんのサイトとして使っていただくには、大事なことかと感じているところです。","id":"exchange-004"},{"speaker":"堺委員","kind":"意見","question":"かなりレベルの高い人たちがこういうところに参加してきているのかと思いましたので、それを前提にして、ちょっとお尋ねしたんです。協働という視点から取り上げていくと、その辺のところをしっかりとらえていただいて、成功していくように進めていってほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-005"},{"speaker":"土井委員","kind":"質問・要望","question":"すから、この形が一番適切なのかどうかも含めたものについて、その辺のことをちょっとお聞かせいただきたい。さまざまな課題の問題が起こっているのが現実ですから、どこが管理をして、どこがどうするのか。","respondent":"中川原広報広聴課長","answer":"説明会を開く前の７月初旬に、所管を通じて説明をしてもらったりしまして、個別に説明もできる限りした中で登録を受け付けて。説明会での質問がたくさん出ましたし、もう１回操作説明会といいますか、もう１回説明をしながら。","id":"exchange-006"},{"speaker":"土井委員","kind":"質問","question":"当然のことながら考えていかなければいけないわけですから、いろいろな意味での情報の共有等をされるわけですから、それは。お役所はだめでしたなんていう話とかは往々にして起こる話ですから、どういう発想を持ってやっていくのかということを話してください。","respondent":"中川原広報広聴課長","answer":"このサイトに関する区の関与ですが、要綱で定めすることになると思うんですが、システム管理運営委員会というのを、やはり庁内に設けまして、適正な運営を担保していくということを、区として行っていく予定です。","id":"exchange-007"},{"speaker":"土井委員","kind":"意見","question":"まさしく、下手すると官権で押さえつける話になりかねないという、もっと協働で、民間の皆さんが幅広く柔かい頭でやっていただこうというのと、そことをどう調整するという話なので、あまり固い話をされると、ちょっとまた何か言いたくなってしまうとの意見を述べました。","respondent":"中川原広報広聴課長","answer":"やはり責任問題も発生しますので、ある程度信用できるサイトとして運営するための枠組みは、区のほうで責任を持ってやらせていただく予定でおります。どこまでどうというのは見えませんので、やりながら、できるだけ区民の方主体のサイトに育っていけばいいなと考えています。","id":"exchange-008"},{"speaker":"土井委員","kind":"質問","question":"そこら辺を非常に気にしているものですから、お話を伺っているんです。これまた大いにあるわけで、その辺がちょっと、今のお話だけではわからないんです。","respondent":"日下部企画部長","answer":"柔軟性を高めていくとか、それはまたいろいろな方法も考えられると思いますので、まずは９月１日にスタートを切る。区側としても柔軟な対処をしていく、そういう方向で進めていくのが一番適切ではないかと考えているところです。","id":"exchange-009"},{"speaker":"土井委員","kind":"質問・要望","question":"文句がついたら、いつの間にか消えてしまったとかいう流れが、ときどきあるわけです。もう公表ですから、公開しているわけですから、終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-010"},{"speaker":"宮崎委員","kind":"意見","question":"これはどういうふうにつくっているのかということと、具体的にどこというのが決まっているのかどうか、お尋ねしたい。１２０名が参加したという話なんですけれども、どういう団体なのかということ、どういう団体を想定しているのかというところを聞きたいと思いますとの意見を述べました。","respondent":"中川原広報広聴課長","answer":"委託事業ではないので、こういうことだったらできるというあたりをお話ししながらやっていかないと難しいかなというところはあります。こういった活動を、地域でやっていらっしゃる方で、営利を目的としていない団体というところを想定しています。","id":"exchange-011"},{"speaker":"宮崎委員","kind":"質問","question":"立ち上げで大体３９０万円で、先ほどの委員の質問にもあったと思うんですけれども、そんなところで聞いているんです。年間１６０万円のランニングコストといいますけれども、それとの費用の関係、どういうふうにお考えなのか伺いたいと思います。","respondent":"中川原広報広聴課長","answer":"今まで活動をしている方は、結構高齢の方も多くて、何団体を想定するかというのはなかなか難しいです。８月にもう１回説明会をやって、１,０００枠は設けさせていただいて、今年度は積極的にお声をかけさせていただきたいと考えています。","id":"exchange-012"},{"speaker":"須貝委員","kind":"質問","question":"これから急速にネット社会がますます発展していくわけですから、そういう意味では、一歩踏み出したということは価値があるのではないかと思います。システムの管理運営を区で構築しているわけですから、そこに対して、ちゃんとお持ちになっているのか尋ねました。","respondent":"中川原広報広聴課長","answer":"ＣＭＳという仕組みを使っていまして、わりと簡単に入力できるということは、そんなに難しいことは入らないということです。支援という立場からすると、募集したくてもできなかった人たちというところを、まずは応援するのかなという感触を持っているところです。","id":"exchange-013"},{"speaker":"須貝委員","kind":"質問","question":"そのときに、やっぱりだれかが必ず監視できるような状況は、ちゃんとあるのかどうか。それだけ、ちょっと心配しているんですが、何かお考えか尋ねました。","respondent":"中川原広報広聴課長","answer":"今後、ＮＰＯ法人と具体的な話をする中で、どこまでできるかということは考えていく形になると思います。ほんとうに大事なことだと思います。","id":"exchange-014"},{"speaker":"林委員","kind":"質問","question":"個の団体がつくるホームページと基本的に違うところだと思うんですけれども、さっき言っていた、だめなものは何があるんですか。極端に一つ言うと、品川区という自治体に対するチェックというのも入れておいてあげればいいのではないか尋ねました。","respondent":"中川原広報広聴課長","answer":"登録の段階で、今から申し上げます、だめというのは、チェックをする予定になっています。その構成員でなくなった日から５年を経過しない者の統制下にある活動、その他、サイト管理者が適当でないと認めた活動といった形になってあります。","id":"exchange-015"},{"speaker":"林委員","kind":"意見","question":"例えば社会貢献活動を行っている団体ならいいというのは、その活動のみについては認めるという細かいことが言われるのか、スタートするときまでに。どういうのが営利団体なのか、このサイトを運営しているのも、営利団体でしょうとの意見を述べました。","respondent":"中川原広報広聴課長","answer":"その貢献活動に限って、このサイトを使って発信していただくという、そういったことなんです。例えば区内で清掃活動をやるとか、そういった品川区のために企業が貢献している活動があれば、ここでご紹介することができるということなんです。","id":"exchange-016"},{"speaker":"林委員","kind":"意見","question":"助成金は出るけれども、７０歳以上の人を新規に雇用したら、雇用促進のためとなる。私は思いますので、それだけを念を押して、改めてお願いをしておきますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-017"}]},{"id":"topic-02","title":"の「広報しながわ」全戸配布の実証実験","agenda":"の「広報しながわ」全戸配布の実証実験","exchanges":[{"speaker":"土井委員","kind":"質問・要望","question":"どうなったかということを、どう確認をするのかということにもつながらないと、そこら辺をどのようにお考えになっているのかということ。その方法等によっては、具体的なものはなかなかわからないという形になりかねませんので、そこをちょっと聞かせてほしいと求めました。","respondent":"中川原広報広聴課長","answer":"２日目でどのぐらい配れたか、そういった配布に関する種々の事項をそれぞれ報告書として出していただくという形の委託仕様になっております。できるだけ多くの方に配布する方法としまして、どのようなことができるのかということの検討を…","id":"exchange-018"},{"speaker":"土井委員","kind":"質問","question":"いつ幾日までに、どのように配ったかというような検証を含めたものも、業者に出してもらうことになりますよね。今の４８７万７,０００円という費用のうち、検証にかかる費用というような意味も含めて出ているんだと思うんですけれども、内訳を説明を求めました。","respondent":"中川原広報広聴課長","answer":"印刷費が２６２万円です。配布業者にお願いした費用が、２０７万６,０００円で、その中に、そういった検討も含んでいるものです。","id":"exchange-019"},{"speaker":"土井委員","kind":"意見","question":"当然、今後、これがいいとなれば、年に何回とか、ある種のものは、そうすることになるんですよね。そうすると、検証費用はちゃんとやっておかないと、我々は、幾らぐらいかかるのかという検討ができないんですよとの意見を述べました。","respondent":"中川原広報広聴課長","answer":"うちのほうで、４０回という話を出したときに、どういうことが組めるかというやりとりになってこようかと思います。今回は、全戸配布にくるんで、こういった報告もしてくださいという、全戸配布の仕様の中で、報告をお願いしているものです。","id":"exchange-020"},{"speaker":"土井委員","kind":"質問","question":"全戸配布を３日でやってくださいということなのは、何人でやって、どうするという見積もりをしなければいけないわけですよね。今のお話を伺っていると、４０回だとできないかもしれないなんていう話になると、ということにもなりますよね。","respondent":"中川原広報広聴課長","answer":"何らか検討して、将来的に何かできることがないかということを整理して考えていく、やらせていただいております。業者にとってみると、ちゃんと管理者として押さえて、ほんとうにやっているかどうかということをやらなければいけない内容かなと考えています。","id":"exchange-021"},{"speaker":"土井委員","kind":"意見","question":"そうすると、この業者は、新聞販売店だそうですけれども、この業者でいけば、２０７万円何がしというお金がかかりますと、それが回数が増えても、これから頼んでも、同じような近い値段で、回数が増えれば割引きをしてくれるのかどうかわかりませんけれども…","respondent":"中川原広報広聴課長","answer":"これがそのまま言えるかどうかわかりませんが、新聞折込みですと、単価は６円２５銭なんですが、今回、全戸配布という形での単価は１０円３８銭になっております。","id":"exchange-022"},{"speaker":"堺委員","kind":"質問・要望","question":"平成１９年第４回定例会、平成２０年の決算特別委員会の総括質疑で、全戸配布について要望した経緯があるんです。いわゆる新聞協会というのですか、いろいろ対象に入っていたのかどうかわかりませんが、ちょっと参考までに教えていただけますか。","respondent":"中川原広報広聴課長","answer":"説明会には８社ほどお見えになりました。シルバー人材センターは、今回は辞退をされています。","id":"exchange-023"},{"speaker":"堺委員","kind":"質問","question":"その辺の継続実施をするための合格点というのでしょうか、判断基準というのでしょうか、今回は特に設けていないのでしょうか。その辺のお考えがあれば、ちょっと説明を求めました。","respondent":"中川原広報広聴課長","answer":"今までいろいろやってきた経験上のものを突き合わせて検討しないと、今回１回限りのことで、ただ投げ込んだだけではだめなんですね。いろいろな場合を想定して、今の段階で何がベターかということを、少し検討させていただきたいというのが今の状態です。","id":"exchange-024"},{"speaker":"堺委員","kind":"確認","question":"今回は４８７万７,０００円、ポスティング経費としては２０７万６,０００円とおっしゃっていましたが、どのぐらいの経費になるんですか。今回はポスティングだから２０７万６,０００円になってしまうんですが、この経費はどのぐらいなんか尋ねました。","respondent":"中川原広報広聴課長","answer":"広報紙を読んでいらっしゃる方が、在勤の方もいらっしゃいますので、今回の８月１日の臨時号につきましては、スタンド配送は行う予定です。今年度の予算でいきますと、定例号ですと８６万３,０００円で、全戸配布ですと２０７万６,０００円という形になります。","id":"exchange-025"},{"speaker":"堺委員","kind":"質問","question":"従来ですと８６万円で、ポスティングすると２０７万６,０００円だと。そうすると、これは約１２０万円の開きがあるという理解でいいんか尋ねました。","respondent":"中川原広報広聴課長","answer":"全戸配布ですと、部数も多くなりますので、単価も上がりますので、そういうことになります。","id":"exchange-026"},{"speaker":"宮崎委員","kind":"質問","question":"今回、全戸配布で２０万世帯の何％ぐらい、何世帯ぐらいに届くのか、そこのところをどういうふうに見ているのか伺いたいと思います。そこら辺はどうなんか尋ねました。","respondent":"中川原広報広聴課長","answer":"今回はダブりではありませんで、８月１日号の定例号は、それはそれとしてやらせていただいております。今回の実験は１０円３８銭で込みで出ておりますが、全戸配布ですと１０円から１３円の間で、それぞれ事業者が見積もりを出してきているところです。","id":"exchange-027"},{"speaker":"宮崎委員","kind":"質問","question":"新聞折込みでやった場合の２０万世帯中何世帯ぐらい届いていたか。どのぐらいになるのか、そこら辺の比較というか、それはどうか尋ねました。","respondent":"中川原広報広聴課長","answer":"今までの新聞折込みですと７５％ぐらいが新聞折込みで、あとの部分を、広報スタンドとか、公共施設とか、郵便局、浴場組合、今年はスーパーマーケットにも置いていただいたりとか、そういったところで補足をさせていただいているというのが現状です。","id":"exchange-028"},{"speaker":"宮崎委員","kind":"質問","question":"今度の全戸配布で、基本的には１００％自宅に届くということになるでしょうけれども、今、そういう前提でいいのか、どうなのか。そこのところは、どういうふうに考えられているのか尋ねました。","respondent":"中川原広報広聴課長","answer":"区民の方にどの程度届いているかという見込みにつきましては、８０歳代の方は、情報を見ていただくのかなと考えています。広報紙だけではありませんので、いろいろな媒体を使ってお届けしているのかなとは考えております。","id":"exchange-029"},{"speaker":"宮崎委員","kind":"意見","question":"今までの新聞折り込みだと７５％は届いているけれども、駅等で見ているのではないかと、こういうところがはっきりしないわけです。意見だけですとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-030"},{"speaker":"須貝委員","kind":"質問・要望","question":"３日以内に届かないと先に押さえられてしまっているというのでは、募集の記事、今後も配っていただくような努力をしてほしいと求めました。意見だけ述べさせていただきました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-031"},{"speaker":"林委員","kind":"質問","question":"目的の中にある、新聞講読者数が減少しているというのが、トライをするための大きい要因になっているように聞こえるし、減少しているというのは、今も意見が出たけれども、どのぐらい減少しているとつかんでいるわけか尋ねました。","respondent":"中川原広報広聴課長","answer":"昨年までは１５万６,０００部を新聞折込みしていたんですが、もう１回、新聞販売店に全部調査を行ったんです。そして、今年度から１３万８,０００部に精査いたしました。","id":"exchange-032"},{"speaker":"林委員","kind":"質問","question":"１軒で１紙だけというお宅が多いんでしょうけれども、新聞に対して、そうではないですか。広報紙が届かないという苦情はあったんか尋ねました。","respondent":"中川原広報広聴課長","answer":"販売店もそんなに把握はできませんので、新聞講読者数が減っているというのは、検討しなければいけない時期がきたのかなということです。先ほども意見を言っていただきましたが、いろいろな方法を検討して、何が一番できることなのかを考えることが必要かなと思った次第です。","id":"exchange-033"},{"speaker":"林委員","kind":"質問","question":"区民の感情というか、感覚というか、そういうことはお聞きになったことはあるんか尋ねました。","respondent":"中川原広報広聴課長","answer":"年に何回か、新聞を取っていないので広報紙が届かないのだけれども、それは不公平ではありませんかという電話をいただくことがあります。","id":"exchange-034"},{"speaker":"林委員","kind":"質問","question":"年に何人かから、そういう情報が届いていないと来るとすれば、４０回出したとして、１００円で送って、１人４,０００円ではないですか。反対しているわけではないんですが、そういうことも考えられるのではないのかと思うんですけれども、そこまでは突っ込んでやらないんか尋ねました。","respondent":"中川原広報広聴課長","answer":"それも検討の方策の一つには入っています。担当者と案を検討はしているんですが、いろいろなご意見をいただきますので、すみません。","id":"exchange-035"},{"speaker":"林委員","kind":"質問","question":"区の情報が届かないということを訂正していくということも一つのトライなんでしょうから、２、３日で実施されることでやってほしいと求めました。お願いしておきます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-036"}]},{"id":"topic-03","title":"の平成２２年１０月３日執行、品川区長選挙・品川区議会議員補欠選挙執行計画","agenda":"の平成２２年１０月３日執行、品川区長選挙・品川区議会議員補欠選挙執行計画","exchanges":[{"speaker":"土井委員","kind":"質問","question":"今回の選挙にも、当然、使われるものと思います。初めて使ったわけですから、何なりというものが活用されるべきだと、どのようにお考えか尋ねました。","respondent":"早津選挙管理委員会事務局長","answer":"したがって、ほぼ予定どおりに出来ていたんですが、比例区のほうが１７％という２倍以上の読み取れなかったということが起こりました。もう一つの課題になります、比例区のほうが、なぜ２倍以上のリジェクト率になったのかについては、現在、業者側も含めて、今、検証しています。","id":"exchange-037"},{"speaker":"土井委員","kind":"質問","question":"素直に読み取ったんですから、取れなかったものについては、人手をしっかりとかけなければいけないものになるわけです。まだ私の思いだけですから、また数十人が立候補されるでしょうから、何とかしてもらいたいと思うものですから。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-038"}]},{"id":"topic-04","title":"所管事務調査に入ります。 今年度の所管事務調査項目につきましては、６月２９日の委員会で、「都区制度のあり方」","agenda":"所管事務調査に入ります。 今年度の所管事務調査項目につきましては、６月２９日の委員会で、「都区制度のあり方」","exchanges":[{"speaker":"林委員","kind":"意見","question":"極端に言うと３人とか、５人とか、お願いします。そんな言葉があるかどうかわからないけれども、研修をしているのか、その辺を聞かせてくださいとの意見を述べました。","respondent":"榎本人事課長","answer":"やはり定年退職１００人を超えてくるのが、あと７年ぐらいは続きますので、１００人を超える採用の数がある程度必要になってくるかなと考えています。経験者採用も織りまぜながら、３０歳代の経験者採用の職員も増やしながら…","id":"exchange-039"},{"speaker":"林委員","kind":"質問","question":"伝えていこうという意識を、若い人たちに伝えていくことは大事なことだろうと思うんですけれども、そういう仕組みになっているのかどうか。若手が品川区を支えてくれないと困るわけで、そういうこともやらなければいけないと思うんですけれども、その辺はいかがか尋ねました。","respondent":"榎本人事課長","answer":"２年目以降、１年間の研修計画を、部下に合った形をつくってもらうということをしています。人事考課も、それぞれの組織体に合った人事考課制度というのがありますので、そういう形できちんと運用していきたいという考えです。","id":"exchange-040"},{"speaker":"林委員","kind":"質問","question":"最後にちょっとお聞きしたいんですけれども、ここ５年ぐらいで、退職していった人はいらっしゃるんですか。品川区はもうすっかりわかって嫌だと出て行った人ではなくて、ここ５年ぐらいに採用した人でです。","respondent":"榎本人事課長","answer":"二年でやめた方がいますし、事務職はあまり記憶がないので、そんなにやめるという形はないです。ただし、ちょっと病気になる方もいますので、例えば５年間の新採を見ますと、たしか二、三人は、メンタル系の病気になった方がいた記憶があります。","id":"exchange-041"},{"speaker":"土井委員","kind":"質問","question":"私に言わせれば、２年過ぎてしまうと、もう枠にはめるのは皆さんはお上手ですから、すとんと枠にはまってしまうのではないかなと。こちら側の発想も変えられる研修みたいなものに活用できないのかと、こんな思いがあるんですが、どうか尋ねました。","respondent":"榎本人事課長","answer":"前年度の新人も一緒に加わって、自分たちが１年前に発表したときにはどうだったのかがわかるような形、そういう交流の場も設けてあります。チューター制度、メンター制度ということで、直属の上司ではない人に意見を言えるというようなところを増やしていきたいと考えています。","id":"exchange-042"},{"speaker":"土井委員","kind":"意見","question":"今のお話は、非常にいいと思うんですよね。こういう研修で、きちんと発言をする新人をつくってもらいたいと考えていますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-043"},{"speaker":"須貝委員","kind":"意見","question":"平成２２年度に新人として入った方、かなり応募者が殺到したという話を聞いております、倍率も高かったと。それで、優秀な人材もかなり応募してこられたという話も聞きますが、その辺の実態について聞かせてくださいとの意見を述べました。","respondent":"榎本人事課長","answer":"今年、１８９人の採用のうち、９３人は保育士ということで、保育士につきましては、実技選考も踏まえて選考してきております。いろいろな区の意見調整をしながら、最終的によりよいまちづくりをしていくというところをＰＲという意味で、こういう特集も組まれているです。","id":"exchange-044"},{"speaker":"須貝委員","kind":"質問","question":"そういうシステムとか、また、どこに相談に行きなさいというようなケアする人はいるんですか。その辺について、説明を求めました。","respondent":"榎本人事課長","answer":"そのほか、メンタル面につきましては、それぞれの２年目、３年目研修でも、メンタル的なものを、カウンセラーのほうからいろいろと話をしていただく。それからあとは採用５年目でも、カウンセラーのほうへ相談すれば大丈夫ですよという意味も含めて…","id":"exchange-045"},{"speaker":"須貝委員","kind":"質問・要望","question":"成績上では優秀な方も、品川区目指して大勢の方が来られるということはありがたいんですが、ぜひ、メンタルの面に対して、ほんとうにやめる人が出ないようなケアを、今後もしっかりと取り組んでほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-046"},{"speaker":"本多委員","kind":"質問・要望","question":"行政マンとしてのサービス業をレベルアップするというか、もしそういう部分が品川区の研修の中で、独自性みたいなものがあれば教えていただきたい。ひとつ、そのあり方の部分だけ、できる範囲でお答えしてほしいと求めました。","respondent":"榎本人事課長","answer":"区の研修と特別区の研修の連携というか、２３区の共通の部分も取り上げて、基本の部分をやっているというのが基本的なスタンスです。２０倍から３０倍ぐらいの倍率がありますので、面接も２回ありますし、かなり価値があるものだと認識しております。","id":"exchange-047"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/212618?Template=document&Id=1860#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2010-01-01&TermEnd=2010-12-31"}],"sourceMeta":{"pages":0,"characters":45841,"voices":114}},{"id":"h22-20100824-6","meetingId":"h22-cm08","date":"2010年8月24日","dateIso":"2010-08-24","committee":"区民委員会","time":"午後１時０３分～午後２時４４分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を26件整理しています。","topics":[{"id":"topic-01","title":"を行います。 住民基本台帳カードの不正取得","agenda":"を行います。 住民基本台帳カードの不正取得","exchanges":[{"speaker":"渡辺委員","kind":"確認","question":"どのようなことが想定されるのか、それともう１点、運転免許証の確認専用システムのソフトウエアはどのようなソフトウエアなのでしょうか。オンラインか何かで本人確認をするソフトウエアなのか、どのようなものか説明を求めました。","respondent":"梶戸籍住民課長","answer":"暗証番号は２つあるんですが、その２つの番号を、あるいは顔写真等がそのパソコンの中で出てくるというものです。ちなみに、こちらのはネットにはつながっていないので、ソフトウエアをパソコンにダウンロードして、それで確認をするといったシステムです。","id":"exchange-001"},{"speaker":"菊地副委員長","kind":"質問","question":"はいといって出てくるような、一般的なインターネットの活用とはまた違うんだと思うんですけれども、その辺をもう少し詳しく教えてくれませんか。","respondent":"梶戸籍住民課長","answer":"私どもで品川区住民基本台帳カードを不正取得された例なんですけれども、ご本人に確認すると、運転免許証は紛失していないんです。ただ、それにつきましては、確認がとれていません。","id":"exchange-002"},{"speaker":"菊地副委員長","kind":"質問","question":"だから、その情報のもとになるものというのは、ソフトウエアを入れることで、どういうふうに取得できるのかということなんです。だから、その辺のことをちょっと教えてもらいたいんです。","respondent":"梶戸籍住民課長","answer":"専用ソフトウエアのお話ですね。","id":"exchange-003"},{"speaker":"菊地副委員長","kind":"意見","question":"ソフトウエアがどうなるのかというところから、運転免許証の情報との意見を述べました。","respondent":"梶戸籍住民課長","answer":"運転免許証のＩＣチップの中に入っている情報というのは、運転免許証の表書きに書いてあります生年月日と運転免許証の種類と顔写真がＩＣチップの中に入っているということです。","id":"exchange-004"},{"speaker":"菊地副委員長","kind":"質問","question":"それはわかったんですけれども、一般的な質問、私がそのソフトウエアを入れれば、その情報がとれるかというと、とれないわけですよね。情報の発信元となるところとの連携というのか何というのか、そこら辺の区との関連がよくわからないんです。","respondent":"梶戸籍住民課長","answer":"ソフトウエア自体は多分市販されていないものですし、ダウンロードを通常はできるようなものではありません。正しい運転免許証、専用ソフトウエアを入れないと、中身は読み取れないということです。","id":"exchange-005"},{"speaker":"菊地副委員長","kind":"質問","question":"そうすると、それにかかわる経費が発生してくるものになるんでしょうか。国なり、都から出てくるような経費ということなんですか、そこを最後に。","respondent":"梶戸籍住民課長","answer":"１つが大体３,０００円程度です。カードリーダーだけです。","id":"exchange-006"},{"speaker":"山内委員","kind":"質問・要望","question":"住民基本台帳カードのことについて、関連で教えていただきたいんですけれども、今回はこの偽造運転免許証を本人確認資料として確認をしたと。写真つきでなければ、保険証になるけれども、住民基本台帳カードを取得するに当たっての本人確認を今後はどういう形でしていくのか。","respondent":"梶戸籍住民課長","answer":"年金の手帳ですとか、保険証とか、そういったものを２点以上確認するという形になってあります。ご協力いただければ、運転免許証以外にもう１点何かありますかというお尋ねをしていって、少し確認を強化していきたいと考えているところです。","id":"exchange-007"},{"speaker":"山内委員","kind":"質問・要望","question":"写真つきでないものは２点というお話でした。今これだと確認するシステムが多分整っていないと思うんですが、国に対してどのような要望をしていくのか、その辺の流れを教えてほしいと思います。","respondent":"梶戸籍住民課長","answer":"あくまでも２点以上の場合は、強制ということでは進められないと思うんです。今まで以上に２点確認につきましても、区民のご協力を得ながら、確認強化に力を入れていきたいと考えているところです。","id":"exchange-008"},{"speaker":"山内委員","kind":"質問","question":"ですから、パスポートを提出された際にはどうするのかということを今聞いているんです。その辺を説明を求めました。","respondent":"梶戸籍住民課長","answer":"パスポートのほうの偽造という部分が出てくるかわからないんですけれども、確認ソフトウエアはございません。写しをとって、パスポート以外に何かございませんかと提示を求めたり、個人しか知り得ないような内容を聴取するような方法もあわせてとっていくです。","id":"exchange-009"},{"speaker":"山内委員","kind":"質問・要望","question":"では、最後に要望。そうでないと、またこのような同じ事件になるということも考えられるので、その辺はよろしくお願いしたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-010"}]},{"id":"topic-02","title":"所管事務調査に移ります。 今年度の所管事務調査の項目につきましては、６月２９日の委員会で、「町会支援のあり方」","agenda":"所管事務調査に移ります。 今年度の所管事務調査の項目につきましては、６月２９日の委員会で、「町会支援のあり方」","exchanges":[{"speaker":"石田委員","kind":"質問","question":"町会会計アドバイザー制度についてお伺いしたいんですが、３回で、３回以降の部分を教えてほしいと求めました。そこをちょっとお願いします。","respondent":"中山地域活動課長","answer":"原則として２時間ということですから、これはアドバイザー派遣が必要な状況だということになれば、そこから有料でという形は考えておりません。さらによろしいのではないかというような話なので、３回までと考えたんですが、実はそこまで至っていない。","id":"exchange-011"},{"speaker":"石田委員","kind":"意見","question":"もう１点が、掲示板なんですが、町会の掲示板とふれあい掲示板の差は一体何なのかというのがまず１点。その辺の掲示板のあり方というのを、区としてアドバイスできる部分というのがあるのかなと思って、その辺の現状をお知らせほしいと求めました。","respondent":"中山地域活動課長","answer":"設置主体からすれば、町会そのものにいろいろな考え方があるので、統一していくというのは難しい部分があろうかと思います。一定の助言の中での整理はできようかと思いますが、基本として主体が違う部分はある程度お任せするしかないだろうということになろうかと思います。","id":"exchange-012"},{"speaker":"山内委員","kind":"質問","question":"２０４町会で、町会に加入されている方というのは何人いらっしゃるんですか。そこから説明を求めました。","respondent":"中山地域活動課長","answer":"大体６割強というふうに、地域差が若干ありますけれども、加入率は６０％強かなと。会費を払っている会員数と世帯数を考えると、大体６２％ぐらいの数字というのが区内の平均値になっておりますので、半分以上の方は加入している。","id":"exchange-013"},{"speaker":"山内委員","kind":"質問・要望","question":"基本的に６割、基本的にこの６割という数字を役所から見た場合、今のままではいけない部分というのがあると思うんです。その辺をちょっと教えてほしいと求めました。","respondent":"中山地域活動課長","answer":"お答えはできませんが、紙だけでないようなご支援もしていかなければということで、加入につながらないという悩みをご支援申し上げたいということで。１つはマンション対策みたいなものをしっかり考えていきながら、また、加入率を上げていきたいと考えております。","id":"exchange-014"},{"speaker":"山内委員","kind":"質問・要望","question":"もう少し調査・研究をしていただいた中で、そういうところに努めてほしいと求めましたので、よろしくお願いしたいと思います。そういったことへの対応は役所として考えているのか、その辺をちょっと教えていただきたいと思うんです。","respondent":"中山地域活動課長","answer":"町会会館を使っての葬儀と考えますと、利用が減った、あるいはなくなったという声も聞いております。そういう会合以外の場合でも会員が喜んで使えるものの支援をしていきたいという考えで、その辺の申し出を基本に助成はしていきたいと考えております。","id":"exchange-015"},{"speaker":"山内委員","kind":"質問","question":"その場合はどうなんですか。それでもこれは葬祭として認めて、葬祭の範囲の助成をするということでいいんか尋ねました。","respondent":"中山地域活動課長","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-016"},{"speaker":"渡辺委員","kind":"質問・要望","question":"結構善意のボランティアですから、その辺を最初に伺いたいのと、２つの見方があると思います。加入促進という点で、力の入れ方、最初は感覚的な２点を伺えればと思います。","respondent":"中山地域活動課長","answer":"ご質問の２点目にあるような特定の方だけのご負担で、さまざま申し上げたようなご支援、そういう中に町会の意味合いというんでしょうか。町会を支援し、今後とも一番重要な進め方の１つかなと考えていますので…","id":"exchange-017"},{"speaker":"渡辺委員","kind":"質問・要望","question":"伺った中で、区民サービスを提供する当てが一番見えるというんですか、商店街だと思っています。限られた職員定数の中で、地域センターによるマネージャー的な、マネジメントの位置づけのこれからの考え方を伺いたいと思います。","respondent":"中山地域活動課長","answer":"協働の切り口でさまざまな支援をする中で、どう算定するかと考えると、１つの課題とさせていただければと思います。先ほど来出ている町会が非常に大事だということをまず認識する中で、これは１つの支援として、町会への大きな支援と思います。","id":"exchange-018"},{"speaker":"渡辺委員","kind":"質問・要望","question":"その辺をどのように考えられているのか教えていただきたい。委託事業的なものの窓口であったりするならば、そこをきっかけに加入促進につながるのかなという思いがあって、その辺のお考えを聞かせてください。","respondent":"中山地域活動課長","answer":"何らかの形できちんとそういう声を聞き、それをどうやって改善していくかという対応をしていきたいと思います。非常に頼りになると思われるところの１つというのは、わかりやすい、加入されていない方にもきちんと伝える工夫はしていきたいと思います。","id":"exchange-019"},{"speaker":"菊地副委員長","kind":"質問","question":"１つだけ教えてもらいたいんですけれども、２０４の町会のうち、町会会館を持っている町会というのはどれぐらいなんか尋ねました。","respondent":"中山地域活動課長","answer":"どこまでを会館というかというのは、実は微妙なところがあるんですが、ざっくり言うと、約８０です。所有そのものが町会かというと、結構微妙な会館というのもあるんですが、そういうものも含めて考えていくと、約８０です。","id":"exchange-020"},{"speaker":"菊地副委員長","kind":"質問","question":"１つは８０の町会がとりあえず会館を持っていらして、今５０町会が法人化ということですから、法人化が進められてきたんだと思うんです。どういうふうに、何か特例事項でも設けられるのかどうか、その辺ちょっとお聞かせ願いたいんですが。","respondent":"中山地域活動課長","answer":"いろいろな対応があるということを言い出すと細かくなってしまう。こういう場合は柔軟にやってまいりますので、５年以内であっても、この期間で十分やっていけるものと考えています。","id":"exchange-021"},{"speaker":"高橋委員","kind":"質問・要望","question":"そういうことに関してどのようにお考えで、もう１つ、それを教えていただきたい。そういうことが起きないように、区としては今後どうされていくかというのをちょっとお伺いしたい。","respondent":"中山地域活動課長","answer":"ご支援をしていくということで、基本として会計の適正化をしっかり支援していきたいと思いますが、それ以外の内部のところについて。会の運営等について、今回のような会計士のような方も含めた助成の体制をさらに強化するべきといった考えをとっています。","id":"exchange-022"},{"speaker":"山内委員","kind":"質問","question":"内容の２番、今スポーツごみ拾いの話がありましたけれども、これはちょっとおかしくないかなと思うんです。まず、この内容をどういう形で決めていったのか、その辺をちょっと教えてほしいんですけれども。","respondent":"諸岡商業・観光課長","answer":"ごみ拾いだけが目的ではありませんし、まちをきれいにしながら、その間にまちを再発見していただこうという取り組みです。わりと整然と実施され、参加された方も非常に充実感があって楽しめたということを感想として伺っているものです。","id":"exchange-023"},{"speaker":"山内委員","kind":"意見","question":"まさか協会があるとは思ってもいなかったので、それの説明を事前にしていただければ、ありがたかったなと。要は、散歩をしながら、いろいろと発見をしていくといった意味での取り組みだと受けとめしますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-024"},{"speaker":"渡辺委員","kind":"質問","question":"最後、５番の主催などの運営のところなんですが、品川区の位置づけ、よくあるのが、主催、共催、後援という段階があるんですが、これは今回協賛という、珍しく見えたんですが、この辺の経緯を説明を求めました。","respondent":"諸岡商業・観光課長","answer":"今申し上げましたスポーツごみ拾いについても、皆さん方でお決めになられたということで、主体的に実施されたものです。その意味で一歩踏み出して、経費等も支援させていただいているということで、協賛という形にさせていただいているものです。","id":"exchange-025"},{"speaker":"菊地副委員長","kind":"質問・要望","question":"１つだけ聞きたいんですけれども、国勢調査が地域振興事業部の管轄になっているんですけれども、今、全国的にも問題になっている例の高齢者の方の所在不明という話、品川区はどうなっているのかがわからないので、教えていただきたいんですけれども。","respondent":"梶戸籍住民課長","answer":"所管的には、高齢者福祉課、高齢者いきがい課で所管しています。聞いた話では、品川区では１００歳以上の方について、所在不明の方はいらっしゃらないという形では聞いております。","id":"exchange-026"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/397696?Template=document&Id=2588#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2010-01-01&TermEnd=2010-12-31"}],"sourceMeta":{"pages":0,"characters":30987,"voices":75}},{"id":"h22-20100824-7","meetingId":"h22-cm08","date":"2010年8月24日","dateIso":"2010-08-24","committee":"厚生委員会","time":"午後１時０２分～午後２時４５分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を29件整理しています。","topics":[{"id":"topic-01","title":"品川総合福祉センター本部の改修工事と（仮称）八潮南特別養護老人ホーム整備","agenda":"品川総合福祉センター本部の改修工事と（仮称）八潮南特別養護老人ホーム整備","exchanges":[{"speaker":"南委員","kind":"確認","question":"今は６階の食堂で行っているんだけれども、それはそのほうが、むしろいいのではないかなと思って伺っていました。ここの施設を建てた２８年前には複合型施設だったんだけれども、全くクリアされていることなのかどうか、ちょっと確認をしたいと思います。","respondent":"冨岡高齢者福祉課長","answer":"それ以外の部分については居ながらの工事ということで、業者に配慮していただいて、工夫して工事を進めていただくことになるかと考えております。これから実施設計に細かく入っていくところですが、あらあら、各フロアということでオーケーのように聞いているところです。","id":"exchange-001"},{"speaker":"南委員","kind":"質問","question":"定員もそうですけれども、そういう点でも、もう少し検討を要する部分もあるかなと思って伺っていました。終末という言い方をしていいのでしょうか、やっぱり最後の最後まで人間としての尊厳というのを守っていってほしいと、施設建設にあたって。","respondent":"冨岡高齢者福祉課長","answer":"申しわけございません。２,０００万円ということで、実施設計費を考えていたわけでございまして、いろいろトータルで考えて２,０００万円という形で計算をしたところです。","id":"exchange-002"},{"speaker":"南委員","kind":"質問・要望","question":"この枠がどういうふうに変化するのか、正確にしたいと思って、再質問するんです。具体的にどういう法律のもとで、そのあたりの根拠を教えていただきたいということで、質問したつもりです。","respondent":"冨岡高齢者福祉課長","answer":"実施設計といいますのは、改修するにあたっての設計費ですので、どれだけ工事をするか見積もっていくための細かい設計費が２,０００万円です。トータルで２,０００万円で足りるかですけれども、区は２,０００万円を出したということで、一定の負担割合で出したです。","id":"exchange-003"},{"speaker":"三上委員","kind":"提案","question":"最初にちょっと確認だけさせてもらいますけれども、両施設の運営は品川福祉総合センターが行うということで理解しておいていいのか、どうか。ですから、この施設については検討されているのかどうかということについて、いかがか尋ねました。","respondent":"冨岡高齢者福祉課長","answer":"１点目の、これは議会でお決めいただくことですが、指定管理の候補者としては品川総合福祉センターを予定しています。品川総合福祉センターが検討しているか、ご提案があったということにつきましては、法人のほうに伝えてまいりたいと考えているところです。","id":"exchange-004"},{"speaker":"三上委員","kind":"質問・要望","question":"ですから、問題がないように対応すべきだと、いろいろ言ってきたりしてきているわけです。そういうキーマンであってほしいと思いますので、ぜひとも、十分にそういった点で対応できることを引き継いでいってほしいと求めました。","respondent":"冨岡高齢者福祉課長","answer":"指定管理につきましては、条例の制定、それから指定管理者の選定ということで、また議会の会議等で上程する予定です。それから、珪藻土、しっくい塗料の利用につきましては、私どもももちろん、真摯に受けとめて研究させていただきたいと考えているところです。","id":"exchange-005"},{"speaker":"大沢委員","kind":"質問・要望","question":"高齢の方は順応するのに時間がかかると思うんですけれども、そこら辺のところを、どういうふうにお考えなんでしょうか。指定管理ということで運営を委託しているわけですけれども、品川区の担当部局でおわかりになるところを教えてほしいと求めました。","respondent":"冨岡高齢者福祉課長","answer":"さまざまな状態像の方を４０名、区と協力し合いながら検討して決めてまいりたいと考えていますので、軽々には答えを申し上げられない状況です。いずれにしましても、高齢者は非常に環境に敏感に反応される場合もありますので…","id":"exchange-006"},{"speaker":"山元委員","kind":"質問・要望","question":"ちょっと教えていただきたいのは、やはり、「入所者の特性に応じた対応が可能なようにバリエーションを用意する」とありますが、具体的に何か考えていることがあれば、ちょっと教えてほしいと求めました。","respondent":"永尾障害者福祉課長","answer":"逆に、一人っきりになると不安になってしまうというような状況も見られますので、その方の状況に合わせて選択できるというような意味で考えております。","id":"exchange-007"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"なぜそんなことを伺ったかと言いますと、具体例を見ておりますと、正直、どうしてここまで放っておいたのかなという印象を、すごく受けるんです。その財源内訳というんですか、どこから幾らというふうにお考えになっているのか、ご説明いただけますか。","respondent":"冨岡高齢者福祉課長","answer":"当然、法人と区とでパートナーシップをとりながら支援をするという立場から、今回も対応しています。ただ、区については一定の支援をするという予定です。","id":"exchange-008"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"今は委託ですか、民設民営ですか、この話がうまくいっているのかなと率直に感じたんです。９,５００万円かからないからこっちなんだという説明だと思うんですけれども、ちょっとこの辺を、もう少し詳しくご説明いただけますか尋ねました。","respondent":"冨岡高齢者福祉課長","answer":"それから、障害者支援施設かもめにつきましては、対応については、当然あるかと思いますが、現在のままで工事をしていくです。基本的に考えられるのは、ほかの方が利用できませんので、その辺はこの二つに分けて見積もったです。","id":"exchange-009"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"最後にもう少し伺いたいのは、（仮称）八潮南特別養護老人ホームを４０ベッド使って工事をするということですけれども、いつごろから行っていたのか。あわせて、どうして仕切りがあってプライバシーに配慮したいと思ったのか、改善を図るというその理由、また区の考え方を、改めて伺いたいと思います。","respondent":"冨岡高齢者福祉課長","answer":"議論についての検討がいつぐらいからかですけれども、実施計画を進めていくためには、もう少し具体的な対応が必要になってくるという中において。２人分ほど増える予定になっておりますけれども、その中で、個室的なしつらえというものでお願いしたいと思っているところです。","id":"exchange-010"},{"speaker":"南委員","kind":"質問","question":"伺えばよかったんですけれども、改修工事着工が来年８月ですよね。それはいつごろやろうとしているのか、ちょっとその辺だけ伺いたいと思います。","respondent":"冨岡高齢者福祉課長","answer":"議会に報告をさせていただいて、それに基づきまして、今後、地域への説明会等あると思いますが、今、私どもは、法人からいつとは聞いておりません。","id":"exchange-011"}]},{"id":"topic-02","title":"夜間対応型訪問介護事業所を活用した２４時間対応システムモデル事業","agenda":"夜間対応型訪問介護事業所を活用した２４時間対応システムモデル事業","exchanges":[{"speaker":"南委員","kind":"質問","question":"いろいろな努力をされるんだろうと思うんですけれども、その辺についての認識はどうなのか、ちょっと一つ伺いたい。この現況がどのようになっているのかも、あわせてこの機会に伺いたいと思います。","respondent":"冨岡高齢者福祉課長","answer":"実施をしております夜間の事業と、２４時間の見守りということで、今後対応していくということになるかと思います。現在、７月で１２人ということで、今後とも拡大を図ってまいりたいと考えているところです。","id":"exchange-012"},{"speaker":"南委員","kind":"質問・要望","question":"高齢者ですから、１カ月、２カ月すぐに過ぎてしまうのではないかと思うんです。確かに次期の介護計画をつくるにあたってのモデルですから、ちょっと１点、教えてほしいと求めました。","respondent":"冨岡高齢者福祉課長","answer":"夜間のサービスも実際にベースとして実施しているわけでございまして、そういうことも含めて入らせていただきたいという趣旨での、今回のご報告です。それから、件数につきましては、１２名は要支援者でございまして、ほかに要介護者のほうは８３名が利用されているという状況で…","id":"exchange-013"},{"speaker":"南委員","kind":"質問・要望","question":"トータルで８３名というのは、合わせて９５名がご利用されているということで伺っていいのか、どうか。それから、区としての短期間のモデル実施についての見解、それがさっきの答弁にはなかったので、そこを聞きたいです。","respondent":"冨岡高齢者福祉課長","answer":"要支援者につきましては、入院からお帰りになって要支援の状態になったとか、要介護の方が要支援になったとか。今回の４カ月の部分について、どう考えるかですけれども、これから進めてまいりたいと思っているところです。","id":"exchange-014"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"社会問題化している高齢者の安否確認や見守り、地域課題であると書いてありますけれども、区の問題意識を伺いたいと思うんです。２４時間サービス提供とありますけれども、何かボタンを押すと何かがどうなって、そこをご説明いただけますか尋ねました。","respondent":"冨岡高齢者福祉課長","answer":"これは中身とちょっと絡んでまいりますが、夜間対応型訪問介護事業所に受信機がございまして、ナースコールと同じような形で反応がある。ほとんど同じで、ナースステーションが夜間対応型訪問介護事業所のキーステーションというところで、こういう形で事業を展開していくです。","id":"exchange-015"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"モデル実施ですから、どういう問題意識や課題を、その内容がよくわからないんです。どうなのか、また検証する仕組みを考えていらっしゃるのか、ご説明ほしいと求めました。","respondent":"冨岡高齢者福祉課長","answer":"２４時間対応と申しますのは、それから社会的な支援といったサービスが、地域包括ケアの研究会の報告がなされたわけです。それに基づきまして、一定の、議会に対する対応をすると考えているところです。","id":"exchange-016"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"では、緊急だとどうなるのか、その辺を伺いたい。そんな話も伺うので、その点の問題意識というのはどんなふうにお考えになっていらっしゃるのか、お聞かせほしいと求めました。","respondent":"冨岡高齢者福祉課長","answer":"後のほうのモデル実施の負担の部分ですが、国庫の１０分の１０ということですので、それで負担する。夜間対応型訪問介護では、では２４時間対応型にした場合、１０分の１０の事業になっているんだと理解しています。","id":"exchange-017"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"高齢者の安否確認、今、非常に厳しい生活を強いられているわけですよね。減免制度であったり、最後に、利用者の生活実態や要望にしっかり目を向けてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-018"}]},{"id":"topic-03","title":"平成２２年度高齢者福祉週間行事","agenda":"平成２２年度高齢者福祉週間行事","exchanges":[{"speaker":"南委員","kind":"確認","question":"１０１歳のところでは、改めて確認ですけれども、というお話でしたよね。介護サービスを受けていない１００歳以上の方なんてあり得ないんか尋ねました。","respondent":"冨岡高齢者福祉課長","answer":"７０歳以上のひとり暮らしの方と高齢者世帯を訪問していただいていますので、ひとり暮らしで１００歳以上の方、そこでカバーできるです。受けていない方もおいでになるということで、介護保険プラス後期高齢者医療を調べまして、すべて利用されているということがわかったです。","id":"exchange-019"}]},{"id":"topic-04","title":"ふくしまつり２０１０","agenda":"ふくしまつり２０１０","exchanges":[{"speaker":"中塚副委員長","kind":"質問・要望","question":"それを前提に伺いたいと思うんですけれども、どんな事情、どんな理由があったのかなということなんです。どういうふうに説明しているのか、どういった意見が挙がっているのか、その現状も教えていただけますか尋ねました。","respondent":"永尾障害者福祉課長","answer":"実施する際に、昨年は、ゲートシティ周辺と大崎の駅周辺で実施をいたしました。同様にやることを検討をしてきたんですけれども、ちょっと場所を変えるか、どうするかという検討を行ってきました。","id":"exchange-020"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"今までどういうふうに借りていたのかも含めて、率直に伺っているんですけれども、その経過を教えてほしいと求めました。やっぱりもとのあそこの場所がよかったのかどうか、障害者団体の方の意見や要望がよくわからなかったので、ちょっとどんな意見が挙がっていたのか。","respondent":"木下健康福祉事業部長、永尾障害者福祉課長","answer":"もう既に１８回ぐらいになるのでしょうか、内容が拡充といいますか、拡大されてきました。今回、ふくしまつりとしては別の場所で展開するほうが望ましいのではないかということで、判断をさせていただいたです。 確かに、今まで、大崎の駅をおりて自然と歩けば、そこにバザーの会場等があったので、誘導とかは特に必要ありませんでした。中小企業センターの前には模擬店を出す予定ですので、中にも入っていただくような誘導を…","id":"exchange-021"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"第１回みんなのまちフェスタということで、気持ちを新たにという感じなのか、要するに企画として変わったわけですよね。だれがどう答えるのかよくわからないんですけれども、企画として第１回とした、ご説明いただけますか尋ねました。","respondent":"永尾障害者福祉課長","answer":"そういう関係で横の連携はとっておりましたけれども、区民の皆さんにも、みんなのまちフェスタというものを考えたものです。まちづくりについて、みんなのまちについて、考えていく機会になったらと考えています。","id":"exchange-022"},{"speaker":"南委員","kind":"質問・要望","question":"大事なことですから、ずっと発展してきたそこが何分の１かに薄まっては、やっぱり発展とはなっていかないんだろうと思うんです。意味がないわけですから、もっともっと健康福祉事業部として、このチラシにもしっかり存在がわかるような内容にするべきではないかと思ったんです。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-023"},{"speaker":"南委員","kind":"質問・要望","question":"ですから、ちょっとそこのところは正確にしたほうがいいのかと思ったので、確認の質問をしたいと思いました。事前にＪＴに問い合わせをして確認しておけばよかったのかもしれないけれども、そこだけ確認したいと思って、質問させてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-024"},{"speaker":"南委員","kind":"確認","question":"ですから、１カ月半ぐらい経った中で、その活用について検討しているという中身がわからないわけですよね。どういう中身かはあれなんですけれども、区の企画のところに確認をして、答弁をしたというわけですね。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-025"},{"speaker":"南委員","kind":"質問","question":"ですから、今日、委員長にお許しをいただいて質問することになったわけです。ですから、企画のところが、あちらと直接交渉した中での情報提供だというところは、それはそれであったにしても…。","respondent":"冨岡高齢者福祉課長","answer":"すみません、私が聞いたのは経理課管財係です。要するに用地交渉はそこがいたしますので、その観点でしか、私は聞いておりません。","id":"exchange-026"},{"speaker":"南委員","kind":"確認","question":"みんなそれぞれが正確な情報を持って臨まないといけないかなと、反省も込めて、思ったところです。そういうことで、出所の確認と、そこがわかったということで、とりあえず納めたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-027"},{"speaker":"三上委員","kind":"確認","question":"自分が先方に確認したとかということであったとしても、用地の担当部はどこなのかとなったら、総務委員会になるわけですよ。もう一度確認する必要があるのではないのかということを、総務委員会の場で確認してもらいたいということであれば、聞いていました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-028"},{"speaker":"南委員","kind":"質問・要望","question":"区のほうがどういう確認ルートをとってこられたのかも、やっぱり知る上で、その他のところで質問させていただいたということです。ですから、その辺については、ぜひ、そういうことで受けとめてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-029"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/360687?Template=document&Id=3276#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2010-01-01&TermEnd=2010-12-31"}],"sourceMeta":{"pages":0,"characters":30639,"voices":84}},{"id":"h22-20100824-8","meetingId":"h22-cm08","date":"2010年8月24日","dateIso":"2010-08-24","committee":"建設委員会","time":"午後１時０３分～午後３時１０分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を47件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"要望していたわけですけれども、説明会とあわせて行うということはなかなか行われてこなかったと思っているんですけど、今回説明会を行うことにした理由というのがあれば教えていただきたいなというふうに考えています。","respondent":"藤田水とみどりの課長","answer":"案が確定し、景観計画になりますと、その中で色やデザインについては皆様方が建築をする際にある一定程度の制限をかけることになります。そういった面から、きちんとした説明をやはりする必要があるであろうということで今回説明会を行うというような形で進めるものです。","id":"exchange-001"},{"speaker":"安藤委員","kind":"質問","question":"区民生活にすごく影響を与えるようなことは、パブリックコメントとあわせてこれからも積極的に説明会の開催をお願いしたいなというふうに思います。街並みがどう変化するのかというのがちょっと、どういうふうに変化するのか、その辺についてはいかがか尋ねました。","respondent":"藤田水とみどりの課長","answer":"やはりわかりやすいのが一番だというふうに考えてありますので、うまく発信できるような形を考えながら進めていきたいというふうに考えてあります。１冊読むのはなかなか難しいということもありまして、その辺をご覧いただきながらご理解をいただければなというふうに思います。","id":"exchange-002"},{"speaker":"安藤委員","kind":"質問","question":"よろしくお願いします。そういったなるべく多くの区民の皆さんに参加してもらうための何か工夫というんですかね、その点に関してはいかがか尋ねました。","respondent":"藤田水とみどりの課長","answer":"説明会等を含めて、いろんな形でのご案内の方法はあろうかと思います。多くの方に参加いただきたいと私どもは考えております。","id":"exchange-003"},{"speaker":"安藤委員","kind":"質問・要望","question":"要望なんですが、要望ですけれども、。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-004"},{"speaker":"阿部副委員長","kind":"質問","question":"私から１点お伺いします。今やっているものがどうなるとか、何かちょっと区民の日常の意識とこの計画をつなぐための簡単な資料が１枚、いかがか尋ねました。","respondent":"藤田水とみどりの課長","answer":"区のほうでは平成１７年からさまざまなことに取り組んできたというようなことを前提に広報「しながわ」のほうでお知らせをしながらやっていくという…わかりやすい、最終的に取りまとめをするときにもその辺には十分留意しながら進めていきたいと思ってあります。","id":"exchange-005"},{"speaker":"阿部副委員長","kind":"意見","question":"品川区でこういう流れですというだけじゃなくて、もう少し方向的にわかったほうが多分理解しやすいだろうなと思ったので言わせていただきました。ご理解ほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-006"},{"speaker":"藤原委員","kind":"質問","question":"羽田空港移転問題協議会というのは歴史が長いですし、うちも区長、副区長が出られていますよね。改めて伺いますが、羽田空港跡地まちづくりに対して、品川区は関係をどういうふうにしていくんか尋ねました。","respondent":"山崎マスタープラン担当課長、片田防災まちづくり事業部長","answer":"そういった意味で近接区としまして品川区もそこに参画をして、区としての意見等々を今まで申し上げてきたものです。品川区としましては、その跡地の部分については特に積極的な意見を持って協議会でという部分… エリアについては大田区のエリアになってくるわけですけれども、そういう意味で区が直接跡地をどうするということはありません。今課長のほうから説明しました第１ゾーン地区、海老取川に面したエリアですけれども…","id":"exchange-007"},{"speaker":"藤原委員","kind":"質問","question":"まちづくりの進め方で、第１ゾーンは大田区だということで、大田区が取得するように動いているわけでしょう。品川区はどういうふうにかかわっていくのかという質問をしたので、もっとストレートに報告はしましたけど、その辺ははっきりしてほしい。","respondent":"片田防災まちづくり事業部長","answer":"直接跡地に取り組むということは全くありませんけれども、今の発着回数の１.５倍ぐらいの発着が見込まれると、そういう中でアジア。そういうものを今現在検討し始めた状況ですので、品川区のほうとしては…","id":"exchange-008"},{"speaker":"藤原委員","kind":"質問","question":"ハブ空港ができて、まちづくりをするというのは別な話。じゃなくて、このできた跡地まちづくり、跡地に関して品川区はどういうふうにかかわり合っていくんですか、跡地に関してということです。","respondent":"片田防災まちづくり事業部長","answer":"跡地に対しては、今品川区はかかわる考えは持っていません。","id":"exchange-009"},{"speaker":"安藤委員","kind":"質問","question":"羽田空港移転問題協議会の件について伺いたいんですが、品川区ではだれが、どういう方が何人参加しておられたのか。その場で今回跡地利用はおやりになっていると言ったんですが、品川区はこの議題に対しては、どのような発言をしてきたのかお伺いします。","respondent":"山崎マスタープラン担当課長","answer":"羽田空港移転問題協議会の関係ですけれども、先ほども若干ご説明を申し上げましたけれども、発足は昭和５２年です。それから、協議会の委員としましては、品川区では副区長が出席をしていると、こういうような状況です。","id":"exchange-010"},{"speaker":"安藤委員","kind":"質問","question":"品川区はどんな発言をしてきたのかなというのをお伺いしたいのと、品川区にかかわる影響というのはどういうふうなものがあるのか。それはどれぐらい増えて、それがどういうふうに品川区の区域内を通って区民生活に影響があるのかとか、そういうのをちょっとお伺いしたいと思います。","respondent":"山崎マスタープラン担当課長","answer":"新たに年間５０万トンの取り扱いが可能となるということで、昼間２５トン、深夜・早朝で２５トンという内訳です。それから、そうした周辺アクセス道路の整備も進んでいるというような状況です。","id":"exchange-011"},{"speaker":"安藤委員","kind":"質問・要望","question":"今お話があったんですが、ハブ化、国際化における中央環状品川線を品川区はどう位置づけているのかというのをもう少しお伺いしたいなと思います。羽田空港移転問題協議会の中で、紹介できるところがあれば教えていただきたいなと思います。","respondent":"片田防災まちづくり事業部長","answer":"それとあと、移転問題協議会が先日行われまして一連の説明がございましたけれども、特に私ども品川区のほうから意見は出しませんでした。護岸整備に当たってもいろんな支援をお願いしたいといったような大田区のほうからのいわゆる主体的な要望が国に出されたというような経過が…","id":"exchange-012"},{"speaker":"安藤委員","kind":"質問","question":"護岸もつくられて、かなり大規模な事業だなという印象を持ちましたが、この時代にここまでやるのかという印象を私は持ったわけですね。ちょっとあまり大がかりな計画なので、総事業費というのは幾らぐらいなのか説明を求めました。","respondent":"片田防災まちづくり事業部長","answer":"その絵の中で、こういう計画を考えていると。例えば第２ゾーンについては民間活用とか、いろいろ考えられているところですので、このように理解しています。","id":"exchange-013"},{"speaker":"安藤委員","kind":"質問","question":"国際都市品川ということで、いろいろ民間もつくっていますけど、区内にあちこちホテルとかあるわけです。そういう大きな施設がドーンとこの近くにできますと、何か閑古鳥が鳴いたりとかしないのかなと思うんですが、そこら辺の影響はどうなんか尋ねました。","respondent":"片田防災まちづくり事業部長","answer":"そういうところは明らかにしたり、またお示ししていきたいと、このように考えてあります。やはり注視していく必要がありますし、それを十分見極めながらまちづくりを進めていきたいということで考えているところです。","id":"exchange-014"},{"speaker":"渡部委員","kind":"質問・要望","question":"移転というのに関してはこうあるべきかなという気がするんですけれど、羽田空港移転問題協議会自体はいつまで続くのか。でもって、ここに今の段階で品川区が入っていることについてお示しいただきたい。","respondent":"山崎マスタープラン担当課長、片田防災まちづくり事業部長","answer":"先ほどもご説明申し上げましたとおり、そういうものは引き続き注視していかなければいけないということで理解をしております。そういった立場でこれまでも臨んでまいりましたし、これからも臨んでいくです。 今後の羽田空港移転問題協議会としての対応ですけれども、基本的にやはり事業を進めるに当たっては、羽田空港移転問題協議会の中でやっていくというような立場をとりたいと考えております。","id":"exchange-015"},{"speaker":"渡部委員","kind":"意見","question":"第１ゾーンは大田区が何か利用するということなんですけど、逆に意見を、区の中で例えばこういう施設が欲しいとかといった場合に言えるのか。例えばこういう委員会の中でも、けんけんがくがくな議論ができるのかなという気がするんですけど、可能性というのはいかがでしょうとの意見を述べました。","respondent":"片田防災まちづくり事業部長","answer":"観光とか、共同施設というようなものを利用できる立場があるとすれば、それに対していろんな意見を申し述べるということは十分可能だと考えております。","id":"exchange-016"},{"speaker":"渡部委員","kind":"質問","question":"せっかくその羽田空港移転問題協議会に入っているわけですから、何らかのメリットというものがあるといいのかなというふうに感じます。例えば同じ協議会の中でも参加するべきもの、区も空港とかかわってくるんだよというのがあればお伝えいただければなというふうに思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-017"},{"speaker":"阿部副委員長","kind":"質問","question":"そういった説明は今後この２カ月でご説明を予定されているかどうかということを伺いたい。そういうことを考えれば、そういったことを事前に何らかの形で説明をする予定はあるのかということをまず１点聞きたい。","respondent":"山崎マスタープラン担当課長","answer":"先日東京都のほうからルートの公表の解禁という形で８月１８日の本協議会の素案の決定とあわせまして、そういった通知をいただいています。今のところは影響なしですけれども、そうした内容も含めまして、周知という点で留意してまいりたいというふうに考えてあります。","id":"exchange-018"},{"speaker":"阿部副委員長","kind":"質問","question":"国際化になって、品川区の活性化のために攻めていかなきゃいけないというような話は多分建設委員会でもここ数年出ていたことだと思うんですね。これはこれとして、品川として現在国際化を受けて何をしていくんだというのは、どこか影響部署でも何でも検討というのは何かされているんですかね。","respondent":"山崎マスタープラン担当課長","answer":"現在庁内におきまして、羽田空港国際化プロジェクトチームというのを立ち上げて、いろんな角度から検討しています。大田区、それから大田区の観光協会、東京都等と連携を図りながら取り組みを検討しておりまして。","id":"exchange-019"},{"speaker":"阿部副委員長","kind":"質問","question":"これはどちらも、観光のほうも国際化プロジェクトチームも区民委員会ということでよろしいんか尋ねました。","respondent":"山崎マスタープラン担当課長","answer":"国際化というテーマで観光面によらずに、多角的な方面でプロジェクトチームを立ち上げているというのが一つです。それから、二つ目の観光面は、先ほどの大田区と連携をしながら、一定方向のまとめに至る手前まで来ていますよです。","id":"exchange-020"},{"speaker":"阿部副委員長","kind":"質問","question":"全庁的なプロジェクトチームのタイムスケジュールと、どういった段階で、どういう形でまとめが出てくるのかということを説明を求めました。","respondent":"山崎マスタープラン担当課長、藤田水とみどりの課長","answer":"現在具体的なスケジュールにつきましては、大変申しわけないです。伺っておりませんというか、年度内に一定というようなところまでしか伺っておりません。 ただいま庁内のプロジェクトの関係に、私ども水とみどりの課が入っております。国際ターミナルができるということで、到着ロビーのところに、それについては１０月のオープンに合わせてやりたいということで考えてあります。","id":"exchange-021"},{"speaker":"安藤委員","kind":"質問","question":"大田区もありますし、東京都はパブリックコメントの制度があるのかちょっと私知らないんですけど、品川区だけじゃないんですよね。それはかかわっている自治体がどういうふうに調整するのかとか、その辺がわからないので、そこだけ説明を求めました。","respondent":"山崎マスタープラン担当課長","answer":"現在実施しておりますパブリックコメントにつきましては、国と東京都、大田区、品川区と同様のものです。ちなみに、昨日現在、９件の意見が参っているというようなことで伺っております。","id":"exchange-022"},{"speaker":"安藤委員","kind":"質問・要望","question":"確認ですが、スタートは品川区のパブリックコメントの要望に基づいてやりますけども、これは東京都がやるパブリックコメントということなんですかね。普通窓口というのは、入口は各国や大田区や品川区でやると、そういうことでよろしいんか尋ねました。","respondent":"山崎マスタープラン担当課長","answer":"委員おっしゃられたとおりです。","id":"exchange-023"},{"speaker":"藤原委員","kind":"確認","question":"改めて確認をしますが、あとこの何枚かあるうちのカッターのある部分が欠けちゃっても、ある程度掘ってここまで来たわけですよね。やっぱり完璧な状態にカッターをしないとだめなんか尋ねました。","respondent":"山崎マスタープラン担当課長","answer":"今回損傷が起きましたのは７月末の時点で、先ほどのセンター部分の９本ある一番出っ張った突起の真ん中の部分です。この状態で１００ｍほど今回も補修予定の位置までは掘削するんですけれども、カッターを交換するような補修方法をとるというように聞いてあります。","id":"exchange-024"},{"speaker":"藤原委員","kind":"確認","question":"ということは、ボーリング調査をしますよね。シールドがある位置の確認とか、あとその後の地盤とかの調査をして、人が入れる立坑が掘れるかどうかの調査をしていくんか尋ねました。","respondent":"山崎マスタープラン担当課長、片田防災まちづくり事業部長","answer":"ボーリング調査につきましては、先ほど説明しました本格的なシールドマシンのビット、歯を交換する作業のための事前調査という位置づけです。そこの掘った先の地盤の状況等々を調査しまして… それから、一応予定としては平成２５年中の工事の期限ですので、まだどの程度かかるか。地域のほうにも説明しつつ、地域の皆さんにも安心していただくような方法で対応していきたいと考えていますので、よろしくお願いしたいと思います。","id":"exchange-025"},{"speaker":"藤原委員","kind":"質問・要望","question":"地域の方が不安にならないようにその辺の説明はちゃんとしていただきたいのと、今はシールドがとまっちゃっているわけですよね。それが、その分がイコール全体の工事の予定から、その期間が全部おくれちゃうというふうに考えてよろしいんか尋ねました。","respondent":"片田防災まちづくり事業部長、岩田都市環境事業部長","answer":"今の前提ではおくれない方法で検討できないかということを考えております。ただ、場合によってはおくれるところについてはきちっと説明をしていきたいと思います。 大体今６カ月ぐらいかかるんじゃないかと言われているんですけど、この補修に。あるいは延びずに済むかというのが確定しますので、これがわかり次第、また当委員会に報告することになると思います。","id":"exchange-026"},{"speaker":"安藤委員","kind":"質問・要望","question":"今修復に６カ月ぐらいかかるんじゃないかというお話があったんですが、大体修復をいつぐらいに始める予定ですかね。首都高速道路株式会社ということなんですけれども、税金は１円も投入されないということでよろしいんか尋ねました。","respondent":"山崎マスタープラン担当課長","answer":"それから、スケジュールですが、そうしたことが特定されて、スケジュールが判明してくるという関係です。ということで、現時点でははっきりしたスケジュールが明確じゃないです。","id":"exchange-027"},{"speaker":"安藤委員","kind":"質問","question":"東京都のシールドマシンもこれから通過するわけですけれども、そちらへの影響というのはどうなのか、それはどうなんか尋ねました。","respondent":"山崎マスタープラン担当課長、岩田都市環境事業部長","answer":"東京都のマシンにつきましては、本日時点で位置関係が居木橋を少し過ぎたところということで、まだ目黒川の下を通過中です。基本問題につきましては慎重に対応しているということですけれども、順調に動いているということですので… このメーカーが８kmを一発で押せるようなものを設計したので、一発で行こうということに変わったんですね。ただ、ビットが折れてとれてしまったことだけははっきりしているということです。","id":"exchange-028"},{"speaker":"安藤委員","kind":"確認","question":"ちょっと説明の確認なんですが、シールドマシンは二つの会社で違うものを使っているということなんですが、それはちょっと私認識不足でした。同様な地点を東京都のほうが後から通るとなると、それにかかわらず東京都のほうは全くとまらずに普通に進む考えなんか尋ねました。","respondent":"山崎マスタープラン担当課長、原委員長、柏原住宅担当課長","answer":"その際に、２kmを進んでシールドマシンの歯がマイナス１２mm、こういったものを東京都のマシンが想定していたそうです。… ほかに。ご発言がないようですので、本件を終了いたします。 抽選結果の通知は、１０月１５日までに申込者の方に発送する予定です。なお、募集の冊子につきましては、準備が整い次第区議会事務局を通じまして委員の皆…","id":"exchange-029"},{"speaker":"安藤委員","kind":"質問","question":"単身でも入れるんでしょうか。家賃は同様のグレードの民間住宅と比較して、どれぐらいの水準なんでしょうか、説明を求めました。","respondent":"柏原住宅担当課長","answer":"一番広い部屋で８２平米、３ＬＤＫで８２平米というのがありますが、１３万円から１７万円程度というような形。場所によっては１９万円から２０万円程度の家賃のところもありますので、安いところでは１万円、５万円程度安い家賃を設定しています。","id":"exchange-030"},{"speaker":"安藤委員","kind":"質問・要望","question":"区営住宅とかだと１年間有効な登録順位を決めて、入居件数があるんですが、何か借上と建設が一緒になっちゃっているんですね。２００９年度で４８人入って、全体の応募数は２２１人という、ここ３年ぐらいの内訳などを教えていただきたい。","respondent":"柏原住宅担当課長","answer":"それから、昨年度も２３件ということで、大体二十数件程度毎年この３住宅で、ファミーユ下神明と西五反田ですね、こちらのほうで入居されていると。残り半分程度が６月に募集しております借上型やそれ以外の建設型の住宅ということになっております。","id":"exchange-031"},{"speaker":"安藤委員","kind":"質問・要望","question":"平成１８年度、平成１７年度もわかれば教えていただきたいのと、そこら辺でいかがか尋ねました。","respondent":"柏原住宅担当課長","answer":"何世帯あるかというのは、正確なところで数字としては押さえておりませんが、実際パンフレットは２,０００部ほど印刷しております。別な、ちょっとアンケートをとった際に、そういったところも含めていろんなところで周知活動をこれからもしていきたいというふうに思っておりま…","id":"exchange-032"},{"speaker":"安藤委員","kind":"質問・要望","question":"要望なんですけども、広報が９月１日にあって、その日を含めた申込期間が１週間ぐらいしかないんですね。ぜひお伺いしたいんですが。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-033"},{"speaker":"松澤委員","kind":"質問","question":"簡単なことなんですけど、区民住宅のあき家入居予定者ということで、抽選日が１０月５日、抽選番号を１０月１日に発送するというんですけど、抽選の仕方、さっき課長がこうやっていたからガラガラでやるのかなと思うんですが、ちょっと抽選のやり方というのを説明を求めました。","respondent":"柏原住宅担当課長","answer":"優遇条件というのがありまして、例えば３倍の条件というのがあったりしますけれども、要するに確率的に多く出るような形にして番号を多く入れる。やりまして、その当たった番号につきましては、１５日ごろまでにはご本人のところに発送するという流れになります。","id":"exchange-034"},{"speaker":"松澤委員","kind":"質問","question":"そのときに、当然応募した方は全員目の前ですよね、いるということでよろしいんか尋ねました。","respondent":"柏原住宅担当課長","answer":"昼間の時間帯ですので、皆さんがいらっしゃるというのはなかなかちょっと難しい。それからあと、一般の方に来ていただいて署名をしていただいて、確かに間違いないですと立会人の方に署名いただくというやり方をしております。","id":"exchange-035"},{"speaker":"松澤委員","kind":"質問","question":"私は何回応募しても当たらないのでという方がいらっしゃったものですから、こういうところで聞くのはどうかとは思ったんですけど。そうすると、何月何日、どこそこの会場でやっていますから来てくださいというご案内はされているということでよろしいですね。","respondent":"柏原住宅担当課長","answer":"はい、おっしゃるとおりでございまして、いつ、どこでやっているというのはちゃんとご案内をしております。","id":"exchange-036"},{"speaker":"安藤委員","kind":"質問・要望","question":"確認なんですが、リフォーム助成とか、そういった事業の紹介というのは入っているのか。ふくしまつりのほうは、例年大崎ニューシティのほうでやっていたと思うんですが、こちらに移った理由をお聞かせほしいと求めました。","respondent":"柏原住宅担当課長","answer":"平成２２年度につきましては、予定していたホールであるとか、どうしても場所が押さえられなかったという事情もあったようです。こちらのほうでも予定を入れておりましたので、それでは一緒にやるということで、こちらのほうで開催したいという流れです。","id":"exchange-037"},{"speaker":"阿部副委員長","kind":"質問・要望","question":"確認が１点です。ちょうど足した内容になっているのか、新たにつけ加わったものとか、なくなったものとかがあるのかどうかということを教えていただきたい。","respondent":"柏原住宅担当課長","answer":"形としてはこういった形で続けていければと考えておりますが、いろんなことを考えていくとして次回につなげられるというふうに思っております。今までやっていたものをそのままコラボレーションするという言い方がいいのかもしれませんけれども…","id":"exchange-038"},{"speaker":"阿部副委員長","kind":"質問","question":"せっかく課長が実行委員長なんですから、これが第１回ですし、課長みずからがぜひ言葉の力で盛り上げてほしいと求めました。第１回ですからもう少し、中でやっている方も気持ちよくできると思うので、そこはどうでしょう。","respondent":"柏原住宅担当課長","answer":"ハードもソフトもありますので、こういうふうに考えられるとか、そういったところも見ていただきたいというのが一番大きなところです。ましてや、お互いが認識し合えるところがありますので、そういったところが大きな目的だというふうに私どもは考えております。","id":"exchange-039"},{"speaker":"若林委員","kind":"確認","question":"別に予算をもらっていたということを確認したいのと、１１日が雨天の場合は、ふくしまつりは中止ということになるのかどうか。その二つ。","respondent":"柏原住宅担当課長","answer":"共同といいますか、細かい話をしますと、ふくしまつりの予算をこちら側に執行委任していただく形で一緒に執行するという流れでやる予定です。雨天の場合、ふくしまつりのほうは…","id":"exchange-040"},{"speaker":"若林委員","kind":"質問","question":"実行委員長としてでしょうから、当然どういうことに、意気込みも含めてしたいのか。ネーミングは、それについての意見を説明を求めました。","respondent":"柏原住宅担当課長、齋藤道路公園課長","answer":"いろいろ内部でも検討いたしました。内部で検討したところ、ハードもソフトも含めたみんなのフェスタだということで、こういった名前にさせていただいたというところです。 支援者の方たちが大変高齢化していて、３０万円しかないのにしながわ中央公園でやるというのは、とてもじゃないけどできない。岩田部長はあと１年半で退職ですが、回数を重ねて…","id":"exchange-041"},{"speaker":"安藤委員","kind":"質問・要望","question":"ちょっと区民の声なども含めて、もう一度ここに道をつくるという経過というんですかね、経緯というのをもう一度改めて教えてほしいと求めました。もしあれば教えていただきたいのと、あと完成イメージが２月ということなんですけど、どのように井戸を利用するのか。","respondent":"品川防災整備担当課長","answer":"経過についてご説明いたします。まだ少し近隣住民の皆様と調整をしている最中ですので、今後また照明については具体的な話が出てくるかというふうに考えております。","id":"exchange-042"},{"speaker":"安藤委員","kind":"意見","question":"井戸は近隣の方のボランティアの方が世話をされているということなので、ぜひ活用できる方向で、今保育園の方のご好意で利用していただいているんですけれども、できるような方向でお願いいたしますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-043"},{"speaker":"阿部副委員長","kind":"質問","question":"１回のほうがコスト的に安く済まないかなと思ったんですけれども、なぜ二段階で整備することになったのか理由を教えてください。コストの違いとか、もし計算されていたら説明を求めました。","respondent":"品川防災整備担当課長","answer":"それから２月についてですが、ここの植栽を植えるのは２月が最適だということで、完成を２月という形にしております。それから、コストの差ですが、これは申し訳ございませんが、計算してございません。","id":"exchange-044"}]},{"id":"topic-02","title":"その他","agenda":"その他","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"どんな住宅が建設されたのか教えていただきたいのと、どうなっているのか、最高価格と最低価格も教えてほしいと求めました。販売状況は、現時点でどうなっているのか説明を求めました。","respondent":"三宅都市開発課長","answer":"すみません、ちょっとお答えするようなものを今持ち合わせていませんでして、一応資料としてお配りしておると思います。","id":"exchange-045"},{"speaker":"安藤委員","kind":"質問・要望","question":"それはそれでいただきたいんですが、ぜひ簡単でもいいですから、委員会報告としてお願いしたいんですけれども。重ねていかがか尋ねました。","respondent":"岩田都市環境事業部長","answer":"議会の場でその内容を行政が説明するということは、まさに民間事業のＰＲをすることになってしまいますので、不適切ではないかと考えます。","id":"exchange-046"},{"speaker":"安藤委員","kind":"質問・要望","question":"お願いしたいのと、ぜひ前向きに検討していただきたいなというふうに思っていますけれども、何かそれが報告できなくなった理由とかがあるのか。私は報告していただきたいなと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-047"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/483234?Template=document&Id=3986#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2010-01-01&TermEnd=2010-12-31"}],"sourceMeta":{"pages":0,"characters":37725,"voices":140}}]);
